use std::path::{Path, PathBuf, Component};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{SystemTime, UNIX_EPOCH, Duration};
use std::fmt;

use clap::{Arg, Command, ArgAction, value_parser, ValueHint};
use clap_complete::{Shell, shells, generate as generate_completion};
use clap_mangen::Man;
use base64::{Engine as _, engine::general_purpose::STANDARD as BASE64};
use sha2::{Sha256, Sha512, Digest};
use chrono::{Utc, DateTime, Local, TimeZone};
use flate2::write::GzEncoder;
use flate2::Compression as FlateCompression;
use percent_encoding::percent_decode_str;
use url::form_urlencoded;

// Embedded assets
const FAVICON_SVG: &str = include_str!("../../data/logo.svg");
// For style.css we need to load from our fetched copy? We have /tmp/style.css but we can embed original CSS that we fetched.
// Let's read from file at compile time if exists, else fallback.
const STYLE_CSS: &str = include_str!("../assets/style.css");

// We'll also need to embed style.css, but original style.css is at /tmp/style.css. To get it, we need to copy it to assets/style.css or include directly.
// Actually assets/style.css doesn't exist; we have data/logo.svg. We'll create assets/style.css file with original CSS content (we have fetched).
// For now we will try to include from a file we will create during compile? Simpler: embed the CSS content by reading file at runtime? But we need const.
// We'll use include_str with path relative to src: we need assets/style.css to exist. We'll create it later.

// Version
const VERSION: &str = "0.32.0";

#[derive(Clone, Debug, PartialEq, Eq)]
enum SortingMethod { Name, Size, Date }
#[derive(Clone, Debug, PartialEq, Eq)]
enum SortingOrder { Asc, Desc }
#[derive(Clone, Debug, PartialEq, Eq)]
enum ColorScheme { Squirrel, Archlinux, Zenburn, Monokai }
#[derive(Clone, Debug, PartialEq, Eq)]
enum SizeDisplay { Human, Exact }
#[derive(Clone, Debug, PartialEq, Eq)]
enum OnDuplicate { Error, Overwrite, Rename }
#[derive(Clone, Debug)]
enum MediaType { Image, Audio, Video }

impl fmt::Display for SortingMethod {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self { Self::Name => write!(f,"name"), Self::Size => write!(f,"size"), Self::Date => write!(f,"date") }
    }
}
impl std::str::FromStr for SortingMethod {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s { "name"=>Ok(Self::Name), "size"=>Ok(Self::Size), "date"=>Ok(Self::Date), _=>Err(format!("invalid sorting method")) }
    }
}
impl std::str::FromStr for SortingOrder {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s { "asc"=>Ok(Self::Asc), "desc"=>Ok(Self::Desc), _=>Err(format!("invalid order")) }
    }
}
impl std::str::FromStr for ColorScheme {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s { "squirrel"=>Ok(Self::Squirrel), "archlinux"=>Ok(Self::Archlinux), "zenburn"=>Ok(Self::Zenburn), "monokai"=>Ok(Self::Monokai), _=>Err(format!("invalid scheme")) }
    }
}
impl std::str::FromStr for SizeDisplay {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s { "human"=>Ok(Self::Human), "exact"=>Ok(Self::Exact), _=>Err(format!("invalid")) }
    }
}
impl std::str::FromStr for OnDuplicate {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s { "error"=>Ok(Self::Error), "overwrite"=>Ok(Self::Overwrite), "rename"=>Ok(Self::Rename), _=>Err(format!("invalid")) }
    }
}

#[derive(Clone, Debug)]
struct AuthEntry {
    username: String,
    password_hash_type: Option<String>, // None = plain, Some("sha256") etc, or empty password?
    password: String, // plain password or hash hex
}

#[derive(Debug)]
struct Config {
    verbose: bool,
    temp_dir: Option<PathBuf>,
    index: Option<String>,
    spa: bool,
    pretty_urls: bool,
    port: u16,
    interfaces: Option<String>,
    auth: Vec<AuthEntry>,
    route_prefix: Option<String>,
    random_route: bool,
    random_route_value: Option<String>,
    no_symlinks: bool,
    hidden: bool,
    default_sorting_method: SortingMethod,
    default_sorting_order: SortingOrder,
    color_scheme: ColorScheme,
    color_scheme_dark: ColorScheme,
    qrcode: bool,
    upload_files: Option<Option<String>>, // None = disabled, Some(None) = enabled for root, Some(Some(dir)) = enabled for specific dir
    web_upload_concurrency: usize,
    chmod: Option<u32>,
    directory_size: bool,
    mkdir: bool,
    media_type: Option<MediaType>,
    raw_media_type: Option<String>,
    on_duplicate: OnDuplicate,
    rm_files: Option<Option<String>>,
    enable_tar: bool,
    enable_tar_gz: bool,
    enable_zip: bool,
    compress_response: bool,
    dirs_first: bool,
    title: Option<String>,
    headers: Vec<(String, String)>,
    show_symlink_info: bool,
    hide_version_footer: bool,
    hide_theme_selector: bool,
    show_wget_footer: bool,
    tls_cert: Option<String>,
    tls_key: Option<String>,
    readme: bool,
    disable_indexing: bool,
    enable_webdav: bool,
    size_display: SizeDisplay,
    file_external_url: Option<String>,
    serve_path: PathBuf,
    serve_path_is_file: bool,
}

fn parse_auth_str(s: &str) -> Option<AuthEntry> {
    // format username:password, username:sha256:hash, username:sha512:hash, username: (empty)
    // split at first colon?
    if s.is_empty() { return None; }
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() == 1 {
        // just username? original example shows "bill:" in file but also could be without colon? We'll treat as username with empty password?
        return Some(AuthEntry { username: parts[0].to_string(), password_hash_type: None, password: "".to_string() });
    } else if parts.len() == 2 {
        // username:password (plain)
        let username = parts[0].to_string();
        let password = parts[1].to_string();
        if username.is_empty() { return None; }
        // empty password allowed? e.g. bill: -> password empty
        return Some(AuthEntry { username, password_hash_type: None, password });
    } else if parts.len() == 3 {
        // username:hash_type:hash
        let username = parts[0].to_string();
        let hashtype = parts[1].to_string();
        let hash = parts[2].to_string();
        if hashtype != "sha256" && hashtype != "sha512" { return None; }
        if username.is_empty() { return None; }
        return Some(AuthEntry { username, password_hash_type: Some(hashtype), password: hash });
    } else {
        // more than 3 parts: password may contain colon? Original spec says username:password simple, so password could contain colon? But to handle, rejoin remaining?
        // If hashtype in second part is sha256/sha512, then treat rest as hash (but hash shouldn't contain colon)
        // Otherwise treat everything after first colon as password
        let username = parts[0].to_string();
        if username.is_empty() { return None; }
        if parts[1] == "sha256" || parts[1] == "sha512" {
            let hashtype = parts[1].to_string();
            let hash = parts[2..].join(":");
            return Some(AuthEntry { username, password_hash_type: Some(hashtype), password: hash });
        } else {
            let password = parts[1..].join(":");
            return Some(AuthEntry { username, password_hash_type: None, password });
        }
    }
}

fn check_auth(entry: &AuthEntry, provided_password: &str) -> bool {
    match &entry.password_hash_type {
        None => {
            // plain compare
            entry.password == provided_password
        },
        Some(ht) => {
            if ht == "sha256" {
                let mut hasher = Sha256::new();
                hasher.update(provided_password.as_bytes());
                let res = hasher.finalize();
                let hex = format!("{:x}", res);
                hex == entry.password.to_lowercase()
            } else if ht == "sha512" {
                let mut hasher = Sha512::new();
                hasher.update(provided_password.as_bytes());
                let res = hasher.finalize();
                let hex = format!("{:x}", res);
                hex == entry.password.to_lowercase()
            } else {
                false
            }
        }
    }
}

fn build_cli() -> Command {
    let mut cmd = Command::new("miniserve")
        .version(VERSION)
        .about("For when you really just want to serve some files over HTTP right now!")
        .arg(Arg::new("PATH")
            .help("Which path to serve")
            .env("MINISERVE_PATH")
            .value_hint(ValueHint::AnyPath))
        .arg(Arg::new("verbose")
            .short('v').long("verbose")
            .help("Be verbose, includes emitting access logs")
            .env("MINISERVE_VERBOSE")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("temp-directory")
            .long("temp-directory")
            .value_name("TEMP_UPLOAD_DIRECTORY")
            .help("The path to where file uploads will be written to before being moved to their correct location. It's wise to make sure that this directory will be written to disk and not into memory.\n\nThis value will only be used **IF** file uploading is enabled. If this option is not set, the operating system default temporary directory will be used.")
            .env("MINISERVER_TEMP_UPLOAD_DIRECTORY")
            .value_hint(ValueHint::DirPath))
        .arg(Arg::new("index")
            .long("index")
            .value_name("INDEX")
            .help("The name of a directory index file to serve, like \"index.html\"\n\nNormally, when miniserve serves a directory, it creates a listing for that directory. However, if a directory contains this file, miniserve will serve that file instead.")
            .env("MINISERVE_INDEX"))
        .arg(Arg::new("spa")
            .long("spa")
            .help("Activate SPA (Single Page Application) mode\n\nThis will cause the file given by --index to be served for all non-existing file paths. In effect, this will serve the index file whenever a 404 would otherwise occur in order to allow the SPA router to handle the request instead.")
            .env("MINISERVE_SPA")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("pretty-urls")
            .long("pretty-urls")
            .help("Activate Pretty URLs mode\n\nThis will cause the server to serve the equivalent `.html` file indicated by the path.\n\n`/about` will try to find `about.html` and serve it.")
            .env("MINISERVE_PRETTY_URLS")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("port")
            .short('p').long("port")
            .value_name("PORT")
            .help("Port to use")
            .env("MINISERVE_PORT")
            .default_value("8080")
            .value_parser(value_parser!(u16).range(0..=65535)))
        .arg(Arg::new("interfaces")
            .short('i').long("interfaces")
            .value_name("INTERFACES")
            .help("Interface to listen on")
            .env("MINISERVE_INTERFACE"))
        .arg(Arg::new("auth")
            .short('a').long("auth")
            .value_name("AUTH")
            .help("Set authentication\n\nCurrently supported formats:\nusername:password, username:sha256:hash, username:sha512:hash\n(e.g. joe:123,\njoe:sha256:a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3)")
            .env("MINISERVE_AUTH")
            .action(ArgAction::Append))
        .arg(Arg::new("auth-file")
            .long("auth-file")
            .value_name("AUTH_FILE")
            .help("Read authentication values from a file\n\nExample file content:\n\njoe:123\nbob:sha256:a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3\nbill:\n")
            .env("MINISERVE_AUTH_FILE")
            .value_hint(ValueHint::FilePath))
        .arg(Arg::new("route-prefix")
            .long("route-prefix")
            .value_name("ROUTE_PREFIX")
            .help("Use a specific route prefix")
            .env("MINISERVE_ROUTE_PREFIX"))
        .arg(Arg::new("random-route")
            .long("random-route")
            .help("Generate a random 6-hexdigit route")
            .env("MINISERVE_RANDOM_ROUTE")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("no-symlinks")
            .short('P').long("no-symlinks")
            .help("Hide symlinks in listing and prevent them from being followed")
            .env("MINISERVE_NO_SYMLINKS")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("hidden")
            .short('H').long("hidden")
            .help("Show hidden files")
            .env("MINISERVE_HIDDEN")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("default-sorting-method")
            .short('S').long("default-sorting-method")
            .value_name("DEFAULT_SORTING_METHOD")
            .help("Default sorting method for file list")
            .env("MINISERVE_DEFAULT_SORTING_METHOD")
            .default_value("name")
            .value_parser(["name","size","date"]))
        .arg(Arg::new("default-sorting-order")
            .short('O').long("default-sorting-order")
            .value_name("DEFAULT_SORTING_ORDER")
            .help("Default sorting order for file list")
            .env("MINISERVE_DEFAULT_SORTING_ORDER")
            .default_value("desc")
            .value_parser(["asc","desc"]))
        .arg(Arg::new("color-scheme")
            .short('c').long("color-scheme")
            .value_name("COLOR_SCHEME")
            .help("Default color scheme")
            .env("MINISERVE_COLOR_SCHEME")
            .default_value("squirrel")
            .value_parser(["squirrel","archlinux","zenburn","monokai"]))
        .arg(Arg::new("color-scheme-dark")
            .short('d').long("color-scheme-dark")
            .value_name("COLOR_SCHEME_DARK")
            .help("Default color scheme")
            .env("MINISERVE_COLOR_SCHEME_DARK")
            .default_value("archlinux")
            .value_parser(["squirrel","archlinux","zenburn","monokai"]))
        .arg(Arg::new("qrcode")
            .short('q').long("qrcode")
            .help("Enable QR code display")
            .env("MINISERVE_QRCODE")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("upload-files")
            .short('u').long("upload-files")
            .value_name("ALLOWED_UPLOAD_DIR")
            .help("Enable file uploading (and optionally specify for which directory)\n\nThe provided path is not a physical file system path. Instead, it's relative to the serve dir. For instance, if the serve dir is '/home/hello', set this to '/upload' to allow uploading to '/home/hello/upload'. When specified via environment variable, a path always needs to be specified.")
            .env("MINISERVE_ALLOWED_UPLOAD_DIR")
            .num_args(0..=1)
            .default_missing_value("true_marker")
        )
        .arg(Arg::new("web-upload-files-concurrency")
            .long("web-upload-files-concurrency")
            .value_name("WEB_UPLOAD_CONCURRENCY")
            .help("Configure amount of concurrent uploads when visiting the website. Must have upload-files option enabled for this setting to matter.\n\nFor example, a value of 4 would mean that the web browser will only upload 4 files at a time to the web server when using the web browser interface.\n\nWhen the value is kept at 0, it attempts to resolve all the uploads at once in the web browser.\n\nNOTE: Web pages have a limit of how many active HTTP connections that they can make at one time, so even though you might set a concurrency limit of 100, the browser might only make progress on the max amount of connections it allows the web page to have open.")
            .env("MINISERVE_WEB_UPLOAD_CONCURRENCY")
            .default_value("0")
            .value_parser(value_parser!(usize)))
        .arg(Arg::new("chmod")
            .long("chmod")
            .value_name("CHMOD")
            .help("Set unix file permissions of uploaded files\n\nThis takes an octal number, for example 0600. By default 0666 & ~umask is used to simulate the system's default behavior.")
            .env("MINISERVE_CHMOD"))
        .arg(Arg::new("directory-size")
