            .value_name("MEDIA_TYPE")
            .help("Specify uploadable media types")
            .env("MINISERVE_MEDIA_TYPE")
            .value_parser(["image","audio","video"]))
        .arg(Arg::new("raw-media-type")
            .short('M').long("raw-media-type")
            .value_name("MEDIA_TYPE_RAW")
            .help("Directly specify the uploadable media type expression")
            .env("MINISERVE_RAW_MEDIA_TYPE"))
        .arg(Arg::new("on-duplicate-files")
            .short('o').long("on-duplicate-files")
            .value_name("ON_DUPLICATE_FILES")
            .help("What to do if existing files with same name is present during file upload\n\nIf you enable renaming files, the renaming will occur by adding a numerical suffix to the filename before the final extension. For example file.txt will be uploaded as file-1.txt, the number will be increased until an available filename is found.")
            .env("MINISERVE_ON_DUPLICATE_FILES")
            .default_value("error")
            .value_parser(["error","overwrite","rename"]))
        .arg(Arg::new("rm-files")
            .short('R').long("rm-files")
            .value_name("ALLOWED_RM_DIR")
            .help("Enable file and directory deletion (and optionally specify for which directory)")
            .env("MINISERVE_ALLOWED_RM_DIR")
            .num_args(0..=1)
            .default_missing_value("true_marker"))
        .arg(Arg::new("enable-tar")
            .short('r').long("enable-tar")
            .help("Enable uncompressed tar archive generation")
            .env("MINISERVE_ENABLE_TAR")
            .action(ArgAction::SetTrue))
        .arg(Arg::new("enable-tar-gz")
            .short('g').long("enable-tar-gz")
            .help("Enable gz-compressed tar archive generation")
            .env("MINISERVE_ENABLE_TAR_GZ")
            .action(ArgAction::SetTrue))
