fn calculate_dir_size(path: &Path, config: &Config) -> u64 {
    // Recursive size
    let mut total = 0u64;
    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries.flatten() {
            let p = entry.path();
            if !config.hidden {
                if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
                    if name.starts_with('.') { continue; }
                }
            }
            if config.no_symlinks {
                if let Ok(meta) = fs::symlink_metadata(&p) {
                    if meta.file_type().is_symlink() { continue; }
                }
            }
            if let Ok(meta) = fs::metadata(&p) {
                if meta.is_dir() {
                    total += calculate_dir_size(&p, config);
                } else {
                    total += meta.len();
                }
            }
        }
    }
    total
}

struct HttpResponse {
    status_code: u16,
    reason: String,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

fn build_simple_text_response(status: u16, text: &str, config: &Config) -> HttpResponse {
    let body = text.as_bytes().to_vec();
    let mut headers = vec![
        ("Content-Type".to_string(), "text/plain; charset=utf-8".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            headers.push((k.clone(), v.clone()));
        }
    }
    HttpResponse {
        status_code: status,
        reason: match status { 200=>"OK", 404=>"Not Found", 403=>"Forbidden", 400=>"Bad Request", 500=>"Internal Server Error", 401=>"Unauthorized", _=>"OK" }.to_string(),
        headers,
        body,
    }
}

fn build_404(config: &Config, effective_path: &str, raw_path: &str, query_params: &HashMap<String,String>, headers: &HashMap<String,String>, method: String, client_ip: String, is_route_prefix_mismatch: bool) -> HttpResponse {
    // If route prefix mismatch, original returned 404 page with message "Route / could not be found" etc. Let's build similar.
    // Message: if is_route_prefix_mismatch, path is original raw_path? Or effective_path? Original for route prefix mismatch when accessing "/" returned "Route / could not be found" (effective_path is "/"? Actually when route prefix set and accessing "/", effective_path is "/" but route prefix check fails before. Original message: "Route / could not be found" for "/" request.
    // For general not found, message "Route /notfound could not be found"
    // For file not found when serving file directly? The disable indexing case returned "File not found."
    // So we have two versions.

    let route_display = effective_path;
    let title = "404 Not Found";
    let body_html = format!(r#"<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{prefix}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{prefix}/__miniserve_internal/style.css"><title>{title}</title><script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {{
                        if (name && name != "default") {{
                            localStorage.setItem('theme', name);
                            document.body.setAttribute("data-theme", name)
                        }} else {{
                            localStorage.removeItem('theme');
                            document.body.removeAttribute("data-theme")
                        }}
                    }}

                    // read theme from local storage and apply it to body
                    function loadColorScheme() {{
                        var name = localStorage.getItem('theme');
                        updateColorScheme(name);
                    }}

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script><script>const API_ROUTE = '{prefix}/__miniserve_internal/api';
                    let dirSizeCache = {{}};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {{
                        return fetch(API_ROUTE, {{
                            headers: {{
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            }},
                            method: 'POST',
                            body: JSON.stringify({{
                                DirSize: dir
                            }})
                        }}).then(resp => resp.ok ? resp.text() : "~")
                    }}

                    function updateSizeCells() {{
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {{
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {{
                                cell.dataset.size = dirSizeCache[target];
                            }} else {{
                                fetchDirSize(target).then(dir_size => {{
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                }})
                                .catch(error => console.error("Error fetching dir size:", error));
                            }}
                        }})
                    }}
                    setInterval(updateSizeCells, 1000);
                </script></head><body><div class="error"><p>404 Not Found</p><p>Route {route} could not be found</p><div class="error-nav"><a class="error-back" href="{root}">Go back to file listing</a></div><p class="footer">{footer}</p></div></body></html>"#,
        prefix = config.route_prefix.clone().unwrap_or_default(),
        title = title,
        route = route_display,
        root = config.route_prefix.clone().unwrap_or_else(|| "/".to_string()),
        footer = if config.hide_version_footer { "".to_string() } else { format!(r#"<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/{}</div>"#, VERSION) }
    );

    let body = body_html.into_bytes();
    let mut resp_headers = vec![
        ("Content-Type".to_string(), "text/html".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }

    HttpResponse {
        status_code: 404,
        reason: "Not Found".to_string(),
        headers: resp_headers,
        body,
    }
}

fn build_404_file_not_found(config: &Config, effective_path: &str, raw_path: &str, query_params: &HashMap<String,String>, headers: &HashMap<String,String>, method: String, client_ip: String) -> HttpResponse {
    // For disable indexing case
    let title = "404 Not Found";
    let body_html = format!(r#"<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{prefix}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{prefix}/__miniserve_internal/style.css"><title>{title}</title><script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {{
                        if (name && name != "default") {{
                            localStorage.setItem('theme', name);
                            document.body.setAttribute("data-theme", name)
                        }} else {{
                            localStorage.removeItem('theme');
                            document.body.removeAttribute("data-theme")
                        }}
                    }}

                    // read theme from local storage and apply it to body
                    function loadColorScheme() {{
                        var name = localStorage.getItem('theme');
                        updateColorScheme(name);
                    }}

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script><script>const API_ROUTE = '{prefix}/__miniserve_internal/api';
                    let dirSizeCache = {{}};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {{
                        return fetch(API_ROUTE, {{
                            headers: {{
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            }},
                            method: 'POST',
                            body: JSON.stringify({{
                                DirSize: dir
                            }})
                        }}).then(resp => resp.ok ? resp.text() : "~")
                    }}

                    function updateSizeCells() {{
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {{
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {{
                                cell.dataset.size = dirSizeCache[target];
                            }} else {{
                                fetchDirSize(target).then(dir_size => {{
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                }})
                                .catch(error => console.error("Error fetching dir size:", error));
                            }}
                        }})
                    }}
                    setInterval(updateSizeCells, 1000);
                </script></head><body><div class="error"><p>404 Not Found</p><p>File not found.</p><p class="footer">{footer}</p></div></body></html>"#,
        prefix = config.route_prefix.clone().unwrap_or_default(),
        title = title,
        footer = if config.hide_version_footer { "".to_string() } else { format!(r#"<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/{}</div>"#, VERSION) }
    );
    let body = body_html.into_bytes();
    let mut resp_headers = vec![
        ("Content-Type".to_string(), "text/html".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }
    HttpResponse {
        status_code: 404,
        reason: "Not Found".to_string(),
        headers: resp_headers,
        body,
    }
}

