    let dir_size_script = r#"<script>const API_ROUTE = '/__miniserve_internal/api';
                    let dirSizeCache = {};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {
                        return fetch(API_ROUTE, {
                            headers: {
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            },
                            method: 'POST',
                            body: JSON.stringify({
                                DirSize: dir
                            })
                        }).then(resp => resp.ok ? resp.text() : "~")
                    }

                    function updateSizeCells() {
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {
                                cell.dataset.size = dirSizeCache[target];
                            } else {
                                fetchDirSize(target).then(dir_size => {
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                })
                                .catch(error => console.error("Error fetching dir size:", error));
                            }
                        })
                    }
                    setInterval(updateSizeCells, 1000);
                </script>"#;

    // For upload, need extra JS
    let upload_script = if upload_enabled {
        format!(r#"<script>const CONCURRENCY = {};
                    window.onload = function() {{
                        // Constants
                        const UPLOADING = 'uploading', PENDING = 'pending', COMPLETE = 'complete', CANCELLED = 'cancelled', FAILED = 'failed'
                        const UPLOAD_ITEM_ORDER = {{ UPLOADING: 0, PENDING: 1, COMPLETE: 2, CANCELLED: 3, FAILED: 4 }}
                        let CANCEL_UPLOAD = false;

                        // File Upload dom elements. Used for interacting with the
                        // upload container.
                        const form = document.querySelector('#file_submit');
                        const uploadArea = document.querySelector('#upload_area');
                        const uploadTitle = document.querySelector('#upload_title');
                        const uploadActionText = document.querySelector('#upload_action_text');
                        const uploadCancelButton = document.querySelector('#upload_cancel');
                        const uploadList = document.querySelector('#upload_file_list');
                        const fileUploadItemTemplate = document.querySelector('#upload_file_item');
                        const uploadWidgetToggle = document.querySelector('#upload-toggle');

                        const dropContainer = document.querySelector('#drop-container');
                        const dragForm = document.querySelector('.drag-form');
                        const fileInput = document.querySelector('#file-input');
                        const collection = [];

                        dropContainer.ondragover = function(e) {{
                            e.preventDefault();
                        }}

                        dropContainer.ondragenter = function(e) {{
                            e.preventDefault();
                            if (collection.length === 0) {{
                                dragForm.style.display = 'initial';
                            }}
                            collection.push(e.target);
                        }};

                        dropContainer.ondragleave = function(e) {{
                            e.preventDefault();
                            collection.splice(collection.indexOf(e.target), 1);
                            if (collection.length === 0) {{
                                dragForm.style.display = 'none';
                            }}
                        }};

                        dropContainer.ondrop = function(e) {{
                            e.preventDefault();
                            fileInput.files = e.dataTransfer.files;
                            form.requestSubmit();
                            dragForm.style.display = 'none';
                        }};

                        // Event listener for toggling the upload widget display on mobile.
                        uploadWidgetToggle.addEventListener('click', function (e) {{
                            e.preventDefault();
                            if (uploadArea.style.height === "100vh") {{
                                uploadArea.style = ""
                                document.body.style = ""
                                uploadWidgetToggle.style = ""
                            }} else {{
                                uploadArea.style.height = "100vh"
                                document.body.style = "overflow: hidden"
                                uploadWidgetToggle.style = "transform: rotate(180deg)"
                            }}
                        }})

                        // Cancel all active and pending uploads
                        uploadCancelButton.addEventListener('click', function (e) {{
                            e.preventDefault();
                            CANCEL_UPLOAD = true;
                        }})

                        form.addEventListener('submit', function (e) {{
                            e.preventDefault()
                            uploadFiles()
                        }})

                        // When uploads start, finish or are cancelled, the UI needs to reactively shows those
                        // updates of the state. This function updates the text on the upload widget to accurately
                        // show the state of all uploads.
                        function updateUploadTextAndList() {{
                            const uploading = uploadList.querySelectorAll('[data-state="uploading"]').length;
                            const pending = uploadList.querySelectorAll('[data-state="pending"]').length;
                            const complete = uploadList.querySelectorAll('[data-state="complete"]').length;
                            const cancelled = uploadList.querySelectorAll('[data-state="cancelled"]').length;
                            const failed = uploadList.querySelectorAll('[data-state="failed"]').length;
                            const total = uploading + pending + complete + cancelled + failed;

                            if (total === 0) {{
                                uploadTitle.textContent = "No uploads";
                                uploadActionText.textContent = "No uploads";
                                return;
                            }}

                            uploadTitle.textContent = `${{complete}} / ${{total}} uploaded`;
                            if (uploading > 0) {{
                                uploadActionText.textContent = `Uploading ${{uploading}} files...`;
                            }} else if (pending > 0) {{
                                uploadActionText.textContent = `${{pending}} files pending...`;
                            }} else if (complete === total) {{
                                uploadActionText.textContent = "All uploads complete!";
                                setTimeout(() => {{
                                    location.reload();
                                }}, 1000);
                            }} else if (failed > 0) {{
                                uploadActionText.textContent = `${{failed}} uploads failed`;
                            }} else if (cancelled > 0) {{
                                uploadActionText.textContent = `${{cancelled}} uploads cancelled`;
                            }}
                        }}

                        async function get256FileHash(file) {{
                            if (!window.crypto || !window.crypto.subtle) {{
                                return null;
                            }}
                            const buffer = await file.arrayBuffer();
                            const hash = await crypto.subtle.digest("SHA-256", buffer);
                            const hashArray = Array.from(new Uint8Array(hash));
                            const hashHex = hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
                            return hashHex;
                        }}

                        function uploadFiles() {{
                            const files = fileInput.files;
                            if (files.length === 0) {{
                                return;
                            }}

                            uploadArea.classList.add("active");
                            uploadTitle.textContent = `0 / ${{files.length}} uploaded`;
                            uploadActionText.textContent = "Starting upload...";
                            CANCEL_UPLOAD = false;

                            const uploadPromises = [];
                            for (let i = 0; i < files.length; i++) {{
                                const file = files[i];
                                const uploadFn = uploadFile(file);
                                if (CONCURRENCY === 0) {{
                                    uploadPromises.push(uploadFn());
                                }} else {{
                                    // concurrency handling
                                    uploadPromises.push(uploadFn);
                                }}
                            }}

                            if (CONCURRENCY === 0) {{
                                Promise.all(uploadPromises).then(() => {{
                                    updateUploadTextAndList();
                                }});
                            }} else {{
                                // simple concurrency
                                let index = 0;
                                function runNext() {{
                                    if (index >= uploadPromises.length) {{ return; }}
                                    const fn = uploadPromises[index++];
                                    fn().then(() => {{
                                        updateUploadTextAndList();
                                        runNext();
                                    }});
                                }}
                                for (let i = 0; i < Math.min(CONCURRENCY, uploadPromises.length); i++) {{
                                    runNext();
                                }}
                            }}
                        }}

                        // Creates a file upload widget from an HTML template. It then returns a promise which will
                        // be used to upload the file to the server and control the styles and
                        // interactions on the HTML list item.
                        function uploadFile(file) {{
                            const fileUploadItem = fileUploadItemTemplate.content.cloneNode(true)
                            const itemContainer = fileUploadItem.querySelector(".upload_file_item")
                            const itemText = fileUploadItem.querySelector(".upload_file_text")
                            const size = fileUploadItem.querySelector(".file_size")
                            const name = fileUploadItem.querySelector(".file_name")
                            const percentText = fileUploadItem.querySelector(".file_upload_percent")
                            const bar = fileUploadItem.querySelector(".file_progress_bar")
                            const cancel = fileUploadItem.querySelector(".file_cancel_upload")

                            name.textContent = file.name;
                            size.textContent = formatFileSize(file.size);
                            percentText.textContent = "0%"

                            uploadList.append(fileUploadItem)

                            // Cancel an upload before it even started.
                            function preCancelUpload() {{
                                preCancel = true;
                                itemText.classList.add(CANCELLED);
                                bar.classList.add(CANCELLED);
                                itemContainer.dataset.state = CANCELLED;
                                itemContainer.style.background = 'var(--upload_modal_file_upload_complete_background)';
                                cancel.disabled = true;
                                cancel.removeEventListener("click", preCancelUpload);
                                uploadCancelButton.removeEventListener("click", preCancelUpload);
                                updateUploadTextAndList();
                            }}

                            uploadCancelButton.addEventListener("click", preCancelUpload)
                            cancel.addEventListener("click", preCancelUpload)

                            // A callback function is return so that the upload doesn't start until
                            // we want it to. This is so that we have control over our desired concurrency.
                            return () => {{
                                if (preCancel) {{
                                    return Promise.resolve()
                                }}

                                // Upload the single file in a multipart request.
                                return new Promise(async (resolve, reject) => {{
                                    const fileHash = await get256FileHash(file);
                                    const xhr = new XMLHttpRequest();
                                    const formData = new FormData();
                                    formData.append('file', file);

                                    function onReadyStateChange(e) {{
                                        if (e.target.readyState == 4) {{
                                            if (e.target.status == 200) {{
                                                completeSuccess()
                                            }} else {{
                                                failedUpload(e.target.status)
                                            }}
                                        }}
                                    }}

                                    function onError(e) {{
                                        failedUpload()
                                    }}

                                    function onAbort(e) {{
                                        cancelUpload()
                                    }}

                                    function onProgress (e) {{
                                        update(Math.round((e.loaded / e.total) * 100));
                                    }}

                                    function update(uploadPercent) {{
                                        let wholeNumber = Math.floor(uploadPercent)
                                        percentText.textContent = `${{wholeNumber}}%`
                                        bar.style.width = `${{wholeNumber}}%`
                                    }}

                                    function completeSuccess() {{
                                        cancel.textContent = '✔';
                                        cancel.classList.add(COMPLETE);
                                        bar.classList.add(COMPLETE);
                                        cleanUp(COMPLETE)
                                    }}

                                    function failedUpload(statusCode) {{
                                        cancel.textContent = `${{statusCode}} ⚠`;
                                        itemText.classList.add(FAILED);
                                        bar.classList.add(FAILED);
                                        cleanUp(FAILED);
                                    }}

                                    function cancelUpload() {{
                                        xhr.abort()
                                        itemText.classList.add(CANCELLED);
                                        bar.classList.add(CANCELLED);
                                        cleanUp(CANCELLED);
                                    }}

                                    function cleanUp(state) {{
                                        itemContainer.dataset.state = state;
                                        itemContainer.style.background = 'var(--upload_modal_file_upload_complete_background)';
                                        cancel.disabled = true;
                                        cancel.removeEventListener("click", cancelUpload)
                                        uploadCancelButton.removeEventListener("click", cancelUpload)
                                        xhr.removeEventListener('readystatechange', onReadyStateChange);
                                        xhr.removeEventListener("error", onError);
                                        xhr.removeEventListener("abort", onAbort);
                                        xhr.upload.removeEventListener('progress', onProgress);
                                        resolve()
                                    }}

                                    uploadCancelButton.addEventListener("click", cancelUpload)
                                    cancel.addEventListener("click", cancelUpload)

                                    if (CANCEL_UPLOAD) {{
                                        cancelUpload()
                                    }} else {{
                                        itemContainer.dataset.state = UPLOADING
                                        xhr.addEventListener('readystatechange', onReadyStateChange);
                                        xhr.addEventListener("error", onError);
                                        xhr.addEventListener("abort", onAbort);
                                        xhr.upload.addEventListener('progress', onProgress);
                                        xhr.open('post', form.getAttribute("action"), true);
                                        if (fileHash) {{
                                            xhr.setRequestHeader('X-File-Hash', fileHash);
                                            xhr.setRequestHeader('X-File-Hash-Function', 'SHA256');
                                        }}
                                        xhr.send(formData);
                                    }}
                                }})
                            }}
                        }}

                        function formatFileSize(bytes) {{
                            if (bytes === 0) return '0 B';
                            const k = 1024;
                            const sizes = ['B','KiB','MiB','GiB','TiB'];
                            const i = Math.floor(Math.log(bytes) / Math.log(k));
                            return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
                        }}
                    }}
                    </script>"#, config.web_upload_concurrency)
    } else {
        "".to_string()
    };

    // For dirs-first and sorting, we need active header logic for name/size/date
    // Build table header with sorting links and chevrons
    // The header sorting toggle: when currently sorted by same column, toggle order, else default asc?
    // Original: when sorted by name asc, link goes to desc? Let's see earlier HTML for default (name, desc): 
    // In basic listing (default name desc?), header name had link "?sort=name&order=asc" (toggle). That suggests default sorting name desc, clicking toggles to asc.
    // For size column when default name, link is "?sort=size&order=asc" (always asc for other columns?)
    // Actually original logic: if current sort is same column, toggle order, else set to asc? Or to default order? Let's observe:
    // In basic html, all headers showed order=asc for toggle: Name header link had order=asc, Size had order=asc, Date had order=asc. So when current sort is name desc, the Name header link goes to asc (toggle), while other columns go to asc (default?).
    // When sorted by size asc (in earlier test), header for size had active and link to desc, while name had asc? Let's check: in size asc test, name header link was "?sort=name&order=asc"? Or what? We saw listing for size asc: <th class="name"><span class=""><span class="chevron">▾</span><a href="?sort=name&order=asc"...>Name</a></span></th> So Name column link is asc.
    // For size active asc: <th class="size"><span class="active"><span class="chevron">▴</span><a href="?sort=size&order=desc"...>Size</a></span></th> So active column toggles.
    // So logic: for each column, if column is current sort, link order = opposite of current order, chevron shows current order.
    // If column is not current sort, link order = asc, chevron shows default down? Actually non-active shows chevron down? In example, non-active name column chevron was ▾ (down) when sorted by size asc. So non-active chevron always down? Let's see basic listing (sorted by name desc): name column would be active? But in basic listing earlier we saw no active class? Wait basic listing html: all headers had empty active class. That suggests default sorting not indicated as active? Or maybe default sorting method name asc? But help says default order desc. Could be that when using default, no active? Let's check basic html table header: we had earlier for basic: all th had empty span class. That is because default sorting is name asc? But help says default desc. Let's check more: our earlier fetch for basic gave <th class="name"><span class=""><span class="chevron">▾</span><a href="?sort=name&order=asc"...> - that had chevron down, implying desc? So maybe active not shown for default? We need to check what determines active. Perhaps active is only shown when query param sort is explicitly given? In basic with no query, no active. In size asc test, active was shown for size.
    // So we will implement: if query contains sort, mark active for that column, else no active.
    let has_explicit_sort = query_params.contains_key("sort");

    let name_is_active = has_explicit_sort && sort_method == SortingMethod::Name;
    let size_is_active = has_explicit_sort && sort_method == SortingMethod::Size;
    let date_is_active = has_explicit_sort && sort_method == SortingMethod::Date;

    let name_order_link = if name_is_active {
        match sort_order { SortingOrder::Asc => "desc", SortingOrder::Desc => "asc" }
    } else {
        "asc"
    };
    let size_order_link = if size_is_active {
        match sort_order { SortingOrder::Asc => "desc", SortingOrder::Desc => "asc" }
    } else {
        "asc"
    };
    let date_order_link = if date_is_active {
        match sort_order { SortingOrder::Asc => "desc", SortingOrder::Desc => "asc" }
    } else {
        "asc"
    };

    let name_chevron_display = if name_is_active {
        match sort_order { SortingOrder::Asc => "▴", SortingOrder::Desc => "▾" }
    } else {
        "▾"
    };
    let size_chevron_display = if size_is_active {
        match sort_order { SortingOrder::Asc => "▴", SortingOrder::Desc => "▾" }
    } else {
        "▾"
    };
    let date_chevron_display = if date_is_active {
        match sort_order { SortingOrder::Asc => "▴", SortingOrder::Desc => "▾" }
    } else {
        "▾"
    };

    // Also need to include sort query in dir links? We already handled.

    let table_header = format!(r#"<table><thead><th class="name"><span class="{name_active}"><span class="chevron">{name_chev}</span><a href="?sort=name&amp;order={name_order}" title="Sort by name in {name_title} order">Name</a></span></th><th class="size"><span class="{size_active}"><span class="chevron">{size_chev}</span><a href="?sort=size&amp;order={size_order}" title="Sort by size in {size_title} order">Size</a></span></th><th class="date"><span class="{date_active}"><span class="chevron">{date_chev}</span><a href="?sort=date&amp;order={date_order}" title="Sort by date in {date_title} order">Last modification</a></span></th>{actions_header}</thead><tbody>"#,
        name_active = if name_is_active { "active" } else { "" },
        name_chev = name_chevron_display,
        name_order = name_order_link,
        name_title = if name_order_link=="asc" { "ascending" } else { "descending" },
        size_active = if size_is_active { "active" } else { "" },
        size_chev = size_chevron_display,
        size_order = size_order_link,
        size_title = if size_order_link=="asc" { "ascending" } else { "descending" },
        date_active = if date_is_active { "active" } else { "" },
        date_chev = date_chevron_display,
        date_order = date_order_link,
        date_title = if date_order_link=="asc" { "ascending" } else { "descending" },
        actions_header = if config.rm_files.is_some() { r#"<th class="actions"><span>Actions</span></th>"# } else { "" }
    );

    // Build final html
