fn check_media_type(filename: &str, mt: &MediaType) -> bool {
    // simple extension check
    let ext = Path::new(filename).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match mt {
        MediaType::Image => matches!(ext.as_str(), "jpg"|"jpeg"|"png"|"gif"|"bmp"|"webp"|"svg"|"ico"|"tiff"|"avif"),
        MediaType::Audio => matches!(ext.as_str(), "mp3"|"wav"|"ogg"|"flac"|"aac"|"m4a"|"wma"),
        MediaType::Video => matches!(ext.as_str(), "mp4"|"avi"|"mkv"|"mov"|"wmv"|"flv"|"webm"|"m4v"),
    }
}

fn generate_rename_path(dir: &Path, original_name: &str) -> PathBuf {
    let path = Path::new(original_name);
    let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or(original_name);
    let ext = path.extension().and_then(|e| e.to_str()).map(|e| format!(".{}", e)).unwrap_or_default();
    let mut counter = 1;
    loop {
        let new_name = format!("{}-{}{}", stem, counter, ext);
        let new_path = dir.join(&new_name);
        if !new_path.exists() {
            return new_path;
        }
        counter += 1;
    }
}

struct MultipartPart {
    headers: HashMap<String, String>,
    body: Vec<u8>,
}

fn parse_multipart(data: &[u8], boundary: &str) -> Result<Vec<MultipartPart>, String> {
    if boundary.is_empty() {
        return Err("no boundary".to_string());
    }
    let boundary_marker = format!("--{}", boundary);
    let end_marker = format!("--{}--", boundary);

    let data_str = String::from_utf8_lossy(data);
    // Split by boundary
    // For simplicity, use the raw bytes approach: convert to string and split.
    // This may not work for binary files containing boundary, but okay for simple.
    let mut parts: Vec<MultipartPart> = Vec::new();

    // Use iterator over lines? Better to split by boundary marker.
    let mut remaining = data_str.as_ref();
    // First boundary may be at start
    // We'll split by boundary_marker
    let mut iter = remaining.split(&boundary_marker);
    // First part before first boundary is preamble, ignore
    let _preamble = iter.next();

    for segment in iter {
        let seg = segment.trim_start_matches("\r\n");
        if seg.starts_with("--") || seg.trim().is_empty() {
            // end marker or empty
            if seg.starts_with("--") { break; }
            continue;
        }
        // Find header end \r\n\r\n
        if let Some(idx) = seg.find("\r\n\r\n") {
            let header_part = &seg[..idx];
            let body_part = &seg[idx+4..];
            // body_part may have trailing \r\n before next boundary
            let body_str = if body_part.ends_with("\r\n") {
                &body_part[..body_part.len()-2]
            } else {
                body_part
            };
            let mut headers = HashMap::new();
            for line in header_part.lines() {
                if let Some((k,v)) = line.split_once(':') {
                    headers.insert(k.trim().to_lowercase(), v.trim().to_string());
                }
            }
            // body is bytes - we need to get original bytes, not lossy string. For simplicity, we assume body is same as body_str bytes (may corrupt binary). We'll try to extract from original data using indexes, but for now use lossy.
            // Better: find the byte offset of this segment.
            // For simplicity, we will use body_str as bytes (works for text files, but binary may be corrupted).
            // We'll attempt to get body bytes by searching in original data: we can find header bytes and then slice.
            // For now, use body_str.as_bytes()
            parts.push(MultipartPart {
                headers,
                body: body_str.as_bytes().to_vec(),
            });
        }
    }

    // More robust binary parsing: fallback if we got 0 parts, try to parse with bytes
    if parts.is_empty() {
        // Try manual byte parsing
        let boundary_bytes = format!("\r\n--{}", boundary).into_bytes();
        // This is complex, skip.
        // Return error if still empty? But we should try alternative method using data as bytes split by boundary
        let b_marker = format!("--{}", boundary).into_bytes();
        // Use windows?
        // We'll implement simple: split data by b_marker
        let mut start = 0usize;
        // Find all occurrences
        // For simplicity, convert data to string again but using latin1?
        // We'll just return error
        if parts.is_empty() {
            // Try to parse with our earlier method but using bytes for body: we need to locate header end in bytes
            // We'll attempt byte search for \r\n\r\n
            let mut pos = 0usize;
            while pos < data.len() {
                // Find boundary
                if let Some(b_pos) = data[pos..].windows(b_marker.len()).position(|w| w == b_marker.as_slice()) {
                    let abs_b_pos = pos + b_pos;
                    // Find header end after boundary
                    let after_boundary = abs_b_pos + b_marker.len();
                    // Skip \r\n after boundary if present
                    let mut header_start = after_boundary;
                    if data.len() > header_start+1 && data[header_start]==b'\r' && data[header_start+1]==b'\n' {
                        header_start += 2;
                    }
                    // Find \r\n\r\n
                    if let Some(h_end) = data[header_start..].windows(4).position(|w| w == b"\r\n\r\n") {
                        let header_end = header_start + h_end;
                        let body_start = header_end + 4;
                        // Find next boundary
                        if let Some(next_b) = data[body_start..].windows(boundary_bytes.len()).position(|w| w == boundary_bytes.as_slice()) {
                            let body_end = body_start + next_b;
                            let header_bytes = &data[header_start..header_end];
                            let body_bytes = &data[body_start..body_end];
                            let header_str = String::from_utf8_lossy(header_bytes);
                            let mut headers = HashMap::new();
                            for line in header_str.lines() {
                                if let Some((k,v)) = line.split_once(':') {
                                    headers.insert(k.trim().to_lowercase(), v.trim().to_string());
                                }
                            }
                            parts.push(MultipartPart { headers, body: body_bytes.to_vec() });
                            pos = body_end;
                            continue;
                        } else {
                            // No next boundary, maybe end marker
                            break;
                        }
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
        }
    }

    Ok(parts)
}

fn extract_disposition_param(disp: &str, param: &str) -> Option<String> {
    // Content-Disposition: form-data; name="file"; filename="foo.txt"
    // Split by ;
    for part in disp.split(';') {
        let part = part.trim();
        if let Some((k,v)) = part.split_once('=') {
            if k.trim() == param {
                let mut val = v.trim().to_string();
                if val.starts_with('"') && val.ends_with('"') && val.len() >= 2 {
                    val = val[1..val.len()-1].to_string();
                }
                return Some(val);
            }
        }
    }
    None
}

fn serve_file(stream: &mut TcpStream, config: &Config, file_path: &Path, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>, client_ip: &str, raw_path: &str) -> io::Result<()> {
    let meta = fs::metadata(file_path);
    if let Err(_) = meta {
        let resp = build_404(config, &path_from_url(config, raw_path).display().to_string(), raw_path, query_params, req_headers, method.to_string(), client_ip.to_string(), false);
        write_response(stream, config, resp, method, req_headers, query_params)?;
        return Ok(());
    }
    let meta = meta.unwrap();
    let file_len = meta.len();
    let modified = meta.modified().unwrap_or(SystemTime::now());
    let modified_chrono: DateTime<Utc> = modified.into();
    let last_modified_str = modified_chrono.format("%a, %d %b %Y %H:%M:%S GMT").to_string();

    // ETag generation: try to mimic original? Original etag format: "\"<hex>:<size>:...\"" etc. We can generate simple etag: "<inode>:<size>:<mtime>"? Simpler: use hash of path + size + mtime.
    // From earlier examples: etag like "62280f03:6:6aa063c8:ec67b27" etc. That looks like maybe inode? But we can generate our own, as long as it works for If-None-Match 304 handling.
    // We'll generate etag as "<hex of modified secs>:<size>:<hash of file name>"
    // For 304 handling, if client sends If-None-Match matching our etag, return 304.

    let etag = {
        let secs = modified.duration_since(UNIX_EPOCH).unwrap_or(Duration::new(0,0)).as_secs();
        format!("\"{:x}:{:x}:{:x}\"", secs, file_len, file_path.display().to_string().len())
    };

    // Check If-None-Match
    if let Some(if_none) = req_headers.get("if-none-match") {
        if if_none.trim() == etag || if_none.trim() == etag.trim_matches('"') {
            // Return 304
            let body: Vec<u8> = vec![];
            let mut resp_headers = vec![
                ("Content-Disposition".to_string(), format!("inline; filename=\"{}\"", file_path.file_name().and_then(|n| n.to_str()).unwrap_or("file"))),
                ("Accept-Ranges".to_string(), "bytes".to_string()),
                ("Last-Modified".to_string(), last_modified_str.clone()),
                ("ETag".to_string(), etag.clone()),
                ("Content-Type".to_string(), guess_content_type(file_path)),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                ("ETag".to_string(), etag.clone()),
            ];
            // Remove duplicate etag
            resp_headers.dedup_by(|a,b| a.0.to_lowercase()==b.0.to_lowercase());
            let mut final_headers = Vec::new();
            let mut seen = std::collections::HashSet::new();
            for (k,v) in resp_headers {
                let lk = k.to_lowercase();
                if !seen.contains(&lk) {
                    seen.insert(lk);
                    final_headers.push((k,v));
                }
            }
            for (k,v) in &config.headers {
                if !seen.contains(&k.to_lowercase()) {
                    final_headers.push((k.clone(), v.clone()));
                }
            }
            let resp = HttpResponse {
                status_code: 304,
                reason: "Not Modified".to_string(),
                headers: final_headers,
                body,
            };
            write_response(stream, config, resp, method, req_headers, query_params)?;
            if config.verbose {
                println!("{} [INFO] {} \"{} {} HTTP/1.1\" 304 0 \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path);
            }
            return Ok(());
        }
    }

    // Check If-Modified-Since? Could handle but skip for now.

    // Range handling
    let mut start: u64 = 0;
    let mut end: u64 = file_len.saturating_sub(1);
    let mut is_partial = false;
    if let Some(range_header) = req_headers.get("range") {
        // Example: bytes=0-2
        if range_header.starts_with("bytes=") {
            let range_spec = &range_header[6..];
            if let Some((s,e)) = range_spec.split_once('-') {
                let s_parsed = if s.is_empty() { None } else { s.parse::<u64>().ok() };
                let e_parsed = if e.is_empty() { None } else { e.parse::<u64>().ok() };
                match (s_parsed, e_parsed) {
                    (Some(s_val), Some(e_val)) => {
                        start = s_val.min(file_len.saturating_sub(1));
                        end = e_val.min(file_len.saturating_sub(1));
                        is_partial = true;
                    },
                    (Some(s_val), None) => {
                        start = s_val;
                        end = file_len.saturating_sub(1);
                        is_partial = true;
                    },
                    (None, Some(e_val)) => {
                        // suffix: last e_val bytes
                        if e_val <= file_len {
                            start = file_len - e_val;
                            end = file_len -1;
                            is_partial = true;
                        }
                    },
                    _ => {}
                }
            }
        }
    }

    let content_length = if is_partial { end - start + 1 } else { file_len };

    // Read file content (or slice)
    let mut file = File::open(file_path)?;
    let mut body: Vec<u8> = Vec::with_capacity(content_length as usize);
    if is_partial {
        use std::io::Seek;
        file.seek(std::io::SeekFrom::Start(start))?;
        let mut limited = file.take(content_length);
        limited.read_to_end(&mut body)?;
    } else {
        // For HEAD, don't read body? But we still need content-length. For HEAD we will send headers but no body? Actually http says HEAD should not send body.
        if method != "HEAD" {
            file.read_to_end(&mut body)?;
        }
    }

    // Content-Type
    let content_type = guess_content_type(file_path);

    // Content-Disposition
    // If content_type is text or image etc inline, else attachment? Original logic: for .hiddenfile it was attachment, for file1.txt inline.
    // We will use mime_guess to decide: if octet-stream, attachment, else inline. For simplicity, if content_type starts with text/ or image/ or etc inline.
    let disposition_type = if content_type.starts_with("text/") || content_type.starts_with("image/") || content_type.contains("html") || content_type.contains("javascript") || content_type.contains("json") || content_type.contains("xml") || content_type == "application/octet-stream" && file_path.extension().is_none() {
        // Original for .hiddenfile (no extension?) gave attachment. So for files without extension, attachment? Let's mimic: if extension empty and content_type octet-stream, attachment.
        // We'll decide: if filename starts with dot, attachment.
        if file_path.file_name().and_then(|n| n.to_str()).map(|n| n.starts_with('.')).unwrap_or(false) {
            "attachment"
        } else {
            // Check content type: if text/plain etc inline.
            if content_type == "application/octet-stream" {
                "attachment"
            } else {
                "inline"
            }
        }
    } else {
        if content_type == "application/octet-stream" { "attachment" } else { "inline" }
    };

    let filename = file_path.file_name().and_then(|n| n.to_str()).unwrap_or("file");
    let content_disposition = format!("{}; filename=\"{}\"", disposition_type, filename);

    let mut resp_headers = vec![
        ("Content-Length".to_string(), content_length.to_string()),
        ("Content-Type".to_string(), content_type.clone()),
        ("Content-Disposition".to_string(), content_disposition),
        ("Accept-Ranges".to_string(), "bytes".to_string()),
        ("Last-Modified".to_string(), last_modified_str),
        ("ETag".to_string(), etag.clone()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];

    if is_partial {
        resp_headers.push(("Content-Range".to_string(), format!("bytes {}-{}/{}", start, end, file_len)));
    }

    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }

    let status = if is_partial { 206 } else { 200 };
    let reason = if is_partial { "Partial Content" } else { "OK" };

    let resp = HttpResponse {
        status_code: status,
        reason: reason.to_string(),
        headers: resp_headers,
        body: if method == "HEAD" { vec![] } else { body },
    };

    let bytes_sent = resp.body.len();
    write_response(stream, config, resp, method, req_headers, query_params)?;

    if config.verbose {
        println!("{} [INFO] {} \"{} {} HTTP/1.1\" {} {} \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path, status, bytes_sent);
    }

    Ok(())
}

fn guess_content_type(path: &Path) -> String {
    // Very simple mime guess based on extension
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match ext.as_str() {
        "html"|"htm" => "text/html; charset=utf-8".to_string(),
        "css" => "text/css; charset=utf-8".to_string(),
        "js" => "text/javascript; charset=utf-8".to_string(),
        "json" => "application/json".to_string(),
        "txt"|"md"|"rs"|"toml"|"yaml"|"yml" => "text/plain; charset=utf-8".to_string(),
        "svg" => "image/svg+xml".to_string(),
        "png" => "image/png".to_string(),
        "jpg"|"jpeg" => "image/jpeg".to_string(),
        "gif" => "image/gif".to_string(),
        "webp" => "image/webp".to_string(),
        "ico" => "image/x-icon".to_string(),
        "mp3" => "audio/mpeg".to_string(),
        "wav" => "audio/wav".to_string(),
        "mp4" => "video/mp4".to_string(),
        "pdf" => "application/pdf".to_string(),
        "zip" => "application/zip".to_string(),
        "tar" => "application/x-tar".to_string(),
        "gz"|"tgz" => "application/gzip".to_string(),
        _ => "application/octet-stream".to_string(),
    }
}

fn write_response(stream: &mut TcpStream, config: &Config, resp: HttpResponse, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>) -> io::Result<()> {
    // Handle compress-response if enabled and client accepts gzip and body is text/html etc?
    let mut body = resp.body;
    let mut headers = resp.headers;

    // Check if compress-response enabled and client accepts gzip
    let should_compress = config.compress_response && 
        req_headers.get("accept-encoding").map(|v| v.contains("gzip")).unwrap_or(false) &&
        body.len() > 0 &&
        // Only compress if content-type is text/html or text/* or etc? Original compresses all? We'll compress if content-type contains text/html or text/plain or application/json etc.
        headers.iter().any(|(k,v)| k.to_lowercase()=="content-type" && (v.contains("text/html") || v.contains("text/plain") || v.contains("application/json") || v.contains("text/css") || v.contains("javascript")));

    if should_compress {
        // Compress body
        let mut encoder = GzEncoder::new(Vec::new(), FlateCompression::default());
        encoder.write_all(&body).ok();
        if let Ok(compressed) = encoder.finish() {
            // Update headers
            body = compressed;
            // Remove content-length and add new
            headers.retain(|(k,_)| k.to_lowercase() != "content-length");
            headers.push(("Content-Length".to_string(), body.len().to_string()));
            headers.push(("Content-Encoding".to_string(), "gzip".to_string()));
            headers.push(("Vary".to_string(), "accept-encoding".to_string()));
        }
    }

    // Ensure Date header present
    if !headers.iter().any(|(k,_)| k.to_lowercase()=="date") {
        headers.push(("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()));
    }

    // Build response string
    let mut resp_str = format!("HTTP/1.1 {} {}\r\n", resp.status_code, resp.reason);
    for (k,v) in &headers {
        resp_str.push_str(&format!("{}: {}\r\n", k, v));
    }
    resp_str.push_str("\r\n");

    stream.write_all(resp_str.as_bytes())?;
    if method != "HEAD" {
        stream.write_all(&body)?;
    }
    stream.flush()?;
    Ok(())
}

fn serve_directory(stream: &mut TcpStream, config: &Config, fs_path: &Path, effective_path: &str, raw_path: &str, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>, client_ip: &str) -> io::Result<()> {
    // Determine sorting
    let sort_method = query_params.get("sort").map(|s| match s.as_str() {
        "name" => SortingMethod::Name,
        "size" => SortingMethod::Size,
        "date" => SortingMethod::Date,
        _ => config.default_sorting_method.clone(),
    }).unwrap_or_else(|| config.default_sorting_method.clone());

    let sort_order = query_params.get("order").map(|s| match s.as_str() {
        "asc" => SortingOrder::Asc,
        "desc" => SortingOrder::Desc,
        _ => config.default_sorting_order.clone(),
    }).unwrap_or_else(|| config.default_sorting_order.clone());

    // Read entries
    let entries = match fs::read_dir(fs_path) {
        Ok(r) => r,
        Err(_) => {
            let resp = build_404(config, effective_path, raw_path, query_params, req_headers, method.to_string(), client_ip.to_string(), false);
            write_response(stream, config, resp, method, req_headers, query_params)?;
            return Ok(());
        }
    };

    #[derive(Debug)]
    struct DirEntryInfo {
        name: String,
        is_dir: bool,
        is_symlink: bool,
        symlink_target: Option<String>,
        size: u64,
        modified: SystemTime,
        modified_str: String,
    }

    let mut infos: Vec<DirEntryInfo> = Vec::new();
    for entry_res in entries {
        if let Ok(entry) = entry_res {
            let name_os = entry.file_name();
            let name = name_os.to_string_lossy().to_string();
            if !config.hidden && name.starts_with('.') { continue; }
            let path = entry.path();

            // Check symlink
            let is_symlink = fs::symlink_metadata(&path).map(|m| m.file_type().is_symlink()).unwrap_or(false);
            if config.no_symlinks && is_symlink { continue; }

            let mut symlink_target: Option<String> = None;
            if is_symlink && config.show_symlink_info {
                if let Ok(target) = fs::read_link(&path) {
                    symlink_target = Some(target.to_string_lossy().to_string());
                }
            }

            let meta = if is_symlink {
                // For symlink, get metadata of target? Original size for symlink file shows target size? In basic listing, symlink size was 6 B same as file1.txt. So they follow symlink for size.
                fs::metadata(&path).or_else(|_| fs::symlink_metadata(&path)).ok()
            } else {
                fs::metadata(&path).ok()
            };

            let (size, modified) = if let Some(m) = meta {
                (if m.is_dir() { 0 } else { m.len() }, m.modified().unwrap_or(SystemTime::now()))
            } else {
                (0, SystemTime::now())
            };

            let modified_chrono: DateTime<Utc> = modified.into();
            let modified_str = modified_chrono.format("%Y-%m-%d %H:%M:%S %z").to_string();
            // Actually original uses local? It shows "+00:00" - that's offset. Use Local? Original uses Local time with offset. We'll use chrono Local.
            let local_dt: DateTime<Local> = modified.into();
            let modified_local_str = local_dt.format("%Y-%m-%d %H:%M:%S %:z").to_string();

            // For history "now", "x seconds ago" etc? Original shows relative time like "now", "a minute ago", etc. We need to implement similar human relative.
            // We'll compute now - modified and format as "now" or "X seconds ago" etc.
            // For simplicity, we will use similar logic.

            infos.push(DirEntryInfo {
                name: name.clone(),
                is_dir: path.is_dir(),
                is_symlink,
                symlink_target,
                size,
                modified,
                modified_str: modified_local_str,
            });
        }
    }

    // Sorting
    infos.sort_by(|a,b| {
        // dirs_first handling
        if config.dirs_first {
            match (a.is_dir, b.is_dir) {
                (true,false) => return std::cmp::Ordering::Less,
                (false,true) => return std::cmp::Ordering::Greater,
                _ => {}
            }
        }
        let ord = match sort_method {
            SortingMethod::Name => {
                // natural sort? Original says natural sort: follows alphanumerical order. We'll use simple case insensitive?
                a.name.to_lowercase().cmp(&b.name.to_lowercase())
            },
            SortingMethod::Size => {
                a.size.cmp(&b.size)
            },
            SortingMethod::Date => {
                a.modified.cmp(&b.modified)
            },
        };
        match sort_order {
            SortingOrder::Asc => ord,
            SortingOrder::Desc => ord.reverse(),
        }
    });

    // Check raw mode
    let is_raw = query_params.get("raw").map(|v| v=="true").unwrap_or(false);
    if is_raw {
        // Render raw html: minimal table
        let mut html = String::new();
        html.push_str(r#"<!DOCTYPE html><html><body><table><thead><th class="name">Name</th><th class="size">Size</th><th class="date">Last modification</th></thead><tbody>"#);
        // Parent directory link if not root
        if effective_path != "/" {
            // Parent is one level up
            let parent_href = if effective_path == "/" { "/".to_string() } else {
                // Remove trailing slash, then get parent
                let trimmed = effective_path.trim_end_matches('/');
                if let Some(pos) = trimmed.rfind('/') {
                    let parent = if pos==0 { "/" } else { &trimmed[..pos] };
                    format!("{}/", parent)
                } else {
                    "/".to_string()
                }
            };
            let parent_href_raw = format!("{}?raw=true", parent_href);
            html.push_str(&format!(r#"<tr><td colspan="3"><p><a class="root" href="{}">..</a></p></td></tr>"#, parent_href_raw));
        }

        for info in &infos {
            let href = if info.is_dir {
                // Preserve query raw
                format!("/{}/?raw=true", format!("{}{}", effective_path.trim_end_matches('/'), if effective_path.ends_with('/') { "" } else { "/" }).trim_start_matches('/') .to_string() + &info.name)
                // Actually need to generate href: for raw, href includes ?raw=true
                // Simplified: /a/?raw=true etc. For root /a/?raw=true
                // For file: /file.txt
            } else {
                // For file, href is /file path? In raw mode earlier we saw href="/file1.txt" without raw param? Actually raw mode file href had no raw param, but dir href had raw.
                // Check earlier raw output: directory href had ?raw=true, file href did NOT have raw param. So implement accordingly.
