fn parse_auth_str(s: &str) -> Option<AuthEntry> {
    if s.is_empty() { return None; }
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() == 1 {
        return Some(AuthEntry { username: parts[0].to_string(), password_hash_type: None, password: "".to_string() });
    } else if parts.len() == 2 {
        let username = parts[0].to_string();
        let password = parts[1].to_string();
        if username.is_empty() { return None; }
        return Some(AuthEntry { username, password_hash_type: None, password });
    } else if parts.len() == 3 {
        let username = parts[0].to_string();
        let hashtype = parts[1].to_string();
        let hash = parts[2].to_string();
        if hashtype != "sha256" && hashtype != "sha512" { return None; }
        if username.is_empty() { return None; }
        return Some(AuthEntry { username, password_hash_type: Some(hashtype), password: hash });
    } else {
        let username = parts[0].to_string();
        if username.is_empty() { return None; }
        if parts[1] == "sha256" || parts[1] == "sha512" {
            let hashtype = parts[1].to_string();
            let hash = parts[2..].join(":");
            return Some(AuthEntry { username, password_hash_type: Some(hashtype), password: hash });
        } else {
            let password = parts[1..].join(":");
            return Some(AuthEntry { username, password_hash_type: None, password });
        }
    }
}

fn check_auth(entry: &AuthEntry, provided_password: &str) -> bool {
    match &entry.password_hash_type {
        None => entry.password == provided_password,
        Some(ht) => {
            if ht == "sha256" {
                let mut hasher = Sha256::new();
                hasher.update(provided_password.as_bytes());
                let res = hasher.finalize();
                let hex = format!("{:x}", res);
                hex == entry.password.to_lowercase()
            } else if ht == "sha512" {
                let mut hasher = Sha512::new();
                hasher.update(provided_password.as_bytes());
                let res = hasher.finalize();
                let hex = format!("{:x}", res);
                hex == entry.password.to_lowercase()
            } else { false }
        }
    }
}

