        .arg(Arg::new("index").long("index").value_name("INDEX").help("The name of a directory index file to serve, like \"index.html\"\n\nNormally, when miniserve serves a directory, it creates a listing for that directory. However, if a directory contains this file, miniserve will serve that file instead.").env("MINISERVE_INDEX"))
        .arg(Arg::new("spa").long("spa").help("Activate SPA (Single Page Application) mode\n\nThis will cause the file given by --index to be served for all non-existing file paths. In effect, this will serve the index file whenever a 404 would otherwise occur in order to allow the SPA router to handle the request instead.").env("MINISERVE_SPA").action(ArgAction::SetTrue))
        .arg(Arg::new("pretty-urls").long("pretty-urls").help("Activate Pretty URLs mode\n\nThis will cause the server to serve the equivalent `.html` file indicated by the path.\n\n`/about` will try to find `about.html` and serve it.").env("MINISERVE_PRETTY_URLS").action(ArgAction::SetTrue))
        .arg(Arg::new("port").short('p').long("port").value_name("PORT").help("Port to use").env("MINISERVE_PORT").default_value("8080").value_parser(value_parser!(u16).range(0..=65535)))
        .arg(Arg::new("interfaces").short('i').long("interfaces").value_name("INTERFACES").help("Interface to listen on").env("MINISERVE_INTERFACE"))
        .arg(Arg::new("auth").short('a').long("auth").value_name("AUTH").help("Set authentication\n\nCurrently supported formats:\nusername:password, username:sha256:hash, username:sha512:hash\n(e.g. joe:123,\njoe:sha256:a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3)").env("MINISERVE_AUTH").action(ArgAction::Append))
        .arg(Arg::new("auth-file").long("auth-file").value_name("AUTH_FILE").help("Read authentication values from a file\n\nExample file content:\n\njoe:123\nbob:sha256:a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3\nbill:\n").env("MINISERVE_AUTH_FILE").value_hint(ValueHint::FilePath))
        .arg(Arg::new("route-prefix").long("route-prefix").value_name("ROUTE_PREFIX").help("Use a specific route prefix").env("MINISERVE_ROUTE_PREFIX"))
        .arg(Arg::new("random-route").long("random-route").help("Generate a random 6-hexdigit route").env("MINISERVE_RANDOM_ROUTE").action(ArgAction::SetTrue))
        .arg(Arg::new("no-symlinks").short('P').long("no-symlinks").help("Hide symlinks in listing and prevent them from being followed").env("MINISERVE_NO_SYMLINKS").action(ArgAction::SetTrue))
        .arg(Arg::new("hidden").short('H').long("hidden").help("Show hidden files").env("MINISERVE_HIDDEN").action(ArgAction::SetTrue))
        .arg(Arg::new("default-sorting-method").short('S').long("default-sorting-method").value_name("DEFAULT_SORTING_METHOD").help("Default sorting method for file list").env("MINISERVE_DEFAULT_SORTING_METHOD").default_value("name").value_parser(["name","size","date"]))
        .arg(Arg::new("default-sorting-order").short('O').long("default-sorting-order").value_name("DEFAULT_SORTING_ORDER").help("Default sorting order for file list").env("MINISERVE_DEFAULT_SORTING_ORDER").default_value("desc").value_parser(["asc","desc"]))
        .arg(Arg::new("color-scheme").short('c').long("color-scheme").value_name("COLOR_SCHEME").help("Default color scheme").env("MINISERVE_COLOR_SCHEME").default_value("squirrel").value_parser(["squirrel","archlinux","zenburn","monokai"]))
        .arg(Arg::new("color-scheme-dark").short('d').long("color-scheme-dark").value_name("COLOR_SCHEME_DARK").help("Default color scheme").env("MINISERVE_COLOR_SCHEME_DARK").default_value("archlinux").value_parser(["squirrel","archlinux","zenburn","monokai"]))
        .arg(Arg::new("qrcode").short('q').long("qrcode").help("Enable QR code display").env("MINISERVE_QRCODE").action(ArgAction::SetTrue))
        .arg(Arg::new("upload-files").short('u').long("upload-files").value_name("ALLOWED_UPLOAD_DIR").help("Enable file uploading (and optionally specify for which directory)\n\nThe provided path is not a physical file system path. Instead, it's relative to the serve dir. For instance, if the serve dir is '/home/hello', set this to '/upload' to allow uploading to '/home/hello/upload'. When specified via environment variable, a path always needs to be specified.").env("MINISERVE_ALLOWED_UPLOAD_DIR").num_args(0..=1).default_missing_value("true_marker"))
        .arg(Arg::new("web-upload-files-concurrency").long("web-upload-files-concurrency").value_name("WEB_UPLOAD_CONCURRENCY").help("Configure amount of concurrent uploads when visiting the website. Must have upload-files option enabled for this setting to matter.\n\nFor example, a value of 4 would mean that the web browser will only upload 4 files at a time to the web server when using the web browser interface.\n\nWhen the value is kept at 0, it attempts to resolve all the uploads at once in the web browser.\n\nNOTE: Web pages have a limit of how many active HTTP connections that they can make at one time, so even though you might set a concurrency limit of 100, the browser might only make progress on the max amount of connections it allows the web page to have open.").env("MINISERVE_WEB_UPLOAD_CONCURRENCY").default_value("0").value_parser(value_parser!(usize)))
        .arg(Arg::new("chmod").long("chmod").value_name("CHMOD").help("Set unix file permissions of uploaded files\n\nThis takes an octal number, for example 0600. By default 0666 & ~umask is used to simulate the system's default behavior.").env("MINISERVE_CHMOD"))
        .arg(Arg::new("directory-size").long("directory-size").help("Enable recursive directory size calculation\n\nThis is disabled by default because it is a potentially fairly IO intensive operation.").env("MINISERVE_DIRECTORY_SIZE").action(ArgAction::SetTrue))
        .arg(Arg::new("mkdir").short('U').long("mkdir").help("Enable creating directories").env("MINISERVE_MKDIR_ENABLED").action(ArgAction::SetTrue))
        .arg(Arg::new("media-type").short('m').long("media-type").value_name("MEDIA_TYPE").help("Specify uploadable media types").env("MINISERVE_MEDIA_TYPE").value_parser(["image","audio","video"]))
        .arg(Arg::new("raw-media-type").short('M').long("raw-media-type").value_name("MEDIA_TYPE_RAW").help("Directly specify the uploadable media type expression").env("MINISERVE_RAW_MEDIA_TYPE"))
        .arg(Arg::new("on-duplicate-files").short('o').long("on-duplicate-files").value_name("ON_DUPLICATE_FILES").help("What to do if existing files with same name is present during file upload\n\nIf you enable renaming files, the renaming will occur by adding a numerical suffix to the filename before the final extension. For example file.txt will be uploaded as file-1.txt, the number will be increased until an available filename is found.").env("MINISERVE_ON_DUPLICATE_FILES").default_value("error").value_parser(["error","overwrite","rename"]))
        .arg(Arg::new("rm-files").short('R').long("rm-files").value_name("ALLOWED_RM_DIR").help("Enable file and directory deletion (and optionally specify for which directory)").env("MINISERVE_ALLOWED_RM_DIR").num_args(0..=1).default_missing_value("true_marker"))
        .arg(Arg::new("enable-tar").short('r').long("enable-tar").help("Enable uncompressed tar archive generation").env("MINISERVE_ENABLE_TAR").action(ArgAction::SetTrue))
        .arg(Arg::new("enable-tar-gz").short('g').long("enable-tar-gz").help("Enable gz-compressed tar archive generation").env("MINISERVE_ENABLE_TAR_GZ").action(ArgAction::SetTrue))
        .arg(Arg::new("enable-zip").short('z').long("enable-zip").help("Enable zip archive generation\n\nWARNING: Zipping large directories can result in out-of-memory exception because zip generation is done in memory and cannot be sent on the fly").env("MINISERVE_ENABLE_ZIP").action(ArgAction::SetTrue))
        .arg(Arg::new("compress-response").short('C').long("compress-response").help("Compress response\n\nWARNING: Enabling this option may slow down transfers due to CPU overhead, so it is disabled by default.\n\nOnly enable this option if you know that your users have slow connections or if you want to minimize your server's bandwidth usage.").env("MINISERVE_COMPRESS_RESPONSE").action(ArgAction::SetTrue))
        .arg(Arg::new("dirs-first").short('D').long("dirs-first").help("List directories first").env("MINISERVE_DIRS_FIRST").action(ArgAction::SetTrue))
        .arg(Arg::new("title").short('t').long("title").value_name("TITLE").help("Shown instead of host in page title and heading").env("MINISERVE_TITLE"))
        .arg(Arg::new("header").long("header").value_name("HEADER").help("Inserts custom headers into the responses. Specify each header as a 'Header:Value' pair. This parameter can be used multiple times to add multiple headers.\n\nExample: --header \"Header1:Value1\" --header \"Header2:Value2\" (If a header is already set or previously inserted, it will not be overwritten.)").env("MINISERVE_HEADER").action(ArgAction::Append))
        .arg(Arg::new("show-symlink-info").short('l').long("show-symlink-info").help("Visualize symlinks in directory listing").env("MINISERVE_SHOW_SYMLINK_INFO").action(ArgAction::SetTrue))
        .arg(Arg::new("hide-version-footer").short('F').long("hide-version-footer").help("Hide version footer").env("MINISERVE_HIDE_VERSION_FOOTER").action(ArgAction::SetTrue))
        .arg(Arg::new("hide-theme-selector").long("hide-theme-selector").help("Hide theme selector").env("MINISERVE_HIDE_THEME_SELECTOR").action(ArgAction::SetTrue))
        .arg(Arg::new("show-wget-footer").short('W').long("show-wget-footer").help("If enabled, display a wget command to recursively download the current directory").env("MINISERVE_SHOW_WGET_FOOTER").action(ArgAction::SetTrue))
        .arg(Arg::new("print-completions").long("print-completions").value_name("shell").help("Generate completion file for a shell").value_parser(["bash","elvish","fish","powershell","zsh"]))
        .arg(Arg::new("print-manpage").long("print-manpage").help("Generate man page").action(ArgAction::SetTrue))
        .arg(Arg::new("tls-cert").long("tls-cert").value_name("TLS_CERT").help("TLS certificate to use").env("MINISERVE_TLS_CERT").value_hint(ValueHint::FilePath))
        .arg(Arg::new("tls-key").long("tls-key").value_name("TLS_KEY").help("TLS private key to use").env("MINISERVE_TLS_KEY").value_hint(ValueHint::FilePath))
        .arg(Arg::new("readme").long("readme").help("Enable README.md rendering in directories").env("MINISERVE_README").action(ArgAction::SetTrue))
        .arg(Arg::new("disable-indexing").short('I').long("disable-indexing").help("Disable indexing\n\nThis will prevent directory listings from being generated and return an error instead.").env("MINISERVE_DISABLE_INDEXING").action(ArgAction::SetTrue))
        .arg(Arg::new("enable-webdav").long("enable-webdav").help("Enable read-only WebDAV support (PROPFIND requests)").env("MINISERVE_ENABLE_WEBDAV").action(ArgAction::SetTrue))
        .arg(Arg::new("size-display").long("size-display").value_name("SIZE_DISPLAY").help("Show served file size in exact bytes").env("MINISERVE_SIZE_DISPLAY").default_value("human").value_parser(["human","exact"]))
        .arg(Arg::new("file-external-url").long("file-external-url").value_name("FILE_EXTERNAL_URL").help("Optional external URL (e.g., 'http://external.example.com:8081') prepended to file links in listings.\n\nAllows serving files from a different URL than the browsing instance. Useful for setups like: one authenticated instance for browsing, linking files (via this option) to a second, non-indexed (-I) instance for direct downloads. This obscures the full file list on the download server, while users can still copy direct file URLs for sharing. The external URL is put verbatim in front of the relative location of the file, including the protocol. The user should take care this results in a valid URL, no further checks are being done.").env("MINISERVE_FILE_EXTERNAL_URL"));
    cmd
}

fn generate_random_route() -> String {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let pid = std::process::id() as u128;
    let mut x = now ^ (pid * 0x9e3779b97f4a7c15);
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    let v = (x % 0xFFFFFF) as u32;
    format!("{:06x}", v)
}

fn main() {
    let cli = build_cli();
    let matches = cli.get_matches();

    if let Some(shell_str) = matches.get_one::<String>("print-completions") {
        let shell = match shell_str.as_str() {
            "bash" => Shell::Bash,
            "elvish" => Shell::Elvish,
            "fish" => Shell::Fish,
            "powershell" => Shell::PowerShell,
            "zsh" => Shell::Zsh,
            _ => Shell::Bash,
        };
        let mut cmd = build_cli();
        let bin_name = "miniserve";
        generate_completion(shell, &mut cmd, bin_name, &mut std::io::stdout());
        return;
    }
    if matches.get_flag("print-manpage") {
        let man = Man::new(build_cli());
        let mut buffer: Vec<u8> = Vec::new();
        man.render(&mut buffer).expect("man render");
        std::io::stdout().write_all(&buffer).unwrap();
        return;
    }

    let tls_cert = matches.get_one::<String>("tls-cert").cloned();
    let tls_key = matches.get_one::<String>("tls-key").cloned();
    if tls_cert.is_some() && tls_key.is_none() {
        eprintln!("error: the following required arguments were not provided:\n  --tls-key <TLS_KEY>\n\nUsage: miniserve --tls-cert <TLS_CERT> --tls-key <TLS_KEY> <PATH>\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if tls_key.is_some() && tls_cert.is_none() {
        eprintln!("error: the following required arguments were not provided:\n  --tls-cert <TLS_CERT>\n\nUsage: miniserve --tls-cert <TLS_CERT> --tls-key <TLS_KEY> <PATH>\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    let path_arg = matches.get_one::<String>("PATH").cloned();
    let serve_path: PathBuf;
    if let Some(p) = path_arg {
        let pb = PathBuf::from(p);
        if !pb.exists() {
            eprintln!("{} [ERROR] Failed to resolve path to be served", Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("{} [ERROR] caused by: No such file or directory (os error 2)", Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("Error: Failed to resolve path to be served\ncaused by: No such file or directory (os error 2)");
            std::process::exit(1);
        }
        serve_path = pb.canonicalize().unwrap_or_else(|_| pb);
    } else {
        use std::io::IsTerminal;
        if !std::io::stdin().is_terminal() {
            eprintln!("{} [ERROR] Refusing to start as no explicit serve path was set and no interactive terminal was attached", Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("{} [ERROR] Please set an explicit serve path like: `miniserve /my/path`", Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached\nPlease set an explicit serve path like: `miniserve /my/path`");
            std::process::exit(1);
        } else {
            serve_path = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        }
    }

    let serve_path_is_file = serve_path.is_file();

    let mut auth_entries: Vec<AuthEntry> = Vec::new();
    if let Some(vals) = matches.get_many::<String>("auth") {
        for v in vals {
            if let Some(entry) = parse_auth_str(v) {
                auth_entries.push(entry);
            }
        }
    }
    if let Some(auth_file_path) = matches.get_one::<String>("auth-file") {
        match fs::read_to_string(auth_file_path) {
            Ok(content) => {
                for line in content.lines() {
                    let line = line.trim();
                    if line.is_empty() { continue; }
                    if let Some(entry) = parse_auth_str(line) {
                        auth_entries.push(entry);
                    }
                }
            },
            Err(e) => {
                eprintln!("Failed to read auth file {}: {}", auth_file_path, e);
                std::process::exit(1);
            }
        }
    }

    let mut route_prefix = matches.get_one::<String>("route-prefix").cloned();
    let random_route = matches.get_flag("random-route");
    let mut random_route_value: Option<String> = None;
    if random_route {
        let r = generate_random_route();
        random_route_value = Some(r.clone());
        if route_prefix.is_none() {
            route_prefix = Some(format!("/{}", r));
        }
    }

    let normalized_route_prefix = route_prefix.as_ref().map(|rp| {
        let mut s = rp.trim().to_string();
        if !s.starts_with('/') { s = format!("/{}", s); }
        while s.len() > 1 && s.ends_with('/') {
            s.pop();
        }
        s
    });

    let verbose = matches.get_flag("verbose");
    let temp_dir = matches.get_one::<String>("temp-directory").map(|s| PathBuf::from(s));
    let index = matches.get_one::<String>("index").cloned();
    let spa = matches.get_flag("spa");
    let pretty_urls = matches.get_flag("pretty-urls");
    let port = *matches.get_one::<u16>("port").unwrap_or(&8080);
    let interfaces = matches.get_one::<String>("interfaces").cloned();
    let no_symlinks = matches.get_flag("no-symlinks");
    let hidden = matches.get_flag("hidden");
    let default_sorting_method = match matches.get_one::<String>("default-sorting-method").map(|s| s.as_str()).unwrap_or("name") {
        "name" => SortingMethod::Name,
        "size" => SortingMethod::Size,
        "date" => SortingMethod::Date,
        _ => SortingMethod::Name,
    };
    let default_sorting_order = match matches.get_one::<String>("default-sorting-order").map(|s| s.as_str()).unwrap_or("desc") {
        "asc" => SortingOrder::Asc,
        "desc" => SortingOrder::Desc,
        _ => SortingOrder::Desc,
    };
    let color_scheme = match matches.get_one::<String>("color-scheme").map(|s| s.as_str()).unwrap_or("squirrel") {
        "squirrel" => ColorScheme::Squirrel,
        "archlinux" => ColorScheme::Archlinux,
        "zenburn" => ColorScheme::Zenburn,
        "monokai" => ColorScheme::Monokai,
        _ => ColorScheme::Squirrel,
    };
    let color_scheme_dark = match matches.get_one::<String>("color-scheme-dark").map(|s| s.as_str()).unwrap_or("archlinux") {
        "squirrel" => ColorScheme::Squirrel,
        "archlinux" => ColorScheme::Archlinux,
        "zenburn" => ColorScheme::Zenburn,
        "monokai" => ColorScheme::Monokai,
        _ => ColorScheme::Archlinux,
    };
    let qrcode = matches.get_flag("qrcode");
    let web_upload_concurrency = *matches.get_one::<usize>("web-upload-files-concurrency").unwrap_or(&0);

    let chmod_opt = matches.get_one::<String>("chmod").map(|s| {
        u32::from_str_radix(s.trim_start_matches("0o").trim(), 8).unwrap_or(0o644)
    });

    let directory_size = matches.get_flag("directory-size");
    let mkdir_flag = matches.get_flag("mkdir");
    let media_type = matches.get_one::<String>("media-type").map(|s| match s.as_str() {
        "image" => MediaType::Image,
        "audio" => MediaType::Audio,
        "video" => MediaType::Video,
        _ => MediaType::Image,
    });
    let raw_media_type = matches.get_one::<String>("raw-media-type").cloned();
    let on_duplicate = match matches.get_one::<String>("on-duplicate-files").map(|s| s.as_str()).unwrap_or("error") {
        "error" => OnDuplicate::Error,
        "overwrite" => OnDuplicate::Overwrite,
        "rename" => OnDuplicate::Rename,
        _ => OnDuplicate::Error,
    };

    let upload_files: Option<Option<String>> = if matches.contains_id("upload-files") {
        if let Some(val) = matches.get_one::<String>("upload-files") {
            if val == "true_marker" {
                Some(None)
            } else {
                Some(Some(val.clone()))
            }
        } else {
            Some(None)
        }
    } else {
        None
    };

    if mkdir_flag && upload_files.is_none() {
        eprintln!("error: the following required arguments were not provided:\n  --upload-files [<ALLOWED_UPLOAD_DIR>]\n\nUsage: miniserve --upload-files [<ALLOWED_UPLOAD_DIR>] --port <PORT> --mkdir <PATH>\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    let rm_files: Option<Option<String>> = if matches.contains_id("rm-files") {
        if let Some(val) = matches.get_one::<String>("rm-files") {
            if val == "true_marker" {
                Some(None)
            } else {
                Some(Some(val.clone()))
            }
        } else {
            Some(None)
        }
    } else {
        None
    };

    let enable_tar = matches.get_flag("enable-tar");
    let enable_tar_gz = matches.get_flag("enable-tar-gz");
    let enable_zip = matches.get_flag("enable-zip");
    let compress_response = matches.get_flag("compress-response");
    let dirs_first = matches.get_flag("dirs-first");
    let title = matches.get_one::<String>("title").cloned();
    let mut headers_vec: Vec<(String,String)> = Vec::new();
    if let Some(vals) = matches.get_many::<String>("header") {
        for h in vals {
            if let Some((k,v)) = h.split_once(':') {
                headers_vec.push((k.trim().to_string(), v.trim().to_string()));
            }
        }
    }
    let show_symlink_info = matches.get_flag("show-symlink-info");
    let hide_version_footer = matches.get_flag("hide-version-footer");
    let hide_theme_selector = matches.get_flag("hide-theme-selector");
    let show_wget_footer = matches.get_flag("show-wget-footer");
    let readme = matches.get_flag("readme");
    let disable_indexing = matches.get_flag("disable-indexing");
    let enable_webdav = matches.get_flag("enable-webdav");
    let size_display = match matches.get_one::<String>("size-display").map(|s| s.as_str()).unwrap_or("human") {
        "human" => SizeDisplay::Human,
        "exact" => SizeDisplay::Exact,
        _ => SizeDisplay::Human,
    };
    let file_external_url = matches.get_one::<String>("file-external-url").cloned();

    let config = Arc::new(Config {
        verbose,
        temp_dir,
        index,
        spa,
        pretty_urls,
        port,
        interfaces,
        auth: auth_entries,
        route_prefix: normalized_route_prefix.clone(),
        random_route,
        random_route_value: random_route_value.clone(),
        no_symlinks,
        hidden,
        default_sorting_method,
        default_sorting_order,
        color_scheme,
        color_scheme_dark,
        qrcode,
        upload_files,
        web_upload_concurrency,
        chmod: chmod_opt,
        directory_size,
        mkdir: mkdir_flag,
        media_type,
        raw_media_type,
        on_duplicate,
        rm_files,
        enable_tar,
        enable_tar_gz,
        enable_zip,
        compress_response,
        dirs_first,
        title,
        headers: headers_vec,
        show_symlink_info,
        hide_version_footer,
        hide_theme_selector,
        show_wget_footer,
        tls_cert,
        tls_key,
        readme,
        disable_indexing,
        enable_webdav,
        size_display,
        file_external_url,
        serve_path,
        serve_path_is_file,
    });

    let bind_addr = if let Some(ref iface) = config.interfaces {
        format!("{}:{}", iface.split(',').next().unwrap().trim(), config.port)
    } else {
        format!("0.0.0.0:{}", config.port)
    };

    let listener = match TcpListener::bind(&bind_addr) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("{} [ERROR] Failed to bind server to {}", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), bind_addr);
            eprintln!("{} [ERROR] caused by: {}", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), e);
            eprintln!("Error: Failed to bind server to {}\ncaused by: {}", bind_addr, e);
            std::process::exit(1);
        }
    };

    println!("miniserve v{}", VERSION);
    if config.verbose {
        println!("{} [INFO] starting 20 workers", Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
    }
    if let Some(ref iface) = config.interfaces {
        println!("Bound to {}:{}", iface, config.port);
    } else {
        println!("Bound to [::]:{}, 0.0.0.0:{}", config.port, config.port);
    }
    println!("Serving path {}", config.serve_path.display());
    println!("Available at (non-exhaustive list):");
    let route_prefix_display = if let Some(ref rp) = config.route_prefix {
        rp.clone()
    } else {
        "".to_string()
    };
    if config.interfaces.is_some() {
        println!("    http://{}:{}{}", config.interfaces.as_ref().unwrap(), config.port, route_prefix_display);
    } else {
        println!("    http://127.0.0.1:{}{}", config.port, route_prefix_display);
        println!("    http://172.17.0.6:{}{}", config.port, route_prefix_display);
        println!("    http://[::1]:{}{}", config.port, route_prefix_display);
    }
    println!();

    if config.verbose {
        println!("{} [INFO] Actix runtime found; starting in Actix runtime", Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
        if config.interfaces.is_none() {
            println!("{} [INFO] starting service: \"actix-web-service-[::]:{}\", workers: 20, listening on: [::]:{}", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), config.port, config.port);
            println!("{} [INFO] starting service: \"actix-web-service-0.0.0.0:{}\", workers: 20, listening on: 0.0.0.0:{}", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), config.port, config.port);
        } else {
            println!("{} [INFO] starting service: \"actix-web-service-{}:{}\", workers: 20, listening on: {}:{}", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), config.interfaces.as_ref().unwrap(), config.port, config.interfaces.as_ref().unwrap(), config.port);
        }
    }

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let cfg = config.clone();
                thread::spawn(move || {
                    let _ = handle_connection(stream, cfg);
                });
            },
            Err(e) => {
                eprintln!("accept error: {}", e);
                thread::sleep(Duration::from_millis(100));
            }
        }
    }
}

fn handle_connection(mut stream: TcpStream, config: Arc<Config>) -> io::Result<()> {
    stream.set_read_timeout(Some(Duration::from_secs(30))).ok();
    stream.set_write_timeout(Some(Duration::from_secs(30))).ok();

    let mut reader = BufReader::new(&stream);
    let mut request_line = String::new();
    if reader.read_line(&mut request_line)? == 0 {
        return Ok(());
    }
    let request_line = request_line.trim_end().to_string();
    if request_line.is_empty() { return Ok(()); }
    let mut parts = request_line.split_whitespace();
    let method = parts.next().unwrap_or("GET").to_string();
    let raw_path = parts.next().unwrap_or("/").to_string();
    let _http_version = parts.next().unwrap_or("HTTP/1.1").to_string();

    let mut headers: HashMap<String, String> = HashMap::new();
    loop {
        let mut line = String::new();
        reader.read_line(&mut line)?;
        let line_trim = line.trim_end();
        if line_trim.is_empty() { break; }
        if let Some((k,v)) = line_trim.split_once(':') {
            headers.insert(k.trim().to_lowercase(), v.trim().to_string());
        }
    }

    let client_ip = stream.peer_addr().map(|a| a.ip().to_string()).unwrap_or("127.0.0.1".to_string());

    let (path_part, query_part) = if let Some((p,q)) = raw_path.split_once('?') {
        (p.to_string(), Some(q.to_string()))
    } else {
        (raw_path.clone(), None)
    };

    let decoded_path = percent_decode_str(&path_part).decode_utf8_lossy().to_string();

    let mut query_params: HashMap<String, String> = HashMap::new();
    if let Some(q) = &query_part {
        for (k,v) in form_urlencoded::parse(q.as_bytes()) {
            query_params.insert(k.to_string(), v.to_string());
        }
    }

    let mut effective_path = decoded_path.clone();
    if let Some(ref rp) = config.route_prefix {
        if effective_path == *rp {
            effective_path = "/".to_string();
        } else if effective_path.starts_with(&format!("{}/", rp)) {
            effective_path = effective_path[rp.len()..].to_string();
            if effective_path.is_empty() { effective_path = "/".to_string(); }
            if !effective_path.starts_with('/') { effective_path = format!("/{}", effective_path); }
        } else {
            let resp = build_404(&config, &effective_path, &raw_path, &query_params, &headers, method.clone(), client_ip.clone(), true);
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }
    }

    if !config.auth.is_empty() {
        let auth_header = headers.get("authorization");
        let mut authorized = false;
        if let Some(auth_val) = auth_header {
            if auth_val.to_lowercase().starts_with("basic ") {
                let b64_part = auth_val[6..].trim();
                if let Ok(decoded) = BASE64.decode(b64_part) {
                    if let Ok(decoded_str) = String::from_utf8(decoded) {
                        if let Some((user, pass)) = decoded_str.split_once(':') {
                            for entry in &config.auth {
                                if entry.username == user {
                                    if check_auth(entry, pass) {
                                        authorized = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        if !authorized {
            let mut resp_headers = vec![
                ("WWW-Authenticate".to_string(), "Basic".to_string()),
                ("Content-Length".to_string(), "0".to_string()),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            for (k,v) in &config.headers {
                if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                    resp_headers.push((k.clone(), v.clone()));
                }
            }
            let resp = HttpResponse {
                status_code: 401,
                reason: "Unauthorized".to_string(),
                headers: resp_headers,
                body: vec![],
            };
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            if config.verbose {
                println!("{} [INFO] {} \"{} {} HTTP/1.1\" 401 0 \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path);
            }
            return Ok(());
        }
    }

    if effective_path.starts_with("/__miniserve_internal/") {
        if effective_path == "/__miniserve_internal/favicon.svg" {
            let body = FAVICON_SVG.as_bytes().to_vec();
            let mut resp_headers = vec![
                ("Content-Type".to_string(), "image/svg+xml".to_string()),
                ("Content-Length".to_string(), body.len().to_string()),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            for (k,v) in &config.headers {
                if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                    resp_headers.push((k.clone(), v.clone()));
                }
            }
            let resp = HttpResponse {
                status_code: 200,
                reason: "OK".to_string(),
                headers: resp_headers,
                body,
            };
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        } else if effective_path == "/__miniserve_internal/style.css" {
            let css_content = get_style_css();
            let body = css_content.into_bytes();
            let mut resp_headers = vec![
                ("Content-Type".to_string(), "text/css; charset=utf-8".to_string()),
                ("Content-Length".to_string(), body.len().to_string()),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            for (k,v) in &config.headers {
                if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                    resp_headers.push((k.clone(), v.clone()));
                }
            }
            let resp = HttpResponse {
                status_code: 200,
                reason: "OK".to_string(),
                headers: resp_headers,
                body,
            };
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        } else if effective_path == "/__miniserve_internal/api" {
            let content_length: usize = headers.get("content-length").and_then(|v| v.parse().ok()).unwrap_or(0);
            let mut body_buf = vec![0u8; content_length];
            if content_length > 0 {
                reader.read_exact(&mut body_buf)?;
            }
            let body_str = String::from_utf8_lossy(&body_buf);
            let mut dir_path_str: Option<String> = None;
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&body_str) {
                if let Some(obj) = json.as_object() {
                    if let Some(serde_json::Value::String(s)) = obj.get("DirSize") {
                        dir_path_str = Some(s.clone());
                    }
                }
            }
            if let Some(dp) = dir_path_str {
                if config.directory_size {
                    let fs_path = path_from_url(&config, &dp);
                    let size = calculate_dir_size(&fs_path, &config);
                    let size_str = format_size(size, &config.size_display);
                    let body = size_str.into_bytes();
                    let mut resp_headers = vec![
                        ("Content-Type".to_string(), "text/plain; charset=utf-8".to_string()),
                        ("Content-Length".to_string(), body.len().to_string()),
                        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                    ];
                    for (k,v) in &config.headers {
                        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                            resp_headers.push((k.clone(), v.clone()));
                        }
                    }
                    let resp = HttpResponse {
                        status_code: 200,
                        reason: "OK".to_string(),
                        headers: resp_headers,
                        body,
                    };
                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                } else {
                    let resp = build_simple_text_response(404, "Not Found", &config);
                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                }
            } else {
                let resp = build_simple_text_response(400, "Bad Request", &config);
                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            }
            return Ok(());
        } else {
            let resp = build_404(&config, &effective_path, &raw_path, &query_params, &headers, method.clone(), client_ip.clone(), false);
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }
    }

    if effective_path.starts_with("/upload") && method == "POST" {
        let upload_path_param = query_params.get("path").cloned().unwrap_or("/".to_string());

        if config.upload_files.is_none() {
            let resp = build_simple_text_response(403, "Forbidden", &config);
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }

        let allowed_upload_dir = match &config.upload_files {
            Some(None) => None,
            Some(Some(dir_str)) => Some(dir_str.clone()),
            None => None,
        };

        if let Some(ref allowed) = allowed_upload_dir {
            let allowed_norm = if allowed.ends_with('/') { allowed.clone() } else { format!("{}/", allowed) };
            let param_norm = if upload_path_param.ends_with('/') { upload_path_param.clone() } else { format!("{}/", upload_path_param) };
            if upload_path_param != *allowed && !param_norm.starts_with(&allowed_norm) && !(allowed == "/" || allowed.is_empty()) {
                let body = b"Upload not allowed to this directory".to_vec();
                let mut resp_headers = vec![
                    ("Content-Type".to_string(), "text/plain; charset=utf-8".to_string()),
                    ("Content-Length".to_string(), body.len().to_string()),
                    ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                ];
                for (k,v) in &config.headers {
                    if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                        resp_headers.push((k.clone(), v.clone()));
                    }
                }
                let resp = HttpResponse {
                    status_code: 403,
                    reason: "Forbidden".to_string(),
                    headers: resp_headers,
                    body,
                };
                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                return Ok(());
            }
        }

        let content_length: usize = headers.get("content-length").and_then(|v| v.parse().ok()).unwrap_or(0);
        let content_type = headers.get("content-type").cloned().unwrap_or_default();
        if content_type.starts_with("multipart/form-data") {
            let boundary = if let Some(b) = content_type.split("boundary=").nth(1) {
                b.trim_matches('"').to_string()
            } else {
                "".to_string()
            };
            let mut body_buf = vec![0u8; content_length];
            reader.read_exact(&mut body_buf)?;

            match parse_multipart(&body_buf, &boundary) {
                Ok(parts) => {
                    for part in parts {
                        let disp = part.headers.get("content-disposition").cloned().unwrap_or_default();
                        let name = extract_disposition_param(&disp, "name");
                        let filename = extract_disposition_param(&disp, "filename");

                        if let Some(fname) = filename {
                            let base_name = Path::new(&fname).file_name().and_then(|n| n.to_str()).unwrap_or(&fname).to_string();
                            if base_name.is_empty() { continue; }

                            if let Some(mt) = &config.media_type {
                                if !check_media_type(&base_name, mt) {
                                    let body = format!("File type not allowed: {}", base_name).into_bytes();
                                    let resp = HttpResponse {
                                        status_code: 400,
                                        reason: "Bad Request".to_string(),
                                        headers: vec![("Content-Type".to_string(),"text/plain".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                                        body,
                                    };
                                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                                    return Ok(());
                                }
                            }

                            let target_dir_fs = path_from_url(&config, &upload_path_param);
                            if !target_dir_fs.exists() || !target_dir_fs.is_dir() {
                                let body = format!("Invalid path\ncaused by: cannot upload file to {}, since it's not a directory", target_dir_fs.display()).into_bytes();
                                let resp = HttpResponse {
                                    status_code: 400,
                                    reason: "Bad Request".to_string(),
                                    headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                                    body,
                                };
                                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                                return Ok(());
                            }

                            let mut dest_path = target_dir_fs.join(&base_name);
                            match config.on_duplicate {
                                OnDuplicate::Error => {
                                    if dest_path.exists() {
                                        let body = format!("File {} already exists", base_name).into_bytes();
                                        let resp = HttpResponse {
                                            status_code: 400,
                                            reason: "Bad Request".to_string(),
                                            headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                                            body,
                                        };
                                        write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                                        return Ok(());
                                    }
                                },
                                OnDuplicate::Overwrite => {},
                                OnDuplicate::Rename => {
                                    if dest_path.exists() {
                                        dest_path = generate_rename_path(&target_dir_fs, &base_name);
                                    }
                                }
                            }

                            let write_result = if let Some(ref temp_dir) = config.temp_dir {
                                let temp_file_name = format!("miniserve_tmp_{}", Utc::now().timestamp_nanos_opt().unwrap_or(0));
                                let temp_path = temp_dir.join(temp_file_name);
                                match fs::write(&temp_path, &part.body) {
                                    Ok(_) => {
                                        match fs::rename(&temp_path, &dest_path) {
                                            Ok(_) => Ok(()),
                                            Err(_) => {
                                                match fs::copy(&temp_path, &dest_path) {
                                                    Ok(_) => { fs::remove_file(&temp_path).ok(); Ok(()) },
                                                    Err(e2) => Err(e2),
                                                }
                                            }
                                        }
                                    },
                                    Err(e) => Err(e),
                                }
                            } else {
                                fs::write(&dest_path, &part.body)
                            };

                            if let Err(e) = write_result {
                                let body = format!("Failed to write file: {}", e).into_bytes();
                                let resp = HttpResponse {
                                    status_code: 500,
                                    reason: "Internal Server Error".to_string(),
                                    headers: vec![("Content-Type".to_string(),"text/plain".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                                    body,
                                };
                                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                                return Ok(());
                            }

                            if let Some(mode) = config.chmod {
                                #[cfg(unix)]
                                {
                                    use std::os::unix::fs::PermissionsExt;
                                    let perm = fs::Permissions::from_mode(mode);
                                    let _ = fs::set_permissions(&dest_path, perm);
                                }
                            }
                        } else {
                            if name.as_deref() == Some("mkdir") {
                                if !config.mkdir {
                                    let body = format!("Insufficient permissions to create file in {}", path_from_url(&config, &upload_path_param).display()).into_bytes();
                                    let resp = HttpResponse {
                                        status_code: 403,
                                        reason: "Forbidden".to_string(),
                                        headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                                        body,
                                    };
                                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                                    return Ok(());
                                }
                                let dir_name = String::from_utf8_lossy(&part.body).trim().to_string();
                                if dir_name.is_empty() { continue; }
                                if dir_name.contains('/') || dir_name.contains('\\') || dir_name.contains("..") {
                                    let body = b"Invalid directory name".to_vec();
                                    let resp = HttpResponse {
                                        status_code: 400,
                                        reason: "Bad Request".to_string(),
                                        headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                                        body,
                                    };
                                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                                    return Ok(());
                                }
                                let target_dir_fs = path_from_url(&config, &upload_path_param);
                                let new_dir_path = target_dir_fs.join(&dir_name);
                                if let Err(e) = fs::create_dir(&new_dir_path) {
                                    let body = format!("Failed to create dir: {}", e).into_bytes();
                                    let resp = HttpResponse {
                                        status_code: 500,
                                        reason: "Internal Server Error".to_string(),
                                        headers: vec![("Content-Type".to_string(),"text/plain".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                                        body,
                                    };
                                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                                    return Ok(());
                                }
                            }
                        }
                    }

                    let location = if upload_path_param.is_empty() { "/".to_string() } else { 
                        let loc = if upload_path_param.starts_with('/') { upload_path_param.clone() } else { format!("/{}", upload_path_param) };
                        if let Some(ref rp) = config.route_prefix {
                            format!("{}{}", rp, loc)
                        } else {
                            loc
                        }
                    };
                    let mut resp_headers = vec![
                        ("Location".to_string(), location),
                        ("Content-Length".to_string(), "0".to_string()),
                        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                    ];
                    for (k,v) in &config.headers {
                        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                            resp_headers.push((k.clone(), v.clone()));
                        }
                    }
                    let resp = HttpResponse {
                        status_code: 303,
                        reason: "See Other".to_string(),
                        headers: resp_headers,
                        body: vec![],
                    };
                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                    return Ok(());
                },
                Err(e) => {
                    let body = format!("Failed to parse multipart: {}", e).into_bytes();
                    let resp = HttpResponse {
                        status_code: 400,
                        reason: "Bad Request".to_string(),
                        headers: vec![("Content-Type".to_string(),"text/plain".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                        body,
                    };
                    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                    return Ok(());
                }
            }
        } else {
            let body = b"Unsupported upload".to_vec();
            let resp = HttpResponse {
                status_code: 400,
                reason: "Bad Request".to_string(),
                headers: vec![("Content-Type".to_string(),"text/plain".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                body,
            };
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }
    }

    if effective_path.starts_with("/rm") && method == "POST" {
        if config.rm_files.is_none() {
            let resp = build_simple_text_response(403, "Forbidden", &config);
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }
        let rm_path_param = query_params.get("path").cloned().unwrap_or("/".to_string());
        let allowed_rm_dir = match &config.rm_files {
            Some(None) => None,
            Some(Some(dir_str)) => Some(dir_str.clone()),
            None => None,
        };
        if let Some(ref allowed) = allowed_rm_dir {
            let allowed_norm = if allowed.ends_with('/') { allowed.clone() } else { format!("{}/", allowed) };
            let param_norm = if rm_path_param.ends_with('/') { rm_path_param.clone() } else { format!("{}/", rm_path_param) };
            if rm_path_param != *allowed && !param_norm.starts_with(&allowed_norm) && !(allowed == "/" || allowed.is_empty()) {
                let body = b"Deletion not allowed in this directory".to_vec();
                let resp = HttpResponse {
                    status_code: 403,
                    reason: "Forbidden".to_string(),
                    headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                    body,
                };
                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                return Ok(());
            }
        }

        let target_fs = path_from_url(&config, &rm_path_param);
        if !target_fs.exists() {
            let resp = build_simple_text_response(404, "Not Found", &config);
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }
        if !target_fs.starts_with(&config.serve_path) && !config.serve_path_is_file {
            let resp = build_simple_text_response(403, "Forbidden", &config);
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }

        let res = if target_fs.is_dir() {
            fs::remove_dir_all(&target_fs)
        } else {
            fs::remove_file(&target_fs)
        };

        match res {
            Ok(_) => {
                let mut resp_headers = vec![
                    ("Location".to_string(), "/".to_string()),
                    ("Content-Length".to_string(), "0".to_string()),
                    ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                ];
                for (k,v) in &config.headers {
                    if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                        resp_headers.push((k.clone(), v.clone()));
                    }
                }
                let resp = HttpResponse {
                    status_code: 303,
                    reason: "See Other".to_string(),
                    headers: resp_headers,
                    body: vec![],
                };
                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                return Ok(());
            },
            Err(e) => {
                let body = format!("Failed to delete: {}", e).into_bytes();
                let resp = HttpResponse {
                    status_code: 500,
                    reason: "Internal Server Error".to_string(),
                    headers: vec![("Content-Type".to_string(),"text/plain".to_string()),("Content-Length".to_string(),body.len().to_string()),("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string())],
                    body,
                };
                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                return Ok(());
            }
        }
    }

    if config.serve_path_is_file {
        if effective_path == "/" {
            return serve_file(&mut stream, &config, &config.serve_path, &method, &headers, &query_params, &client_ip, &raw_path);
        } else {
            let resp = build_404(&config, &effective_path, &raw_path, &query_params, &headers, method.clone(), client_ip.clone(), false);
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            if config.verbose {
                println!("{} [ERROR] Route {} could not be found", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), effective_path);
            }
            return Ok(());
        }
    }

    let fs_path = path_from_url(&config, &effective_path);

    let serve_canonical = config.serve_path.canonicalize().unwrap_or(config.serve_path.clone());
    let fs_canonical_attempt = fs_path.canonicalize().unwrap_or_else(|_| {
        if let Some(parent) = fs_path.parent() {
            if let Ok(p) = parent.canonicalize() {
                p.join(fs_path.file_name().unwrap_or_default())
            } else {
                fs_path.clone()
            }
        } else {
            fs_path.clone()
        }
    });

    if config.no_symlinks {
        if let Ok(meta) = fs::symlink_metadata(&fs_path) {
            if meta.file_type().is_symlink() {
                let resp = build_404(&config, &effective_path, &raw_path, &query_params, &headers, method.clone(), client_ip.clone(), false);
                write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
                if config.verbose {
                    println!("{} [ERROR] Route {} could not be found", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), effective_path);
                }
                return Ok(());
            }
        }
    }

    if !fs_canonical_attempt.starts_with(&serve_canonical) {
        let resp = build_404(&config, &effective_path, &raw_path, &query_params, &headers, method.clone(), client_ip.clone(), false);
        write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
        if config.verbose {
            println!("{} [ERROR] Route {} could not be found", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), effective_path);
        }
        return Ok(());
    }

    if fs_path.is_file() {
        return serve_file(&mut stream, &config, &fs_path, &method, &headers, &query_params, &client_ip, &raw_path);
    }

    if fs_path.is_dir() {
        if let Some(dl) = query_params.get("download") {
            match dl.as_str() {
                "tar" => {
                    if config.enable_tar {
                        return serve_tar(&mut stream, &config, &fs_path, false, &method, &headers, &query_params, &client_ip, &raw_path);
                    }
                },
                "tar_gz" => {
                    if config.enable_tar_gz {
                        return serve_tar(&mut stream, &config, &fs_path, true, &method, &headers, &query_params, &client_ip, &raw_path);
                    }
                },
                "zip" => {
                    if config.enable_zip {
                        return serve_zip(&mut stream, &config, &fs_path, &method, &headers, &query_params, &client_ip, &raw_path);
                    }
                },
                _ => {}
            }
        }

        if let Some(ref idx_name) = config.index {
            let idx_path = fs_path.join(idx_name);
            if idx_path.is_file() {
                return serve_file(&mut stream, &config, &idx_path, &method, &headers, &query_params, &client_ip, &raw_path);
            }
        }

        if config.disable_indexing {
            let resp = build_404_file_not_found(&config, &effective_path, &raw_path, &query_params, &headers, method.clone(), client_ip.clone());
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            if config.verbose {
                println!("{} [ERROR] Route {} could not be found", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), effective_path);
            }
            return Ok(());
        }

        if !effective_path.ends_with('/') {
            let mut new_path = effective_path.clone() + "/";
            if let Some(q) = &query_part {
                new_path = format!("{}?{}", new_path, q);
            }
            let location = if let Some(ref rp) = config.route_prefix {
                format!("{}{}", rp, new_path)
            } else {
                new_path
            };
            let mut resp_headers = vec![
                ("Location".to_string(), location),
                ("Content-Length".to_string(), "0".to_string()),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            for (k,v) in &config.headers {
                if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                    resp_headers.push((k.clone(), v.clone()));
                }
            }
            let resp = HttpResponse {
                status_code: 301,
                reason: "Moved Permanently".to_string(),
                headers: resp_headers,
                body: vec![],
            };
            write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
            return Ok(());
        }

        return serve_directory(&mut stream, &config, &fs_path, &effective_path, &raw_path, &method, &headers, &query_params, &client_ip);
    }

    if config.pretty_urls {
        let mut html_candidate = fs_path.clone();
        html_candidate.set_extension("html");
        if html_candidate.is_file() {
            return serve_file(&mut stream, &config, &html_candidate, &method, &headers, &query_params, &client_ip, &raw_path);
        }
    }

    if config.spa {
        if let Some(ref idx_name) = config.index {
            let idx_path = config.serve_path.join(idx_name);
            if idx_path.is_file() {
                return serve_file(&mut stream, &config, &idx_path, &method, &headers, &query_params, &client_ip, &raw_path);
            }
        }
    }

    let resp = build_404(&config, &effective_path, &raw_path, &query_params, &headers, method.clone(), client_ip.clone(), false);
    write_response(&mut stream, &config, resp, &method, &headers, &query_params)?;
    if config.verbose {
        println!("{} [ERROR] Route {} could not be found", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), effective_path);
    }
    Ok(())
}

fn path_from_url(config: &Config, url_path: &str) -> PathBuf {
    let trimmed = url_path.trim_start_matches('/');
    let mut pb = config.serve_path.clone();
    for comp in Path::new(trimmed).components() {
        match comp {
            Component::Normal(os) => pb.push(os),
            Component::ParentDir => { pb.pop(); },
            Component::CurDir => {},
            _ => {},
        }
    }
    pb
}

fn format_size(size: u64, display: &SizeDisplay) -> String {
    match display {
        SizeDisplay::Exact => format!("{} B", size),
        SizeDisplay::Human => {
            if size < 1024 {
                format!("{} B", size)
            } else if size < 1024*1024 {
                format!("{:.1} KiB", size as f64 / 1024.0)
            } else if size < 1024*1024*1024 {
                format!("{:.1} MiB", size as f64 / (1024.0*1024.0))
            } else {
                format!("{:.1} GiB", size as f64 / (1024.0*1024.0*1024.0))
            }
        }
    }
}

fn calculate_dir_size(path: &Path, config: &Config) -> u64 {
    let mut total = 0u64;
    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries.flatten() {
            let p = entry.path();
            if !config.hidden {
                if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
                    if name.starts_with('.') { continue; }
                }
            }
            if config.no_symlinks {
                if let Ok(meta) = fs::symlink_metadata(&p) {
                    if meta.file_type().is_symlink() { continue; }
                }
            }
            if let Ok(meta) = fs::metadata(&p) {
                if meta.is_dir() {
                    total += calculate_dir_size(&p, config);
                } else {
                    total += meta.len();
                }
            }
        }
    }
    total
}

struct HttpResponse {
    status_code: u16,
    reason: String,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

fn build_simple_text_response(status: u16, text: &str, config: &Config) -> HttpResponse {
    let body = text.as_bytes().to_vec();
    let mut headers = vec![
        ("Content-Type".to_string(), "text/plain; charset=utf-8".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            headers.push((k.clone(), v.clone()));
        }
    }
    HttpResponse {
        status_code: status,
        reason: match status { 200=>"OK", 404=>"Not Found", 403=>"Forbidden", 400=>"Bad Request", 500=>"Internal Server Error", 401=>"Unauthorized", _=>"OK" }.to_string(),
        headers,
        body,
    }
}

fn build_404(config: &Config, effective_path: &str, raw_path: &str, query_params: &HashMap<String,String>, headers: &HashMap<String,String>, method: String, client_ip: String, is_route_prefix_mismatch: bool) -> HttpResponse {
    let route_display = effective_path;
    let title = "404 Not Found";
    let body_html = format!(r#"<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{prefix}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{prefix}/__miniserve_internal/style.css"><title>{title}</title><script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {{
                        if (name && name != "default") {{
                            localStorage.setItem('theme', name);
                            document.body.setAttribute("data-theme", name)
                        }} else {{
                            localStorage.removeItem('theme');
                            document.body.removeAttribute("data-theme")
                        }}
                    }}

                    // read theme from local storage and apply it to body
                    function loadColorScheme() {{
                        var name = localStorage.getItem('theme');
                        updateColorScheme(name);
                    }}

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script><script>const API_ROUTE = '{prefix}/__miniserve_internal/api';
                    let dirSizeCache = {{}};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {{
                        return fetch(API_ROUTE, {{
                            headers: {{
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            }},
                            method: 'POST',
                            body: JSON.stringify({{
                                DirSize: dir
                            }})
                        }}).then(resp => resp.ok ? resp.text() : "~")
                    }}

                    function updateSizeCells() {{
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {{
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {{
                                cell.dataset.size = dirSizeCache[target];
                            }} else {{
                                fetchDirSize(target).then(dir_size => {{
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                }})
                                .catch(error => console.error("Error fetching dir size:", error));
                            }}
                        }})
                    }}
                    setInterval(updateSizeCells, 1000);
                </script></head><body><div class="error"><p>404 Not Found</p><p>Route {route} could not be found</p><div class="error-nav"><a class="error-back" href="{root}">Go back to file listing</a></div><p class="footer">{footer}</p></div></body></html>"#,
        prefix = config.route_prefix.clone().unwrap_or_default(),
        title = title,
        route = route_display,
        root = config.route_prefix.clone().unwrap_or_else(|| "/".to_string()),
        footer = if config.hide_version_footer { "".to_string() } else { format!(r#"<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/{}</div>"#, VERSION) }
    );

    let body = body_html.into_bytes();
    let mut resp_headers = vec![
        ("Content-Type".to_string(), "text/html".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }

    HttpResponse {
        status_code: 404,
        reason: "Not Found".to_string(),
        headers: resp_headers,
        body,
    }
}

