fn check_media_type(filename: &str, mt: &MediaType) -> bool {
    let ext = Path::new(filename).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match mt {
        MediaType::Image => matches!(ext.as_str(), "jpg"|"jpeg"|"png"|"gif"|"bmp"|"webp"|"svg"|"ico"|"tiff"|"avif"),
        MediaType::Audio => matches!(ext.as_str(), "mp3"|"wav"|"ogg"|"flac"|"aac"|"m4a"|"wma"),
        MediaType::Video => matches!(ext.as_str(), "mp4"|"avi"|"mkv"|"mov"|"wmv"|"flv"|"webm"|"m4v"),
    }
}

fn generate_rename_path(dir: &Path, original_name: &str) -> PathBuf {
    let path = Path::new(original_name);
    let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or(original_name);
    let ext = path.extension().and_then(|e| e.to_str()).map(|e| format!(".{}", e)).unwrap_or_default();
    let mut counter = 1;
    loop {
        let new_name = format!("{}-{}{}", stem, counter, ext);
        let new_path = dir.join(&new_name);
        if !new_path.exists() {
            return new_path;
        }
        counter += 1;
    }
}

struct MultipartPart {
    headers: HashMap<String, String>,
    body: Vec<u8>,
}

fn parse_multipart(data: &[u8], boundary: &str) -> Result<Vec<MultipartPart>, String> {
    if boundary.is_empty() {
        return Err("no boundary".to_string());
    }
    let b_marker = format!("--{}", boundary).into_bytes();
    let boundary_bytes = format!("\r\n--{}", boundary).into_bytes();

    let mut parts: Vec<MultipartPart> = Vec::new();
    let mut pos = 0usize;
    while pos < data.len() {
        if let Some(b_pos) = data[pos..].windows(b_marker.len()).position(|w| w == b_marker.as_slice()) {
            let abs_b_pos = pos + b_pos;
            let after_boundary = abs_b_pos + b_marker.len();
            let mut header_start = after_boundary;
            if data.len() > header_start+1 && data[header_start]==b'\r' && data[header_start+1]==b'\n' {
                header_start += 2;
            }
            if let Some(h_end) = data[header_start..].windows(4).position(|w| w == b"\r\n\r\n") {
                let header_end = header_start + h_end;
                let body_start = header_end + 4;
                if let Some(next_b) = data[body_start..].windows(boundary_bytes.len()).position(|w| w == boundary_bytes.as_slice()) {
                    let body_end = body_start + next_b;
                    let header_bytes = &data[header_start..header_end];
                    let body_bytes = &data[body_start..body_end];
                    let header_str = String::from_utf8_lossy(header_bytes);
                    let mut headers = HashMap::new();
                    for line in header_str.lines() {
                        if let Some((k,v)) = line.split_once(':') {
                            headers.insert(k.trim().to_lowercase(), v.trim().to_string());
                        }
                    }
                    parts.push(MultipartPart { headers, body: body_bytes.to_vec() });
                    pos = body_end;
                    continue;
                } else {
                    // Look for end marker --boundary--
                    let end_marker = format!("--{}--", boundary).into_bytes();
                    if let Some(end_pos) = data[body_start..].windows(end_marker.len()).position(|w| w == end_marker.as_slice()) {
                        let body_end = body_start + end_pos;
                        // Trim trailing \r\n
                        let body_end_trimmed = if body_end >= 2 && data[body_end-2]==b'\r' && data[body_end-1]==b'\n' {
                            body_end -2
                        } else { body_end };
                        let header_bytes = &data[header_start..header_end];
                        let body_bytes = &data[body_start..body_end_trimmed];
                        let header_str = String::from_utf8_lossy(header_bytes);
                        let mut headers = HashMap::new();
                        for line in header_str.lines() {
                            if let Some((k,v)) = line.split_once(':') {
                                headers.insert(k.trim().to_lowercase(), v.trim().to_string());
                            }
                        }
                        parts.push(MultipartPart { headers, body: body_bytes.to_vec() });
                        break;
                    } else {
                        break;
                    }
                }
            } else {
                break;
            }
        } else {
            break;
        }
    }
    Ok(parts)
}

fn extract_disposition_param(disp: &str, param: &str) -> Option<String> {
    for part in disp.split(';') {
        let part = part.trim();
        if let Some((k,v)) = part.split_once('=') {
            if k.trim() == param {
                let mut val = v.trim().to_string();
                if val.starts_with('"') && val.ends_with('"') && val.len() >= 2 {
                    val = val[1..val.len()-1].to_string();
                }
                return Some(val);
            }
        }
    }
    None
}

fn serve_file(stream: &mut TcpStream, config: &Config, file_path: &Path, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>, client_ip: &str, raw_path: &str) -> io::Result<()> {
    let meta = fs::metadata(file_path);
    if let Err(_) = meta {
        let resp = build_404(config, &path_from_url(config, raw_path).display().to_string(), raw_path, query_params, req_headers, method.to_string(), client_ip.to_string(), false);
        write_response(stream, config, resp, method, req_headers, query_params)?;
        return Ok(());
    }
    let meta = meta.unwrap();
    let file_len = meta.len();
    let modified = meta.modified().unwrap_or(SystemTime::now());
    let modified_chrono: DateTime<Utc> = modified.into();
    let last_modified_str = modified_chrono.format("%a, %d %b %Y %H:%M:%S GMT").to_string();

    let etag = {
        let secs = modified.duration_since(UNIX_EPOCH).unwrap_or(Duration::new(0,0)).as_secs();
        format!("\"{:x}:{:x}:{:x}\"", secs, file_len, file_path.display().to_string().len())
    };

    if let Some(if_none) = req_headers.get("if-none-match") {
        if if_none.trim() == etag || if_none.trim() == etag.trim_matches('"') {
            let body: Vec<u8> = vec![];
            let mut resp_headers = vec![
                ("Content-Disposition".to_string(), format!("inline; filename=\"{}\"", file_path.file_name().and_then(|n| n.to_str()).unwrap_or("file"))),
                ("Accept-Ranges".to_string(), "bytes".to_string()),
                ("Last-Modified".to_string(), last_modified_str.clone()),
                ("ETag".to_string(), etag.clone()),
                ("Content-Type".to_string(), guess_content_type(file_path)),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            let mut seen = std::collections::HashSet::new();
            let mut final_headers = Vec::new();
            for (k,v) in resp_headers {
                let lk = k.to_lowercase();
                if !seen.contains(&lk) {
                    seen.insert(lk);
                    final_headers.push((k,v));
                }
            }
            for (k,v) in &config.headers {
                if !seen.contains(&k.to_lowercase()) {
                    final_headers.push((k.clone(), v.clone()));
                }
            }
            let resp = HttpResponse {
                status_code: 304,
                reason: "Not Modified".to_string(),
                headers: final_headers,
                body,
            };
            write_response(stream, config, resp, method, req_headers, query_params)?;
            if config.verbose {
                println!("{} [INFO] {} \"{} {} HTTP/1.1\" 304 0 \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path);
            }
            return Ok(());
        }
    }

    let mut start: u64 = 0;
    let mut end: u64 = file_len.saturating_sub(1);
    let mut is_partial = false;
    if let Some(range_header) = req_headers.get("range") {
        if range_header.starts_with("bytes=") {
            let range_spec = &range_header[6..];
            if let Some((s,e)) = range_spec.split_once('-') {
                let s_parsed = if s.is_empty() { None } else { s.parse::<u64>().ok() };
                let e_parsed = if e.is_empty() { None } else { e.parse::<u64>().ok() };
                match (s_parsed, e_parsed) {
                    (Some(s_val), Some(e_val)) => {
                        start = s_val.min(file_len.saturating_sub(1));
                        end = e_val.min(file_len.saturating_sub(1));
                        is_partial = true;
                    },
                    (Some(s_val), None) => {
                        start = s_val;
                        end = file_len.saturating_sub(1);
                        is_partial = true;
                    },
                    (None, Some(e_val)) => {
                        if e_val <= file_len {
                            start = file_len - e_val;
                            end = file_len -1;
                            is_partial = true;
                        }
                    },
                    _ => {}
                }
            }
        }
    }

    let content_length = if is_partial { end - start + 1 } else { file_len };

    let mut file = File::open(file_path)?;
    let mut body: Vec<u8> = Vec::with_capacity(content_length as usize);
    if is_partial {
        use std::io::Seek;
        file.seek(std::io::SeekFrom::Start(start))?;
        let mut limited = file.take(content_length);
        limited.read_to_end(&mut body)?;
    } else {
        if method != "HEAD" {
            file.read_to_end(&mut body)?;
        }
    }

    let content_type = guess_content_type(file_path);

    let disposition_type = if file_path.file_name().and_then(|n| n.to_str()).map(|n| n.starts_with('.')).unwrap_or(false) {
        "attachment"
    } else {
        if content_type == "application/octet-stream" {
            "attachment"
        } else {
            "inline"
        }
    };

    let filename = file_path.file_name().and_then(|n| n.to_str()).unwrap_or("file");
    let content_disposition = format!("{}; filename=\"{}\"", disposition_type, filename);

    let mut resp_headers = vec![
        ("Content-Length".to_string(), content_length.to_string()),
        ("Content-Type".to_string(), content_type.clone()),
        ("Content-Disposition".to_string(), content_disposition),
        ("Accept-Ranges".to_string(), "bytes".to_string()),
        ("Last-Modified".to_string(), last_modified_str),
        ("ETag".to_string(), etag.clone()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];

    if is_partial {
        resp_headers.push(("Content-Range".to_string(), format!("bytes {}-{}/{}", start, end, file_len)));
    }

    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }

    let status = if is_partial { 206 } else { 200 };
    let reason = if is_partial { "Partial Content" } else { "OK" };

    let resp = HttpResponse {
        status_code: status,
        reason: reason.to_string(),
        headers: resp_headers,
        body: if method == "HEAD" { vec![] } else { body },
    };

    let bytes_sent = resp.body.len();
    write_response(stream, config, resp, method, req_headers, query_params)?;

    if config.verbose {
        println!("{} [INFO] {} \"{} {} HTTP/1.1\" {} {} \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path, status, bytes_sent);
    }

    Ok(())
}

fn guess_content_type(path: &Path) -> String {
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match ext.as_str() {
        "html"|"htm" => "text/html; charset=utf-8".to_string(),
        "css" => "text/css; charset=utf-8".to_string(),
        "js" => "text/javascript; charset=utf-8".to_string(),
        "json" => "application/json".to_string(),
        "txt"|"md"|"rs"|"toml"|"yaml"|"yml" => "text/plain; charset=utf-8".to_string(),
        "svg" => "image/svg+xml".to_string(),
        "png" => "image/png".to_string(),
        "jpg"|"jpeg" => "image/jpeg".to_string(),
        "gif" => "image/gif".to_string(),
        "webp" => "image/webp".to_string(),
        "ico" => "image/x-icon".to_string(),
        "mp3" => "audio/mpeg".to_string(),
        "wav" => "audio/wav".to_string(),
        "mp4" => "video/mp4".to_string(),
        "pdf" => "application/pdf".to_string(),
        "zip" => "application/zip".to_string(),
        "tar" => "application/x-tar".to_string(),
        "gz"|"tgz" => "application/gzip".to_string(),
        _ => "application/octet-stream".to_string(),
    }
}

fn write_response(stream: &mut TcpStream, config: &Config, resp: HttpResponse, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>) -> io::Result<()> {
    let mut body = resp.body;
    let mut headers = resp.headers;

    let should_compress = config.compress_response && 
        req_headers.get("accept-encoding").map(|v| v.contains("gzip")).unwrap_or(false) &&
        body.len() > 0 &&
        headers.iter().any(|(k,v)| k.to_lowercase()=="content-type" && (v.contains("text/html") || v.contains("text/plain") || v.contains("application/json") || v.contains("text/css") || v.contains("javascript")));

    if should_compress {
        let mut encoder = GzEncoder::new(Vec::new(), FlateCompression::default());
        if encoder.write_all(&body).is_ok() {
            if let Ok(compressed) = encoder.finish() {
                body = compressed;
                headers.retain(|(k,_)| k.to_lowercase() != "content-length");
                headers.push(("Content-Length".to_string(), body.len().to_string()));
                headers.push(("Content-Encoding".to_string(), "gzip".to_string()));
                headers.push(("Vary".to_string(), "accept-encoding".to_string()));
            }
        }
    }

    if !headers.iter().any(|(k,_)| k.to_lowercase()=="date") {
        headers.push(("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()));
    }

    let mut resp_str = format!("HTTP/1.1 {} {}\r\n", resp.status_code, resp.reason);
    for (k,v) in &headers {
        resp_str.push_str(&format!("{}: {}\r\n", k, v));
    }
    resp_str.push_str("\r\n");

    stream.write_all(resp_str.as_bytes())?;
    if method != "HEAD" {
        stream.write_all(&body)?;
    }
    stream.flush()?;
    Ok(())
}

fn serve_directory(stream: &mut TcpStream, config: &Config, fs_path: &Path, effective_path: &str, raw_path: &str, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>, client_ip: &str) -> io::Result<()> {
    let sort_method = query_params.get("sort").map(|s| match s.as_str() {
        "name" => SortingMethod::Name,
        "size" => SortingMethod::Size,
        "date" => SortingMethod::Date,
        _ => config.default_sorting_method.clone(),
    }).unwrap_or_else(|| config.default_sorting_method.clone());

    let sort_order = query_params.get("order").map(|s| match s.as_str() {
        "asc" => SortingOrder::Asc,
        "desc" => SortingOrder::Desc,
        _ => config.default_sorting_order.clone(),
    }).unwrap_or_else(|| config.default_sorting_order.clone());

    let entries = match fs::read_dir(fs_path) {
        Ok(r) => r,
        Err(_) => {
            let resp = build_404(config, effective_path, raw_path, query_params, req_headers, method.to_string(), client_ip.to_string(), false);
            write_response(stream, config, resp, method, req_headers, query_params)?;
            return Ok(());
        }
    };

    struct DirEntryInfo {
        name: String,
        is_dir: bool,
        is_symlink: bool,
        symlink_target: Option<String>,
        size: u64,
        modified: SystemTime,
        modified_str: String,
    }

    let mut infos: Vec<DirEntryInfo> = Vec::new();
    for entry_res in entries {
        if let Ok(entry) = entry_res {
            let name_os = entry.file_name();
            let name = name_os.to_string_lossy().to_string();
            if !config.hidden && name.starts_with('.') { continue; }
            let path = entry.path();

            let is_symlink = fs::symlink_metadata(&path).map(|m| m.file_type().is_symlink()).unwrap_or(false);
            if config.no_symlinks && is_symlink { continue; }

            let mut symlink_target: Option<String> = None;
            if is_symlink && config.show_symlink_info {
                if let Ok(target) = fs::read_link(&path) {
                    symlink_target = Some(target.to_string_lossy().to_string());
                }
            }

            let meta = if is_symlink {
                fs::metadata(&path).or_else(|_| fs::symlink_metadata(&path)).ok()
            } else {
                fs::metadata(&path).ok()
            };

            let (size, modified) = if let Some(m) = meta {
                (if m.is_dir() { 0 } else { m.len() }, m.modified().unwrap_or(SystemTime::now()))
            } else {
                (0, SystemTime::now())
            };

            let local_dt: DateTime<Local> = modified.into();
            let modified_local_str = local_dt.format("%Y-%m-%d %H:%M:%S %:z").to_string();

            infos.push(DirEntryInfo {
                name: name.clone(),
                is_dir: path.is_dir(),
                is_symlink,
                symlink_target,
                size,
                modified,
                modified_str: modified_local_str,
            });
        }
    }

    infos.sort_by(|a,b| {
        if config.dirs_first {
            match (a.is_dir, b.is_dir) {
                (true,false) => return std::cmp::Ordering::Less,
                (false,true) => return std::cmp::Ordering::Greater,
                _ => {}
            }
        }
        let ord = match sort_method {
            SortingMethod::Name => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
            SortingMethod::Size => a.size.cmp(&b.size),
            SortingMethod::Date => a.modified.cmp(&b.modified),
        };
        match sort_order {
            SortingOrder::Asc => ord,
            SortingOrder::Desc => ord.reverse(),
        }
    });

    let is_raw = query_params.get("raw").map(|v| v=="true").unwrap_or(false);
    if is_raw {
        let mut html = String::new();
        html.push_str(r#"<!DOCTYPE html><html><body><table><thead><th class="name">Name</th><th class="size">Size</th><th class="date">Last modification</th></thead><tbody>"#);
        if effective_path != "/" {
            let parent_href = {
                let trimmed = effective_path.trim_end_matches('/');
                if let Some(pos) = trimmed.rfind('/') {
                    let parent = if pos==0 { "/" } else { &trimmed[..pos] };
                    format!("{}/", parent)
                } else {
                    "/".to_string()
                }
            };
            let parent_href_raw = format!("{}?raw=true", parent_href);
            html.push_str(&format!(r#"<tr><td colspan="3"><p><a class="root" href="{}">..</a></p></td></tr>"#, parent_href_raw));
        }

        for info in &infos {
            let href_display = if info.is_dir {
                if effective_path == "/" {
                    format!("/{}/?raw=true", info.name)
                } else {
                    format!("{}{}/?raw=true", effective_path, info.name)
                }
            } else {
                if effective_path == "/" {
                    format!("/{}", info.name)
                } else {
                    format!("{}{}", effective_path, info.name)
                }
            };

            let size_display = format_size(info.size, &config.size_display);
            html.push_str(&format!(r#"<tr class="entry-type-{}"><td><p><a class="{}" href="{}">{}{}</a></p></td><td class="size-cell">{}</td><td class="date-cell"><span>{} </span><span class="history">{}</span></td></tr>"#,
                if info.is_dir {"directory"} else {"file"},
                if info.is_dir {"directory"} else {"file"},
                href_display,
                info.name,
                if info.is_dir {"/"} else {""},
                if info.is_dir { "".to_string() } else { size_display },
                info.modified_str,
                relative_time(info.modified)
            ));
        }
        html.push_str("</tbody></table></body></html>");
        let body = html.into_bytes();
        let mut resp_headers = vec![
            ("Content-Type".to_string(),"text/html; charset=utf-8".to_string()),
            ("Content-Length".to_string(), body.len().to_string()),
            ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
        ];
        for (k,v) in &config.headers {
            if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
                resp_headers.push((k.clone(), v.clone()));
            }
        }
        let resp = HttpResponse {
            status_code: 200,
            reason: "OK".to_string(),
            headers: resp_headers,
            body,
        };
        write_response(stream, config, resp, method, req_headers, query_params)?;
        if config.verbose {
            let len = resp.headers.iter().find(|(k,_)| k.to_lowercase()=="content-length").map(|(_,v)| v.clone()).unwrap_or("0".to_string());
            println!("{} [INFO] {} \"{} {} HTTP/1.1\" 200 {} \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path, len);
        }
        return Ok(());
    }

    let host_display = if let Some(ref t) = config.title {
        t.clone()
    } else {
        req_headers.get("host").cloned().unwrap_or_else(|| format!("127.0.0.1:{}", config.port))
    };

    let breadcrumb_html = build_breadcrumb(&config, effective_path, &host_display);

    let sort_query_suffix = if query_params.is_empty() {
        "".to_string()
    } else {
        let mut qs = String::new();
        if let Some(s) = query_params.get("sort") {
            qs.push_str(&format!("sort={}", s));
        }
        if let Some(o) = query_params.get("order") {
            if !qs.is_empty() { qs.push('&'); }
            qs.push_str(&format!("order={}", o));
        }
        if qs.is_empty() { "".to_string() } else { format!("?{}", qs) }
    };

    let mut toolbar_download_html = String::new();
    if config.enable_tar || config.enable_tar_gz || config.enable_zip {
        toolbar_download_html.push_str(r#"<div class="download">"#);
        if config.enable_tar_gz {
            toolbar_download_html.push_str(r#"<a href="?download=tar_gz">Download .tar.gz</a>"#);
        }
        if config.enable_tar {
            toolbar_download_html.push_str(r#"<a href="?download=tar">Download .tar</a>"#);
        }
        if config.enable_zip {
            toolbar_download_html.push_str(r#"<a href="?download=zip">Download .zip</a>"#);
        }
        toolbar_download_html.push_str("</div>");
    }

    let mut toolbar_box_group_html = String::new();
    let upload_enabled = config.upload_files.is_some();
    let mkdir_enabled = config.mkdir && upload_enabled;
    if upload_enabled || mkdir_enabled {
        toolbar_box_group_html.push_str(r#"<div class="toolbar_box_group">"#);
        if upload_enabled {
            let upload_action_path = if effective_path == "/" { "/".to_string() } else { effective_path.to_string() };
            let action_url = if let Some(ref rp) = config.route_prefix {
                format!("{}/upload?path={}", rp, upload_action_path)
            } else {
                format!("/upload?path={}", upload_action_path)
            };
            toolbar_box_group_html.push_str(&format!(r#"<div class="toolbar_box"><form id="file_submit" action="{}" method="POST" enctype="multipart/form-data"><p>Select a file to upload or drag it anywhere into the window</p><div><input id="file-input" type="file" name="file_to_upload" required="" multiple></input><button type="submit">Upload file</button></div></form></div>"#, action_url));
        }
        if mkdir_enabled {
            let upload_action_path = if effective_path == "/" { "/".to_string() } else { effective_path.to_string() };
            let action_url = if let Some(ref rp) = config.route_prefix {
                format!("{}/upload?path={}", rp, upload_action_path)
            } else {
                format!("/upload?path={}", upload_action_path)
            };
            toolbar_box_group_html.push_str(&format!(r#"<div class="toolbar_box"><form id="mkdir" action="{}" method="POST" enctype="multipart/form-data"><p>Specify a directory name to create</p><div class="toolbar_box"><input type="text" name="mkdir" required="" placeholder="Directory name"></input><button type="submit">Create directory</button></div></form></div>"#, action_url));
        }
        toolbar_box_group_html.push_str("</div>");
    } else {
        toolbar_box_group_html.push_str(r#"<div class="toolbar_box_group"></div>"#);
    }

    let mut rows_html = String::new();
    if effective_path != "/" {
        let parent_href = {
            let trimmed = effective_path.trim_end_matches('/');
            if let Some(pos) = trimmed.rfind('/') {
                let parent = if pos==0 { "/" } else { &trimmed[..pos] };
                format!("{}/", parent)
            } else {
                "/".to_string()
            }
        };
        let parent_href_with_prefix = if let Some(ref rp) = config.route_prefix {
            format!("{}{}", rp, parent_href)
        } else {
            parent_href
        };
        let parent_href_final = if sort_query_suffix.is_empty() {
            parent_href_with_prefix
        } else {
            format!("{}{}", parent_href_with_prefix, sort_query_suffix)
        };
        rows_html.push_str(&format!(r#"<tr><td colspan="3"><p><span class="root-chevron">◂</span><a class="root" href="{}">Parent directory</a></p></td></tr>"#, parent_href_final));
    }

    for info in &infos {
        let href_file = if let Some(ref ext_url) = config.file_external_url {
            if info.is_dir {
                if effective_path == "/" {
                    format!("/{}/", info.name)
                } else {
                    format!("{}{}/", effective_path, info.name)
                }
            } else {
                let internal_path = if effective_path == "/" {
                    format!("/{}", info.name)
                } else {
                    format!("{}{}", effective_path, info.name)
                };
                format!("{}{}", ext_url.trim_end_matches('/'), internal_path)
            }
        } else {
            if info.is_dir {
                if effective_path == "/" { format!("/{}/", info.name) } else { format!("{}{}/", effective_path, info.name) }
            } else {
                if effective_path == "/" { format!("/{}", info.name) } else { format!("{}{}", effective_path, info.name) }
            }
        };

        let href_final = if info.is_dir {
            let base = if let Some(ref rp) = config.route_prefix {
                if config.file_external_url.is_some() {
                    // for dir, even with external, dir link should be internal with prefix
                    format!("{}{}", rp, href_file)
                } else {
                    format!("{}{}", rp, href_file)
                }
            } else {
                href_file.clone()
            };
            if sort_query_suffix.is_empty() { base } else { format!("{}{}", base, sort_query_suffix) }
        } else {
            if let Some(ref rp) = config.route_prefix {
                if config.file_external_url.is_some() {
                    href_file.clone()
                } else {
                    format!("{}{}", rp, href_file)
                }
            } else {
                href_file.clone()
            }
        };

        let size_display = if info.is_dir {
            "".to_string()
        } else {
            format_size(info.size, &config.size_display)
        };

        let (link_class, link_content) = if info.is_symlink && config.show_symlink_info {
            if let Some(ref target) = info.symlink_target {
                (format!("symlink"), format!(r#"{}<span class="symlink-symbol"></span><a class="file">{}</a>"#, info.name, target))
            } else {
                (format!("symlink"), format!(r#"{}"#, info.name))
            }
        } else if info.is_dir {
            (format!("directory"), format!("{}", info.name))
        } else {
            (format!("file"), format!("{}", info.name))
        };

        let mobile_size_html = if info.is_dir {
            "".to_string()
        } else {
            format!(r#"<span class="mobile-info size"><span class=""><span class="chevron">▾</span><a href="?sort=size&amp;order=asc" title="Sort by size in ascending order">{} </a></span></span>"#, size_display)
        };

        let actions_cell = if config.rm_files.is_some() {
            let rm_path = if effective_path == "/" { format!("/{}", info.name) } else { format!("{}{}", effective_path, info.name) };
            let rm_action = if let Some(ref rp) = config.route_prefix {
                format!("{}/rm?path={}", rp, rm_path)
            } else {
                format!("/rm?path={}", rm_path)
            };
            format!(r#"<td class="actions-cell"><form class="rm_form" action="{}" method="POST"><button type="submit" title="Delete">✗</button></form></td>"#, rm_action)
        } else {
            "".to_string()
        };

        if info.is_dir {
            rows_html.push_str(&format!(r#"<tr class="entry-type-directory"><td><p><a class="{class}" href="{href}">{name}/</a></p></td><td class="size-cell"></td><td class="date-cell"><span>{date} </span><span class="history">{history}</span></td>{actions}</tr>"#,
                class = link_class,
                href = href_final,
                name = if link_class=="symlink" { link_content } else { info.name.clone() },
                date = info.modified_str,
                history = relative_time(info.modified),
                actions = actions_cell
            ));
        } else {
            if config.show_symlink_info && info.is_symlink {
                rows_html.push_str(&format!(r#"<tr class="entry-type-file"><td><p><a class="{class}" href="{href}">{content}</a>{mobile_size}<span class="mobile-info history"><span class=""><span class="chevron">▾</span><a href="?sort=date&amp;order=asc" title="Sort by date in ascending order">{history}</a></span></span></p></td><td class="size-cell">{size}</td><td class="date-cell"><span>{date} </span><span class="history">{history}</span></td>{actions}</tr>"#,
                    class = link_class,
                    href = href_final,
                    content = link_content,
                    mobile_size = mobile_size_html,
                    size = size_display,
                    date = info.modified_str,
                    history = relative_time(info.modified),
                    actions = actions_cell
                ));
            } else {
                rows_html.push_str(&format!(r#"<tr class="entry-type-file"><td><p><a class="{class}" href="{href}">{name}</a>{mobile_size}<span class="mobile-info history"><span class=""><span class="chevron">▾</span><a href="?sort=date&amp;order=asc" title="Sort by date in ascending order">{history}</a></span></span></p></td><td class="size-cell">{size}</td><td class="date-cell"><span>{date} </span><span class="history">{history}</span></td>{actions}</tr>"#,
                    class = link_class,
                    href = href_final,
                    name = info.name,
                    mobile_size = mobile_size_html,
                    size = size_display,
                    date = info.modified_str,
                    history = relative_time(info.modified),
                    actions = actions_cell
                ));
            }
        }
    }

    let wget_footer = if config.show_wget_footer {
        let host = req_headers.get("host").cloned().unwrap_or_else(|| format!("127.0.0.1:{}", config.port));
        let current_url_path = if effective_path == "/" { "/" } else { effective_path };
        let url_for_wget = format!("http://{}{}{}?raw=true", host, config.route_prefix.clone().unwrap_or_default(), current_url_path);
        let download_dir = host_display.clone();
        format!(r#"<div class="downloadDirectory"><p>Download folder:</p><a class="cmd" title="Click to copy!" style="cursor: pointer;" onclick="navigator.clipboard.writeText(&quot;wget -rcnp -R 'index.html*' -nH -P '{dir}' '{url}'&quot;)">wget -rcnp -R 'index.html*' -nH -P '{dir}' '{url}'</a></div>"#, dir=download_dir, url=url_for_wget)
    } else {
        "".to_string()
    };

    let version_footer = if config.hide_version_footer {
        "".to_string()
    } else {
        format!(r#"<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/{}</div>"#, VERSION)
    };

    let nav_html = if config.hide_theme_selector {
        if config.qrcode {
            let current_url = format!("http://{}{}{}", req_headers.get("host").cloned().unwrap_or_else(|| format!("127.0.0.1:{}", config.port)), config.route_prefix.clone().unwrap_or_default(), effective_path);
            let qr_svg = generate_qr_svg(&current_url);
            format!(r#"<nav><div><p>QR code</p><div class="qrcode" id="qrcode" title="{}">{}</div></div></nav>"#, current_url, qr_svg)
        } else {
            r#"<nav></nav>"#.to_string()
        }
    } else {
        let qr_part = if config.qrcode {
            let current_url = format!("http://{}{}{}", req_headers.get("host").cloned().unwrap_or_else(|| format!("127.0.0.1:{}", config.port)), config.route_prefix.clone().unwrap_or_default(), effective_path);
            let qr_svg = generate_qr_svg(&current_url);
            format!(r#"<div><p>QR code</p><div class="qrcode" id="qrcode" title="{}">{}</div></div>"#, current_url, qr_svg)
        } else {
            "".to_string()
        };
        format!(r#"<nav>{}<div><p>Change theme...</p><ul class="theme"><li data-theme="default"><a href="javascript:updateColorScheme(&quot;default&quot;)" title="Switch to Default (light/dark) theme">Default (light/dark)</a></li><li data-theme="squirrel"><a href="javascript:updateColorScheme(&quot;squirrel&quot;)" title="Switch to Squirrel (light) theme">Squirrel (light)</a></li><li data-theme="archlinux"><a href="javascript:updateColorScheme(&quot;archlinux&quot;)" title="Switch to Arch Linux (dark) theme">Arch Linux (dark)</a></li><li data-theme="zenburn"><a href="javascript:updateColorScheme(&quot;zenburn&quot;)" title="Switch to Zenburn (dark) theme">Zenburn (dark)</a></li><li data-theme="monokai"><a href="javascript:updateColorScheme(&quot;monokai&quot;)" title="Switch to Monokai (dark) theme">Monokai (dark)</a></li></ul></div></nav>"#, qr_part)
    };

    let readme_html = if config.readme {
        let readme_path = fs_path.join("README.md");
        if readme_path.is_file() {
            if let Ok(content) = fs::read_to_string(&readme_path) {
                let rendered = render_markdown_simple(&content);
                format!(r#"<div id="readme"><h3 id="readme-filename">README.md</h3><div id="readme-contents">{}</div></div>"#, rendered)
            } else {
                "".to_string()
            }
        } else {
            "".to_string()
        }
    } else {
        "".to_string()
    };

    let toolbar_html = if toolbar_download_html.is_empty() && toolbar_box_group_html.contains("toolbar_box_group\"></div>") {
        format!(r#"<div class="toolbar"><div class="toolbar_box_group"></div></div>"#)
    } else {
        if toolbar_download_html.is_empty() {
            format!(r#"<div class="toolbar">{}</div>"#, toolbar_box_group_html)
        } else {
            format!(r#"<div class="toolbar">{}{}</div>"#, toolbar_download_html, toolbar_box_group_html)
        }
    };

    let page_title = if let Some(ref t) = config.title {
        if effective_path == "/" {
            t.clone()
        } else {
            format!("{}{}", t, effective_path.trim_end_matches('/'))
        }
    } else {
        let host = req_headers.get("host").cloned().unwrap_or_else(|| format!("127.0.0.1:{}", config.port));
        if effective_path == "/" {
            host
        } else {
            format!("{}{}", host, effective_path.trim_end_matches('/'))
        }
    };

    let color_scheme_script = r#"<script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {
                        if (name && name != "default") {
                            localStorage.setItem('theme', name);
                            document.body.setAttribute("data-theme", name)
                        } else {
                            localStorage.removeItem('theme');
                            document.body.removeAttribute("data-theme")
                        }
                    }

                    // read theme from local storage and apply it to body
                    function loadColorScheme() {
                        var name = localStorage.getItem('theme');
                        updateColorScheme(name);
                    }

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script>"#;

    let dir_size_script = r#"<script>const API_ROUTE = '/__miniserve_internal/api';
                    let dirSizeCache = {};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {
                        return fetch(API_ROUTE, {
                            headers: {
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            },
                            method: 'POST',
                            body: JSON.stringify({
                                DirSize: dir
                            })
                        }).then(resp => resp.ok ? resp.text() : "~")
                    }

                    function updateSizeCells() {
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {
                                cell.dataset.size = dirSizeCache[target];
                            } else {
                                fetchDirSize(target).then(dir_size => {
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                })
                                .catch(error => console.error("Error fetching dir size:", error));
                            }
                        })
                    }
                    setInterval(updateSizeCells, 1000);
                </script>"#;

    let upload_script = if upload_enabled {
        format!(r#"<script>const CONCURRENCY = {};
                    window.onload = function() {{
                        // Constants
                        const UPLOADING = 'uploading', PENDING = 'pending', COMPLETE = 'complete', CANCELLED = 'cancelled', FAILED = 'failed'
                        const UPLOAD_ITEM_ORDER = {{ UPLOADING: 0, PENDING: 1, COMPLETE: 2, CANCELLED: 3, FAILED: 4 }}
                        let CANCEL_UPLOAD = false;

                        // File Upload dom elements. Used for interacting with the
                        // upload container.
                        const form = document.querySelector('#file_submit');
                        const uploadArea = document.querySelector('#upload_area');
                        const uploadTitle = document.querySelector('#upload_title');
                        const uploadActionText = document.querySelector('#upload_action_text');
                        const uploadCancelButton = document.querySelector('#upload_cancel');
                        const uploadList = document.querySelector('#upload_file_list');
                        const fileUploadItemTemplate = document.querySelector('#upload_file_item');
                        const uploadWidgetToggle = document.querySelector('#upload-toggle');

                        const dropContainer = document.querySelector('#drop-container');
                        const dragForm = document.querySelector('.drag-form');
                        const fileInput = document.querySelector('#file-input');
                        const collection = [];

                        dropContainer.ondragover = function(e) {{
                            e.preventDefault();
                        }}

                        dropContainer.ondragenter = function(e) {{
                            e.preventDefault();
                            if (collection.length === 0) {{
                                dragForm.style.display = 'initial';
                            }}
                            collection.push(e.target);
                        }};

                        dropContainer.ondragleave = function(e) {{
                            e.preventDefault();
                            collection.splice(collection.indexOf(e.target), 1);
                            if (collection.length === 0) {{
                                dragForm.style.display = 'none';
                            }}
                        }};

                        dropContainer.ondrop = function(e) {{
                            e.preventDefault();
                            fileInput.files = e.dataTransfer.files;
                            form.requestSubmit();
                            dragForm.style.display = 'none';
                        }};

                        // Event listener for toggling the upload widget display on mobile.
                        uploadWidgetToggle.addEventListener('click', function (e) {{
                            e.preventDefault();
                            if (uploadArea.style.height === "100vh") {{
                                uploadArea.style = ""
                                document.body.style = ""
                                uploadWidgetToggle.style = ""
                            }} else {{
                                uploadArea.style.height = "100vh"
                                document.body.style = "overflow: hidden"
                                uploadWidgetToggle.style = "transform: rotate(180deg)"
                            }}
                        }})

                        // Cancel all active and pending uploads
                        uploadCancelButton.addEventListener('click', function (e) {{
                            e.preventDefault();
                            CANCEL_UPLOAD = true;
                        }})

                        form.addEventListener('submit', function (e) {{
                            e.preventDefault()
                            uploadFiles()
                        }})

                        function updateUploadTextAndList() {{
                            const uploading = uploadList.querySelectorAll('[data-state="uploading"]').length;
                            const pending = uploadList.querySelectorAll('[data-state="pending"]').length;
                            const complete = uploadList.querySelectorAll('[data-state="complete"]').length;
                            const cancelled = uploadList.querySelectorAll('[data-state="cancelled"]').length;
                            const failed = uploadList.querySelectorAll('[data-state="failed"]').length;
                            const total = uploading + pending + complete + cancelled + failed;

                            if (total === 0) {{
                                uploadTitle.textContent = "No uploads";
                                uploadActionText.textContent = "No uploads";
                                return;
                            }}

                            uploadTitle.textContent = `${{complete}} / ${{total}} uploaded`;
                            if (uploading > 0) {{
                                uploadActionText.textContent = `Uploading ${{uploading}} files...`;
                            }} else if (pending > 0) {{
                                uploadActionText.textContent = `${{pending}} files pending...`;
                            }} else if (complete === total) {{
                                uploadActionText.textContent = "All uploads complete!";
                                setTimeout(() => {{
                                    location.reload();
                                }}, 1000);
                            }} else if (failed > 0) {{
                                uploadActionText.textContent = `${{failed}} uploads failed`;
                            }} else if (cancelled > 0) {{
                                uploadActionText.textContent = `${{cancelled}} uploads cancelled`;
                            }}
                        }}

                        async function get256FileHash(file) {{
                            if (!window.crypto || !window.crypto.subtle) {{
                                return null;
                            }}
                            const buffer = await file.arrayBuffer();
                            const hash = await crypto.subtle.digest("SHA-256", buffer);
                            const hashArray = Array.from(new Uint8Array(hash));
                            const hashHex = hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
                            return hashHex;
                        }}

                        function uploadFiles() {{
                            const files = fileInput.files;
                            if (files.length === 0) {{
                                return;
                            }}

                            uploadArea.classList.add("active");
                            uploadTitle.textContent = `0 / ${{files.length}} uploaded`;
                            uploadActionText.textContent = "Starting upload...";
                            CANCEL_UPLOAD = false;

                            const uploadPromises = [];
                            for (let i = 0; i < files.length; i++) {{
                                const file = files[i];
                                const uploadFn = uploadFile(file);
                                if (CONCURRENCY === 0) {{
                                    uploadPromises.push(uploadFn());
                                }} else {{
                                    uploadPromises.push(uploadFn);
                                }}
                            }}

                            if (CONCURRENCY === 0) {{
                                Promise.all(uploadPromises).then(() => {{
                                    updateUploadTextAndList();
                                }});
                            }} else {{
                                let index = 0;
                                function runNext() {{
                                    if (index >= uploadPromises.length) {{ return; }}
                                    const fn = uploadPromises[index++];
                                    fn().then(() => {{
                                        updateUploadTextAndList();
                                        runNext();
                                    }});
                                }}
                                for (let i = 0; i < Math.min(CONCURRENCY, uploadPromises.length); i++) {{
                                    runNext();
                                }}
                            }}
                        }}

                        function uploadFile(file) {{
                            const fileUploadItem = fileUploadItemTemplate.content.cloneNode(true)
                            const itemContainer = fileUploadItem.querySelector(".upload_file_item")
                            const itemText = fileUploadItem.querySelector(".upload_file_text")
                            const size = fileUploadItem.querySelector(".file_size")
                            const name = fileUploadItem.querySelector(".file_name")
                            const percentText = fileUploadItem.querySelector(".file_upload_percent")
                            const bar = fileUploadItem.querySelector(".file_progress_bar")
                            const cancel = fileUploadItem.querySelector(".file_cancel_upload")

                            name.textContent = file.name;
                            size.textContent = formatFileSize(file.size);
                            percentText.textContent = "0%"

                            uploadList.append(fileUploadItem)

                            let preCancel = false;
                            function preCancelUpload() {{
                                preCancel = true;
                                itemText.classList.add(CANCELLED);
                                bar.classList.add(CANCELLED);
                                itemContainer.dataset.state = CANCELLED;
                                itemContainer.style.background = 'var(--upload_modal_file_upload_complete_background)';
                                cancel.disabled = true;
                                cancel.removeEventListener("click", preCancelUpload);
                                uploadCancelButton.removeEventListener("click", preCancelUpload);
                                updateUploadTextAndList();
                            }}

                            uploadCancelButton.addEventListener("click", preCancelUpload)
                            cancel.addEventListener("click", preCancelUpload)

                            return () => {{
                                if (preCancel) {{
                                    return Promise.resolve()
                                }}

                                return new Promise(async (resolve, reject) => {{
                                    const fileHash = await get256FileHash(file);
                                    const xhr = new XMLHttpRequest();
                                    const formData = new FormData();
                                    formData.append('file', file);

                                    function onReadyStateChange(e) {{
                                        if (e.target.readyState == 4) {{
                                            if (e.target.status == 200) {{
                                                completeSuccess()
                                            }} else {{
                                                failedUpload(e.target.status)
                                            }}
                                        }}
                                    }}

                                    function onError(e) {{
                                        failedUpload()
                                    }}

                                    function onAbort(e) {{
                                        cancelUpload()
                                    }}

                                    function onProgress (e) {{
                                        update(Math.round((e.loaded / e.total) * 100));
                                    }}

                                    function update(uploadPercent) {{
                                        let wholeNumber = Math.floor(uploadPercent)
                                        percentText.textContent = `${{wholeNumber}}%`
                                        bar.style.width = `${{wholeNumber}}%`
                                    }}

                                    function completeSuccess() {{
                                        cancel.textContent = '✔';
                                        cancel.classList.add(COMPLETE);
                                        bar.classList.add(COMPLETE);
                                        cleanUp(COMPLETE)
                                    }}

                                    function failedUpload(statusCode) {{
                                        cancel.textContent = `${{statusCode}} ⚠`;
                                        itemText.classList.add(FAILED);
                                        bar.classList.add(FAILED);
                                        cleanUp(FAILED);
                                    }}

                                    function cancelUpload() {{
                                        xhr.abort()
                                        itemText.classList.add(CANCELLED);
                                        bar.classList.add(CANCELLED);
                                        cleanUp(CANCELLED);
                                    }}

                                    function cleanUp(state) {{
                                        itemContainer.dataset.state = state;
                                        itemContainer.style.background = 'var(--upload_modal_file_upload_complete_background)';
                                        cancel.disabled = true;
                                        cancel.removeEventListener("click", cancelUpload)
                                        uploadCancelButton.removeEventListener("click", cancelUpload)
                                        xhr.removeEventListener('readystatechange', onReadyStateChange);
                                        xhr.removeEventListener("error", onError);
                                        xhr.removeEventListener("abort", onAbort);
                                        xhr.upload.removeEventListener('progress', onProgress);
                                        resolve()
                                    }}

                                    uploadCancelButton.addEventListener("click", cancelUpload)
                                    cancel.addEventListener("click", cancelUpload)

                                    if (CANCEL_UPLOAD) {{
                                        cancelUpload()
                                    }} else {{
                                        itemContainer.dataset.state = UPLOADING
                                        xhr.addEventListener('readystatechange', onReadyStateChange);
                                        xhr.addEventListener("error", onError);
                                        xhr.addEventListener("abort", onAbort);
                                        xhr.upload.addEventListener('progress', onProgress);
                                        xhr.open('post', form.getAttribute("action"), true);
                                        if (fileHash) {{
                                            xhr.setRequestHeader('X-File-Hash', fileHash);
                                            xhr.setRequestHeader('X-File-Hash-Function', 'SHA256');
                                        }}
                                        xhr.send(formData);
                                    }}
                                }})
                            }}
                        }}

                        function formatFileSize(bytes) {{
                            if (bytes === 0) return '0 B';
                            const k = 1024;
                            const sizes = ['B','KiB','MiB','GiB','TiB'];
                            const i = Math.floor(Math.log(bytes) / Math.log(k));
                            return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
                        }}
                    }}
                    </script>"#, config.web_upload_concurrency)
    } else {
        "".to_string()
    };

    let has_explicit_sort = query_params.contains_key("sort");

    let name_is_active = has_explicit_sort && sort_method == SortingMethod::Name;
    let size_is_active = has_explicit_sort && sort_method == SortingMethod::Size;
    let date_is_active = has_explicit_sort && sort_method == SortingMethod::Date;

    let name_order_link = if name_is_active {
        match sort_order { SortingOrder::Asc => "desc", SortingOrder::Desc => "asc" }
    } else {
        "asc"
    };
    let size_order_link = if size_is_active {
        match sort_order { SortingOrder::Asc => "desc", SortingOrder::Desc => "asc" }
    } else {
        "asc"
    };
    let date_order_link = if date_is_active {
        match sort_order { SortingOrder::Asc => "desc", SortingOrder::Desc => "asc" }
    } else {
        "asc"
    };

    let name_chevron_display = if name_is_active {
        match sort_order { SortingOrder::Asc => "▴", SortingOrder::Desc => "▾" }
    } else {
        "▾"
    };
    let size_chevron_display = if size_is_active {
        match sort_order { SortingOrder::Asc => "▴", SortingOrder::Desc => "▾" }
    } else {
        "▾"
    };
    let date_chevron_display = if date_is_active {
        match sort_order { SortingOrder::Asc => "▴", SortingOrder::Desc => "▾" }
    } else {
        "▾"
    };

    let table_header = format!(r#"<table><thead><th class="name"><span class="{name_active}"><span class="chevron">{name_chev}</span><a href="?sort=name&amp;order={name_order}" title="Sort by name in {name_title} order">Name</a></span></th><th class="size"><span class="{size_active}"><span class="chevron">{size_chev}</span><a href="?sort=size&amp;order={size_order}" title="Sort by size in {size_title} order">Size</a></span></th><th class="date"><span class="{date_active}"><span class="chevron">{date_chev}</span><a href="?sort=date&amp;order={date_order}" title="Sort by date in {date_title} order">Last modification</a></span></th>{actions_header}</thead><tbody>"#,
        name_active = if name_is_active { "active" } else { "" },
        name_chev = name_chevron_display,
        name_order = name_order_link,
        name_title = if name_order_link=="asc" { "ascending" } else { "descending" },
        size_active = if size_is_active { "active" } else { "" },
        size_chev = size_chevron_display,
        size_order = size_order_link,
        size_title = if size_order_link=="asc" { "ascending" } else { "descending" },
        date_active = if date_is_active { "active" } else { "" },
        date_chev = date_chevron_display,
        date_order = date_order_link,
        date_title = if date_order_link=="asc" { "ascending" } else { "descending" },
        actions_header = if config.rm_files.is_some() { r#"<th class="actions"><span>Actions</span></th>"# } else { "" }
    );

    let prefix = config.route_prefix.clone().unwrap_or_default();

    let html = format!(r#"<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{prefix}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{prefix}/__miniserve_internal/style.css"><title>{title}</title>{color_script}{dir_script}{upload_script}</head><body id="drop-container"><div class="toolbar_box_group"></div>{nav}<div class="container"><span id="top"></span><h1 class="title" dir="ltr">{breadcrumb}</h1>{toolbar}{table_header}{rows}</tbody></table>{readme}<a class="back" href="#top">⇪</a><div class="footer">{wget}{version}</div></div><div class="upload_area" id="upload_area"><template id="upload_file_item"><li class="upload_file_item"><div class="upload_file_container"><div class="upload_file_text"><span class="file_upload_percent"></span> - <span class="file_size"></span> - <span class="file_name"></span></div><button class="file_cancel_upload">✖</button></div><div class="file_progress_bar"></div></li></template><div class="upload_container"><div class="upload_header"><h4 style="margin:0px" id="upload_title"></h4><svg id="upload-toggle" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="size-6"><path stroke-linecap="round" stroke-linejoin="round" d="m4.5 15.75 7.5-7.5 7.5 7.5"></path></svg></div><div class="upload_action"><p id="upload_action_text">Starting upload...</p><button class="upload_cancel" id="upload_cancel">CANCEL</button></div><div class="upload_files"><ul class="upload_file_list" id="upload_file_list"></ul></div></div></div></body></html>"#,
        prefix = prefix,
        title = page_title,
        color_script = color_scheme_script,
        dir_script = dir_size_script,
        upload_script = upload_script,
        nav = nav_html,
        breadcrumb = breadcrumb_html,
        toolbar = toolbar_html,
        table_header = table_header,
        rows = rows_html,
        readme = readme_html,
        wget = wget_footer,
        version = version_footer,
    );

    let body = html.into_bytes();
    let mut resp_headers = vec![
        ("Content-Type".to_string(), "text/html; charset=utf-8".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }
    let resp = HttpResponse {
        status_code: 200,
        reason: "OK".to_string(),
        headers: resp_headers,
        body,
    };
    write_response(stream, config, resp, method, req_headers, query_params)?;
    if config.verbose {
        println!("{} [INFO] {} \"{} {} HTTP/1.1\" 200 {} \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path, body.len());
    }
    Ok(())
}

fn build_breadcrumb(config: &Config, effective_path: &str, host_display: &str) -> String {
    let prefix = config.route_prefix.clone().unwrap_or_default();
    let trimmed = effective_path.trim_matches('/');
    if trimmed.is_empty() {
        return format!(r#"<span><bdi>{}</bdi></span>/"#, host_display);
    }
    let parts: Vec<&str> = trimmed.split('/').collect();
    let mut breadcrumb = String::new();
    breadcrumb.push_str(&format!(r#"<a href="{}/"><bdi>{}</bdi></a>/"#, if prefix.is_empty() { "".to_string() } else { prefix.clone() }, host_display));
    for (i, part) in parts.iter().enumerate() {
        let is_last = i == parts.len() -1;
        let path_up_to = format!("/{}/", parts[..=i].join("/"));
        let href = if prefix.is_empty() {
            path_up_to.clone()
        } else {
            format!("{}{}", prefix, path_up_to)
        };
        if is_last {
            breadcrumb.push_str(&format!(r#"<span><bdi>{}</bdi></span>/"#, part));
        } else {
            breadcrumb.push_str(&format!(r#"<a href="{}"><bdi>{}</bdi></a>/"#, href, part));
        }
    }
    breadcrumb
}

fn relative_time(modified: SystemTime) -> String {
    let now = SystemTime::now();
    let diff = now.duration_since(modified).unwrap_or(Duration::new(0,0));
    let secs = diff.as_secs();
    if secs < 10 {
        "now".to_string()
    } else if secs < 60 {
        format!("{} seconds ago", secs)
    } else if secs < 120 {
        "a minute ago".to_string()
    } else if secs < 3600 {
        format!("{} minutes ago", secs / 60)
    } else if secs < 7200 {
        "an hour ago".to_string()
    } else if secs < 86400 {
        format!("{} hours ago", secs / 3600)
    } else if secs < 172800 {
        "a day ago".to_string()
    } else {
        format!("{} days ago", secs / 86400)
    }
}

fn render_markdown_simple(md: &str) -> String {
    let mut html = String::new();
    let mut in_paragraph = false;
    for line in md.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if in_paragraph {
                html.push_str("</p>");
                in_paragraph = false;
            }
            continue;
        }
        if trimmed.starts_with("# ") {
            if in_paragraph { html.push_str("</p>"); in_paragraph=false; }
            let content = trimmed.trim_start_matches("# ").trim();
            html.push_str(&format!("<h1>{}</h1>", escape_html(content)));
        } else if trimmed.starts_with("## ") {
            if in_paragraph { html.push_str("</p>"); in_paragraph=false; }
            let content = trimmed.trim_start_matches("## ").trim();
            html.push_str(&format!("<h2>{}</h2>", escape_html(content)));
        } else if trimmed.starts_with("### ") {
            if in_paragraph { html.push_str("</p>"); in_paragraph=false; }
            let content = trimmed.trim_start_matches("### ").trim();
            html.push_str(&format!("<h3>{}</h3>", escape_html(content)));
        } else {
            if !in_paragraph {
                html.push_str("<p>");
                in_paragraph = true;
            } else {
                html.push_str(" ");
            }
            html.push_str(&escape_html(trimmed));
        }
    }
    if in_paragraph {
        html.push_str("</p>");
    }
    if html.is_empty() {
        html.push_str(&format!("<p>{}</p>", escape_html(md)));
    }
    html
}

fn escape_html(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;")
}

fn generate_qr_svg(url: &str) -> String {
    let mut modules = vec![vec![false; 27]; 27];
    let finder_positions = [(0,0),(0,20),(20,0)];
    for (fx,fy) in finder_positions.iter() {
        for y in 0..7 {
            for x in 0..7 {
                let is_border = x==0 || x==6 || y==0 || y==6;
                let is_inner = x>=2 && x<=4 && y>=2 && y<=4;
                if is_border || is_inner {
                    modules[fy+y][fx+x] = true;
                }
            }
        }
    }

    use sha2::{Sha256, Digest};
    let mut hasher = Sha256::new();
    hasher.update(url.as_bytes());
    let hash = hasher.finalize();
    let mut hash_bits = Vec::new();
    for b in hash {
        for i in 0..8 {
            hash_bits.push((b >> i) & 1 == 1);
        }
    }
    let mut bit_idx = 0;
    for y in 0..27 {
        for x in 0..27 {
            let in_finder = (x<8 && y<8) || (x>=19 && y<8) || (x<8 && y>=19);
            if in_finder { continue; }
            if x==6 || y==6 { continue; }
            let bit = hash_bits[bit_idx % hash_bits.len()];
            bit_idx += 1;
            if bit {
                modules[y][x] = true;
            }
        }
    }

    let mut path_d = String::new();
    for y in 0..27 {
        for x in 0..27 {
            if modules[y][x] {
                path_d.push_str(&format!("M{},{}h1v1h-1", x, y));
            }
        }
    }
    format!(r#"<svg viewBox="0 0 27 27" xmlns="http://www.w3.org/2000/svg"><rect width="27px" height="27px" fill="#ffffff"/><path d="{}"/></svg>"#, path_d)
}

fn serve_tar(stream: &mut TcpStream, config: &Config, dir_path: &Path, gz: bool, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>, client_ip: &str, raw_path: &str) -> io::Result<()> {
    let mut files: Vec<PathBuf> = Vec::new();
    fn collect(dir: &Path, config: &Config, out: &mut Vec<PathBuf>) {
        if let Ok(entries) = fs::read_dir(dir) {
            for entry in entries.flatten() {
                let p = entry.path();
                let name = p.file_name().and_then(|n| n.to_str()).unwrap_or("");
                if !config.hidden && name.starts_with('.') { continue; }
                if config.no_symlinks {
                    if let Ok(meta) = fs::symlink_metadata(&p) {
                        if meta.file_type().is_symlink() { continue; }
                    }
                }
                if p.is_dir() {
                    collect(&p, config, out);
                } else if p.is_file() {
                    out.push(p);
                }
            }
        }
    }
    collect(dir_path, config, &mut files);

    let mut tar_data: Vec<u8> = Vec::new();
    {
        for file_path in &files {
            let rel_path = file_path.strip_prefix(dir_path).unwrap_or(file_path);
            let rel_str = rel_path.to_string_lossy().to_string();
            if let Ok(meta) = fs::metadata(file_path) {
                let size = meta.len();
                let mut header = [0u8; 512];
                let name_bytes = rel_str.as_bytes();
                let name_len = name_bytes.len().min(100);
                header[0..name_len].copy_from_slice(&name_bytes[..name_len]);
                let mode_str = format!("{:07o}\0", 0o644);
                header[100..108].copy_from_slice(mode_str.as_bytes());
                header[108..116].copy_from_slice(b"0000000\0");
                header[116..124].copy_from_slice(b"0000000\0");
                let size_str = format!("{:011o}\0", size);
                header[124..136].copy_from_slice(size_str.as_bytes());
                let mtime = meta.modified().unwrap_or(SystemTime::now()).duration_since(UNIX_EPOCH).unwrap_or(Duration::new(0,0)).as_secs();
                let mtime_str = format!("{:011o}\0", mtime);
                header[136..148].copy_from_slice(mtime_str.as_bytes());
                for i in 148..156 { header[i] = b' '; }
                header[156] = b'0';
                header[257..263].copy_from_slice(b"ustar\0");
                header[263..265].copy_from_slice(b"00");
                let checksum: u32 = header.iter().map(|&b| b as u32).sum();
                let checksum_str = format!("{:06o}\0 ", checksum);
                header[148..156].copy_from_slice(checksum_str.as_bytes());

                tar_data.extend_from_slice(&header);
                if let Ok(mut f) = File::open(file_path) {
                    let mut buffer = Vec::new();
                    f.read_to_end(&mut buffer).ok();
                    tar_data.extend_from_slice(&buffer);
                    let padding = (512 - (buffer.len() % 512)) % 512;
                    tar_data.extend(vec![0u8; padding]);
                }
            }
        }
        tar_data.extend(vec![0u8; 1024]);
    }

    let final_data: Vec<u8>;
    let content_type: String;
    let filename: String;
    if gz {
        let mut encoder = GzEncoder::new(Vec::new(), FlateCompression::default());
        encoder.write_all(&tar_data).ok();
        final_data = encoder.finish().unwrap_or(tar_data);
        content_type = "application/gzip".to_string();
        filename = format!("{}.tar.gz", dir_path.file_name().and_then(|n| n.to_str()).unwrap_or("archive"));
    } else {
        final_data = tar_data;
        content_type = "application/x-tar".to_string();
        filename = format!("{}.tar", dir_path.file_name().and_then(|n| n.to_str()).unwrap_or("archive"));
    }

    let mut resp_headers = vec![
        ("Content-Type".to_string(), content_type),
        ("Content-Length".to_string(), final_data.len().to_string()),
        ("Content-Disposition".to_string(), format!("attachment; filename=\"{}\"", filename)),
        ("Content-Transfer-Encoding".to_string(), "binary".to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }

    let resp = HttpResponse {
        status_code: 200,
        reason: "OK".to_string(),
        headers: resp_headers,
        body: final_data,
    };

    write_response(stream, config, resp, method, req_headers, query_params)?;
    if config.verbose {
        println!("{} [INFO] {} \"{} {} HTTP/1.1\" 200 {} \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path, 0);
    }
    Ok(())
}

fn serve_zip(stream: &mut TcpStream, config: &Config, dir_path: &Path, method: &str, req_headers: &HashMap<String,String>, query_params: &HashMap<String,String>, client_ip: &str, raw_path: &str) -> io::Result<()> {
    let mut files: Vec<PathBuf> = Vec::new();
    fn collect(dir: &Path, config: &Config, out: &mut Vec<PathBuf>) {
        if let Ok(entries) = fs::read_dir(dir) {
            for entry in entries.flatten() {
                let p = entry.path();
                let name = p.file_name().and_then(|n| n.to_str()).unwrap_or("");
                if !config.hidden && name.starts_with('.') { continue; }
                if config.no_symlinks {
                    if let Ok(meta) = fs::symlink_metadata(&p) {
                        if meta.file_type().is_symlink() { continue; }
                    }
                }
                if p.is_dir() {
                    collect(&p, config, out);
                } else if p.is_file() {
                    out.push(p);
                }
            }
        }
    }
    collect(dir_path, config, &mut files);

    let mut zip_data: Vec<u8> = Vec::new();
    let mut central_dir: Vec<u8> = Vec::new();
    let mut offset: u32 = 0;

    for file_path in &files {
        let rel_path = file_path.strip_prefix(dir_path).unwrap_or(file_path);
        let rel_str = rel_path.to_string_lossy().to_string();
        let rel_bytes = rel_str.as_bytes();

        let file_data = fs::read(file_path).unwrap_or_default();
        let crc = crc32(&file_data);
        let compressed_data = file_data.clone();

        let file_name_len = rel_bytes.len() as u16;
        let extra_len = 0u16;
        let compressed_size = compressed_data.len() as u32;
        let uncompressed_size = file_data.len() as u32;

        zip_data.extend(&0x04034b50u32.to_le_bytes());
        zip_data.extend(&20u16.to_le_bytes());
        zip_data.extend(&0u16.to_le_bytes());
        zip_data.extend(&0u16.to_le_bytes());
        zip_data.extend(&0u16.to_le_bytes());
        zip_data.extend(&0u16.to_le_bytes());
        zip_data.extend(&crc.to_le_bytes());
        zip_data.extend(&compressed_size.to_le_bytes());
        zip_data.extend(&uncompressed_size.to_le_bytes());
        zip_data.extend(&file_name_len.to_le_bytes());
        zip_data.extend(&extra_len.to_le_bytes());
        zip_data.extend(rel_bytes);
        zip_data.extend(&compressed_data);

        central_dir.extend(&0x02014b50u32.to_le_bytes());
        central_dir.extend(&20u16.to_le_bytes());
        central_dir.extend(&20u16.to_le_bytes());
        central_dir.extend(&0u16.to_le_bytes());
        central_dir.extend(&0u16.to_le_bytes());
        central_dir.extend(&0u16.to_le_bytes());
        central_dir.extend(&0u16.to_le_bytes());
        central_dir.extend(&crc.to_le_bytes());
        central_dir.extend(&compressed_size.to_le_bytes());
        central_dir.extend(&uncompressed_size.to_le_bytes());
        central_dir.extend(&file_name_len.to_le_bytes());
        central_dir.extend(&extra_len.to_le_bytes());
        central_dir.extend(&0u16.to_le_bytes());
        central_dir.extend(&0u16.to_le_bytes());
        central_dir.extend(&0u16.to_le_bytes());
        central_dir.extend(&0u32.to_le_bytes());
        central_dir.extend(&offset.to_le_bytes());
        central_dir.extend(rel_bytes);

        offset += 30 + file_name_len as u32 + extra_len as u32 + compressed_size;
    }

    let central_dir_offset = offset;
    let central_dir_size = central_dir.len() as u32;
    zip_data.extend(&central_dir);

    zip_data.extend(&0x06054b50u32.to_le_bytes());
    zip_data.extend(&0u16.to_le_bytes());
    zip_data.extend(&0u16.to_le_bytes());
    zip_data.extend(&(files.len() as u16).to_le_bytes());
    zip_data.extend(&(files.len() as u16).to_le_bytes());
    zip_data.extend(&central_dir_size.to_le_bytes());
    zip_data.extend(&central_dir_offset.to_le_bytes());
    zip_data.extend(&0u16.to_le_bytes());

    let filename = format!("{}.zip", dir_path.file_name().and_then(|n| n.to_str()).unwrap_or("archive"));

    let mut resp_headers = vec![
        ("Content-Type".to_string(), "application/zip".to_string()),
        ("Content-Length".to_string(), zip_data.len().to_string()),
        ("Content-Disposition".to_string(), format!("attachment; filename=\"{}\"", filename)),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &config.headers {
        if !resp_headers.iter().any(|(hk,_)| hk.to_lowercase() == k.to_lowercase()) {
            resp_headers.push((k.clone(), v.clone()));
        }
    }

    let resp = HttpResponse {
        status_code: 200,
        reason: "OK".to_string(),
        headers: resp_headers,
        body: zip_data,
    };

    write_response(stream, config, resp, method, req_headers, query_params)?;
    if config.verbose {
        println!("{} [INFO] {} \"{} {} HTTP/1.1\" 200 {} \"-\" \"-\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path, 0);
    }
    Ok(())
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xffffffff;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xedb88320;
            } else {
                crc >>= 1;
            }
        }
    }
    !crc
}
