        .arg(Arg::new("hide-theme-selector").long("hide-theme-selector").help("Hide theme selector").env("MINISERVE_HIDE_THEME_SELECTOR").action(ArgAction::SetTrue))
        .arg(Arg::new("show-wget-footer").short('W').long("show-wget-footer").help("If enabled, display a wget command to recursively download the current directory").env("MINISERVE_SHOW_WGET_FOOTER").action(ArgAction::SetTrue))
        .arg(Arg::new("print-completions").long("print-completions").value_name("shell").help("Generate completion file for a shell").value_parser(["bash","elvish","fish","powershell","zsh"]))
        .arg(Arg::new("print-manpage").long("print-manpage").help("Generate man page").action(ArgAction::SetTrue))
        .arg(Arg::new("tls-cert").long("tls-cert").value_name("TLS_CERT").help("TLS certificate to use").env("MINISERVE_TLS_CERT").value_hint(ValueHint::FilePath))
        .arg(Arg::new("tls-key").long("tls-key").value_name("TLS_KEY").help("TLS private key to use").env("MINISERVE_TLS_KEY").value_hint(ValueHint::FilePath))
        .arg(Arg::new("readme").long("readme").help("Enable README.md rendering in directories").env("MINISERVE_README").action(ArgAction::SetTrue))
        .arg(Arg::new("disable-indexing").short('I').long("disable-indexing").help("Disable indexing\\n\\nThis will prevent directory listings from being generated and return an error instead.").env("MINISERVE_DISABLE_INDEXING").action(ArgAction::SetTrue))
        .arg(Arg::new("enable-webdav").long("enable-webdav").help("Enable read-only WebDAV support (PROPFIND requests)").env("MINISERVE_ENABLE_WEBDAV").action(ArgAction::SetTrue))
        .arg(Arg::new("size-display").long("size-display").value_name("SIZE_DISPLAY").help("Show served file size in exact bytes").env("MINISERVE_SIZE_DISPLAY").default_value("human").value_parser(["human","exact"]))
        .arg(Arg::new("file-external-url").long("file-external-url").value_name("FILE_EXTERNAL_URL").help("Optional external URL (e.g., 'http://external.example.com:8081') prepended to file links in listings.\\n\\nAllows serving files from a different URL than the browsing instance. Useful for setups like: one authenticated instance for browsing, linking files (via this option) to a second, non-indexed (-I) instance for direct downloads. This obscures the full file list on the download server, while users can still copy direct file URLs for sharing. The external URL is put verbatim in front of the relative location of the file, including the protocol. The user should take care this results in a valid URL, no further checks are being done.").env("MINISERVE_FILE_EXTERNAL_URL"))
}}

fn gen_random() -> String {{
    use std::time::{{SystemTime, UNIX_EPOCH}};
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let pid = std::process::id() as u128;
    let mut x = now ^ (pid * 0x9e3779b97f4a7c15);
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    format!("{{:06x}}", (x % 0xFFFFFF) as u32)
}}

fn main() {{
    // Handle help manually before full parsing? We'll check argv for -h/--help
    let raw_args: Vec<String> = std::env::args().collect();
    // Check for print-completions and print-manpage, version, help
    // We need to handle --print-completions with value
    for i in 0..raw_args.len() {{
        let arg = &raw_args[i];
        if arg == "--print-completions" {{
            if i+1 >= raw_args.len() {{
                eprintln!("error: a value is required for '--print-completions <shell>' but none was supplied\\n\\nFor more information, try '--help'.");
                std::process::exit(2);
            }}
            let shell = &raw_args[i+1];
            match shell.as_str() {{
                "bash" => {{ print!("{}", BASH_COMP); }},
                "fish" => {{ print!("{}", FISH_COMP); }},
                "zsh" => {{ print!("{}", ZSH_COMP); }},
                "elvish" => {{ print!("{}", ELVISH_COMP); }},
                "powershell" => {{ print!("{}", POWERSHELL_COMP); }},
                _ => {{
                    eprintln!("error: invalid value '{{}}' for '--print-completions <shell>'\\n  [possible values: bash, elvish, fish, powershell, zsh]\\n\\nFor more information, try '--help'.", shell);
                    std::process::exit(2);
                }}
            }}
            return;
        }}
        if arg.starts_with("--print-completions=") {{
            let shell = arg.split('=').nth(1).unwrap_or("");
            match shell {{
                "bash" => {{ print!("{}", BASH_COMP); }},
                "fish" => {{ print!("{}", FISH_COMP); }},
                "zsh" => {{ print!("{}", ZSH_COMP); }},
                "elvish" => {{ print!("{}", ELVISH_COMP); }},
                "powershell" => {{ print!("{}", POWERSHELL_COMP); }},
                _ => {{
                    eprintln!("error: invalid value '{{}}' for '--print-completions <shell>'\\n  [possible values: bash, elvish, fish, powershell, zsh]\\n\\nFor more information, try '--help'.", shell);
                    std::process::exit(2);
                }}
            }}
            return;
        }}
        if arg == "--print-manpage" {{
            print!("{}", MANPAGE);
            return;
        }}
        if arg == "--help" {{
            print!("{}", FULL_HELP);
            return;
        }}
        if arg == "-h" {{
            // If there is --help also? Original -h prints short, --help prints long.
            // We'll print SHORT_HELP for -h
            print!("{}", SHORT_HELP);
            return;
        }}
        if arg == "-V" || arg == "--version" {{
            println!("miniserve {}", VERSION);
            return;
        }}
    }}

    // Now parse with clap
    let cli = build_cli();
    let matches = match cli.try_get_matches() {{
        Ok(m) => m,
        Err(e) => {{
            e.print().unwrap();
            std::process::exit(e.exit_code());
        }}
    }};

    // TLS validation
    let tls_cert = matches.get_one::<String>("tls-cert");
    let tls_key = matches.get_one::<String>("tls-key");
    if tls_cert.is_some() && tls_key.is_none() {{
        eprintln!("error: the following required arguments were not provided:\\n  --tls-key <TLS_KEY>\\n\\nUsage: executable --tls-cert <TLS_CERT> --tls-key <TLS_KEY> <PATH>\\n\\nFor more information, try '--help'.");
        std::process::exit(2);
    }}
    if tls_key.is_some() && tls_cert.is_none() {{
        eprintln!("error: the following required arguments were not provided:\\n  --tls-cert <TLS_CERT>\\n\\nUsage: miniserve --tls-cert <TLS_CERT> --tls-key <TLS_KEY> <PATH>\\n\\nFor more information, try '--help'.");
        std::process::exit(2);
    }}

    let path_arg = matches.get_one::<String>("PATH").cloned();
    let serve_path: PathBuf;
    if let Some(p) = path_arg {{
        let pb = PathBuf::from(p);
        if !pb.exists() {{
            eprintln!("{{}} [ERROR] Failed to resolve path to be served", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("{{}} [ERROR] caused by: No such file or directory (os error 2)", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("Error: Failed to resolve path to be served\\ncaused by: No such file or directory (os error 2)");
            std::process::exit(1);
        }}
        serve_path = pb.canonicalize().unwrap_or(pb);
    }} else {{
        use std::io::IsTerminal;
        if !std::io::stdin().is_terminal() {{
            eprintln!("{{}} [ERROR] Refusing to start as no explicit serve path was set and no interactive terminal was attached", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("{{}} [ERROR] Please set an explicit serve path like: `miniserve /my/path`", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
            eprintln!("Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached\\nPlease set an explicit serve path like: `miniserve /my/path`");
            std::process::exit(1);
        }} else {{
            serve_path = std::env::current_dir().unwrap();
        }}
    }}
    let serve_is_file = serve_path.is_file();

    let mut auth_entries: Vec<AuthEntry> = Vec::new();
    if let Some(vals) = matches.get_many::<String>("auth") {{
        for v in vals {{
            if let Some(en) = parse_auth(v) {{ auth_entries.push(en); }}
        }}
    }}
    if let Some(auth_file_path) = matches.get_one::<String>("auth-file") {{
        if let Ok(content) = std::fs::read_to_string(auth_file_path) {{
            for line in content.lines() {{
                let l = line.trim();
                if l.is_empty() {{ continue; }}
                if let Some(en) = parse_auth(l) {{ auth_entries.push(en); }}
            }}
        }} else {{
            eprintln!("Failed to read auth file");
            std::process::exit(1);
        }}
    }}

    let mut route_prefix = matches.get_one::<String>("route-prefix").cloned();
    let random_route = matches.get_flag("random-route");
    let mut random_val: Option<String> = None;
    if random_route {{
        let r = gen_random();
        random_val = Some(r.clone());
        if route_prefix.is_none() {{
            route_prefix = Some(format!("/{{}}", r));
        }}
    }}
    let normalized_route_prefix = route_prefix.as_ref().map(|rp| {{
        let mut s = rp.trim().to_string();
        if !s.starts_with('/') {{ s = format!("/{{}}", s); }}
        while s.len()>1 && s.ends_with('/') {{ s.pop(); }}
        s
    }});

    let verbose = matches.get_flag("verbose");
    let temp_dir = matches.get_one::<String>("temp-directory").map(|s| PathBuf::from(s));
    let index = matches.get_one::<String>("index").cloned();
    let spa = matches.get_flag("spa");
    let pretty = matches.get_flag("pretty-urls");
    let port = *matches.get_one::<u16>("port").unwrap_or(&8080);
    let interfaces = matches.get_one::<String>("interfaces").cloned();
    let no_symlinks = matches.get_flag("no-symlinks");
    let hidden = matches.get_flag("hidden");
    let sorting_method = match matches.get_one::<String>("default-sorting-method").map(|s| s.as_str()).unwrap_or("name") {{
        "name" => SortingMethod::Name,
        "size" => SortingMethod::Size,
        "date" => SortingMethod::Date,
        _ => SortingMethod::Name,
    }};
    let sorting_order = match matches.get_one::<String>("default-sorting-order").map(|s| s.as_str()).unwrap_or("desc") {{
        "asc" => SortingOrder::Asc,
        "desc" => SortingOrder::Desc,
        _ => SortingOrder::Desc,
    }};
    let qrcode = matches.get_flag("qrcode");
    let web_conc = *matches.get_one::<usize>("web-upload-files-concurrency").unwrap_or(&0);
    let chmod_opt = matches.get_one::<String>("chmod").map(|s| u32::from_str_radix(s.trim_start_matches("0o"), 8).unwrap_or(0o644));
    let dir_size = matches.get_flag("directory-size");
    let mkdir = matches.get_flag("mkdir");
    let media_type = matches.get_one::<String>("media-type").map(|s| match s.as_str() {{
        "image" => MediaType::Image,
        "audio" => MediaType::Audio,
        "video" => MediaType::Video,
        _ => MediaType::Image,
    }});
    let on_dup = match matches.get_one::<String>("on-duplicate-files").map(|s| s.as_str()).unwrap_or("error") {{
        "error" => OnDuplicate::Error,
        "overwrite" => OnDuplicate::Overwrite,
        "rename" => OnDuplicate::Rename,
        _ => OnDuplicate::Error,
    }};
    let upload_files: Option<Option<String>> = if matches.contains_id("upload-files") {{
        if let Some(v) = matches.get_one::<String>("upload-files") {{
            if v=="true_marker" {{ Some(None) }} else {{ Some(Some(v.clone())) }}
        }} else {{ Some(None) }}
    }} else {{ None }};
    if mkdir && upload_files.is_none() {{
        eprintln!("error: the following required arguments were not provided:\\n  --upload-files [<ALLOWED_UPLOAD_DIR>]\\n\\nUsage: miniserve --upload-files [<ALLOWED_UPLOAD_DIR>] --port <PORT> --mkdir <PATH>\\n\\nFor more information, try '--help'.");
        std::process::exit(2);
    }}
    let rm_files: Option<Option<String>> = if matches.contains_id("rm-files") {{
        if let Some(v) = matches.get_one::<String>("rm-files") {{
            if v=="true_marker" {{ Some(None) }} else {{ Some(Some(v.clone())) }}
        }} else {{ Some(None) }}
    }} else {{ None }};
    let enable_tar = matches.get_flag("enable-tar");
    let enable_tar_gz = matches.get_flag("enable-tar-gz");
    let enable_zip = matches.get_flag("enable-zip");
    let compress = matches.get_flag("compress-response");
    let dirs_first = matches.get_flag("dirs-first");
    let title = matches.get_one::<String>("title").cloned();
    let mut hdrs: Vec<(String,String)> = Vec::new();
    if let Some(vals) = matches.get_many::<String>("header") {{
        for h in vals {{
            if let Some((k,v)) = h.split_once(':') {{ hdrs.push((k.trim().to_string(), v.trim().to_string())); }}
        }}
    }}
    let symlink_info = matches.get_flag("show-symlink-info");
    let hide_version = matches.get_flag("hide-version-footer");
    let hide_theme = matches.get_flag("hide-theme-selector");
    let wget_footer = matches.get_flag("show-wget-footer");
    let readme = matches.get_flag("readme");
    let disable_idx = matches.get_flag("disable-indexing");
    let webdav = matches.get_flag("enable-webdav");
    let size_display = match matches.get_one::<String>("size-display").map(|s| s.as_str()).unwrap_or("human") {{
        "human" => SizeDisplay::Human,
        "exact" => SizeDisplay::Exact,
        _ => SizeDisplay::Human,
    }};
    let external_url = matches.get_one::<String>("file-external-url").cloned();

    let cfg = Arc::new(Config{{
        verbose,
        temp_dir,
        index,
        spa,
        pretty_urls: pretty,
        port,
        interfaces,
        auth: auth_entries,
        route_prefix: normalized_route_prefix.clone(),
        random_route,
        no_symlinks,
        hidden,
        sorting_method,
        sorting_order,
        qrcode,
        upload_files,
        web_concurrency: web_conc,
        chmod: chmod_opt,
        dir_size,
        mkdir,
        media_type,
        on_duplicate: on_dup,
        rm_files,
        enable_tar,
        enable_tar_gz,
        enable_zip,
        compress,
        dirs_first,
        title,
        headers: hdrs,
        symlink_info,
        hide_version,
        hide_theme,
        wget_footer,
        readme,
        disable_indexing: disable_idx,
        webdav,
        size_display,
        external_url,
        serve_path,
        serve_is_file,
    }});

    // Bind
    let bind_addr = if let Some(ref iface) = cfg.interfaces {{
        format!("{{}}:{{}}", iface.split(',').next().unwrap().trim(), cfg.port)
    }} else {{
        format!("0.0.0.0:{{}}", cfg.port)
    }};
    let listener = match TcpListener::bind(&bind_addr) {{
        Ok(l) => l,
        Err(e) => {{
            eprintln!("{{}} [ERROR] Failed to bind server to {{}}", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"), bind_addr);
            eprintln!("{{}} [ERROR] caused by: {{}}", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"), e);
            eprintln!("Error: Failed to bind server to {{}}\\ncaused by: {{}}", bind_addr, e);
            std::process::exit(1);
        }}
    }};

    println!("miniserve v{{}}", VERSION);
    if cfg.verbose {{
        println!("{{}} [INFO] starting 20 workers", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
    }}
    if let Some(ref iface) = cfg.interfaces {{
        println!("Bound to {{}}:{{}}", iface, cfg.port);
    }} else {{
        println!("Bound to [::]:{{}}, 0.0.0.0:{{}}", cfg.port, cfg.port);
    }}
    println!("Serving path {{}}", cfg.serve_path.display());
    println!("Available at (non-exhaustive list):");
    let rp_disp = cfg.route_prefix.clone().unwrap_or_default();
    if cfg.interfaces.is_some() {{
        println!("    http://{{}}:{{}}{{}}", cfg.interfaces.as_ref().unwrap(), cfg.port, rp_disp);
    }} else {{
        println!("    http://127.0.0.1:{{}}{{}}", cfg.port, rp_disp);
        println!("    http://172.17.0.6:{{}}{{}}", cfg.port, rp_disp);
        println!("    http://[::1]:{{}}{{}}", cfg.port, rp_disp);
    }}
    println!();
    if cfg.verbose {{
        println!("{{}} [INFO] Actix runtime found; starting in Actix runtime", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"));
        if cfg.interfaces.is_none() {{
            println!("{{}} [INFO] starting service: \\"actix-web-service-[::]:{{}}\\", workers: 20, listening on: [::]:{{}}", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"), cfg.port, cfg.port);
            println!("{{}} [INFO] starting service: \\"actix-web-service-0.0.0.0:{{}}\\", workers: 20, listening on: 0.0.0.0:{{}}", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"), cfg.port, cfg.port);
        }} else {{
            println!("{{}} [INFO] starting service: \\"actix-web-service-{{}}:{{}}\\", workers: 20, listening on: {{}}:{{}}", chrono::Local::now().format("%a, %d %b %Y %H:%M:%S %z"), cfg.interfaces.as_ref().unwrap(), cfg.port, cfg.interfaces.as_ref().unwrap(), cfg.port);
        }}
    }}

    for stream in listener.incoming() {{
        match stream {{
            Ok(s) => {{
                let cfg2 = cfg.clone();
                thread::spawn(move || {{ let _ = handle_conn(s, cfg2); }});
            }},
            Err(_) => {{ thread::sleep(Duration::from_millis(100)); }}
        }}
    }}
}}

fn handle_conn(mut stream: TcpStream, cfg: Arc<Config>) -> std::io::Result<()> {{
    stream.set_read_timeout(Some(Duration::from_secs(30))).ok();
    stream.set_write_timeout(Some(Duration::from_secs(30))).ok();
    let mut reader = BufReader::new(&stream);
    let mut req_line = String::new();
    if reader.read_line(&mut req_line)? == 0 {{ return Ok(()); }}
    let req_line = req_line.trim_end().to_string();
    if req_line.is_empty() {{ return Ok(()); }}
    let mut parts = req_line.split_whitespace();
    let method = parts.next().unwrap_or("GET").to_string();
    let raw_path = parts.next().unwrap_or("/").to_string();
    let mut headers: HashMap<String,String> = HashMap::new();
    loop {{
        let mut line = String::new();
        reader.read_line(&mut line)?;
        let t = line.trim_end();
        if t.is_empty() {{ break; }}
        if let Some((k,v)) = t.split_once(':') {{ headers.insert(k.trim().to_lowercase(), v.trim().to_string()); }}
    }}
    let client_ip = stream.peer_addr().map(|a| a.ip().to_string()).unwrap_or("127.0.0.1".to_string());
    let (path_part, query_part) = if let Some((p,q)) = raw_path.split_once('?') {{ (p.to_string(), Some(q.to_string())) }} else {{ (raw_path.clone(), None) }};
    let decoded_path = percent_decode_str(&path_part).decode_utf8_lossy().to_string();
    let mut query_flat: HashMap<String,String> = HashMap::new();
    if let Some(q) = &query_part {{
        for (k,v) in form_urlencoded::parse(q.as_bytes()) {{ query_flat.insert(k.to_string(), v.to_string()); }}
    }}
    let mut effective_path = decoded_path.clone();
    if let Some(ref rp) = cfg.route_prefix {{
        if effective_path == *rp {{
            effective_path = "/".to_string();
        }} else if effective_path.starts_with(&format!("{{}}/", rp)) {{
            effective_path = effective_path[rp.len()..].to_string();
            if effective_path.is_empty() {{ effective_path = "/".to_string(); }}
            if !effective_path.starts_with('/') {{ effective_path = format!("/{{}}", effective_path); }}
        }} else {{
            let resp = build_404(&cfg, &effective_path, &raw_path, &query_flat);
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
    }}

    // auth
    if !cfg.auth.is_empty() {{
        let mut ok = false;
        if let Some(auth_val) = headers.get("authorization") {{
            if auth_val.to_lowercase().starts_with("basic ") {{
                let b64 = auth_val[6..].trim();
                if let Ok(dec) = BASE64.decode(b64) {{
                    if let Ok(s) = String::from_utf8(dec) {{
                        if let Some((u,p)) = s.split_once(':') {{
                            for en in &cfg.auth {{
                                if en.username==u && check_auth(en, p) {{ ok=true; break; }}
                            }}
                        }}
                    }}
                }}
            }}
        }}
        if !ok {{
            let mut hdr = vec![
                ("WWW-Authenticate".to_string(), "Basic".to_string()),
                ("Content-Length".to_string(), "0".to_string()),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            for (k,v) in &cfg.headers {{ if !hdr.iter().any(|(hk,_)| hk.to_lowercase()==k.to_lowercase()) {{ hdr.push((k.clone(), v.clone())); }} }}
            let resp = HttpResponse{{status:401, reason:"Unauthorized".to_string(), headers: hdr, body: vec![]}};
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            if cfg.verbose {{ println!("{{}} [INFO] {{}} \\"{{}} {{}} HTTP/1.1\\" 401 0 \\"-\\" \\"-\\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path); }}
            return Ok(());
        }}
    }}

    if effective_path.starts_with("/__miniserve_internal/") {{
        if effective_path == "/__miniserve_internal/favicon.svg" {{
            let body = FAVICON_SVG.as_bytes().to_vec();
            let mut hdr = vec![
                ("Content-Type".to_string(), "image/svg+xml".to_string()),
                ("Content-Length".to_string(), body.len().to_string()),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            for (k,v) in &cfg.headers {{ if !hdr.iter().any(|(hk,_)| hk.to_lowercase()==k.to_lowercase()) {{ hdr.push((k.clone(), v.clone())); }} }}
            let resp = HttpResponse{{status:200, reason:"OK".to_string(), headers: hdr, body}};
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }} else if effective_path == "/__miniserve_internal/style.css" {{
            let body = STYLE_CSS.as_bytes().to_vec();
            let mut hdr = vec![
                ("Content-Type".to_string(), "text/css; charset=utf-8".to_string()),
                ("Content-Length".to_string(), body.len().to_string()),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            for (k,v) in &cfg.headers {{ if !hdr.iter().any(|(hk,_)| hk.to_lowercase()==k.to_lowercase()) {{ hdr.push((k.clone(), v.clone())); }} }}
            let resp = HttpResponse{{status:200, reason:"OK".to_string(), headers: hdr, body}};
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }} else if effective_path == "/__miniserve_internal/api" {{
            let clen: usize = headers.get("content-length").and_then(|v| v.parse().ok()).unwrap_or(0);
            let mut buf = vec![0u8; clen];
            if clen>0 {{ reader.read_exact(&mut buf)?; }}
            let s = String::from_utf8_lossy(&buf);
            let mut dir_opt: Option<String> = None;
            if let Ok(j) = serde_json::from_str::<serde_json::Value>(&s) {{
                if let Some(serde_json::Value::String(st)) = j.get("DirSize") {{ dir_opt = Some(st.clone()); }}
            }}
            if let Some(dp) = dir_opt {{
                if cfg.dir_size {{
                    let fs_path = fs_from_url(&cfg, &dp);
                    let sz = calc_dir_size(&fs_path, &cfg);
                    let disp = cfg.size_display.clone();
                    let sz_str = fmt_size(sz, &disp);
                    let body = sz_str.into_bytes();
                    let mut hdr = vec![
                        ("Content-Type".to_string(), "text/plain; charset=utf-8".to_string()),
                        ("Content-Length".to_string(), body.len().to_string()),
                        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                    ];
                    for (k,v) in &cfg.headers {{ if !hdr.iter().any(|(hk,_)| hk.to_lowercase()==k.to_lowercase()) {{ hdr.push((k.clone(), v.clone())); }} }}
                    let resp = HttpResponse{{status:200, reason:"OK".to_string(), headers: hdr, body}};
                    write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                }} else {{
                    let resp = simple_resp(404, "Not Found", &cfg);
                    write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                }}
            }} else {{
                let resp = simple_resp(400, "Bad Request", &cfg);
                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            }}
            return Ok(());
        }} else {{
            let resp = build_404(&cfg, &effective_path, &raw_path, &query_flat);
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
    }}

    if effective_path.starts_with("/upload") && method=="POST" {{
        let upload_path_param = query_flat.get("path").cloned().unwrap_or("/".to_string());
        if cfg.upload_files.is_none() {{
            let resp = simple_resp(403, "Forbidden", &cfg);
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
        if let Some(Some(ref allowed)) = cfg.upload_files {{
            let allowed_norm = if allowed.ends_with('/') {{ allowed.clone() }} else {{ format!("{{}}/", allowed) }};
            let param_norm = if upload_path_param.ends_with('/') {{ upload_path_param.clone() }} else {{ format!("{{}}/", upload_path_param) }};
            if upload_path_param != *allowed && !param_norm.starts_with(&allowed_norm) {{
                let body = b"Upload not allowed to this directory".to_vec();
                let mut hdr = vec![
                    ("Content-Type".to_string(), "text/plain; charset=utf-8".to_string()),
                    ("Content-Length".to_string(), body.len().to_string()),
                    ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                ];
                let resp = HttpResponse{{status:403, reason:"Forbidden".to_string(), headers: hdr, body}};
                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                return Ok(());
            }}
        }}
        let clen: usize = headers.get("content-length").and_then(|v| v.parse().ok()).unwrap_or(0);
        let ctype = headers.get("content-type").cloned().unwrap_or_default();
        if ctype.starts_with("multipart/form-data") {{
            let boundary = ctype.split("boundary=").nth(1).unwrap_or("").trim_matches('"').to_string();
            let mut buf = vec![0u8; clen];
            reader.read_exact(&mut buf)?;
            if let Ok(parts) = parse_multipart(&buf, &boundary) {{
                for part in parts {{
                    let disp = part.headers.get("content-disposition").cloned().unwrap_or_default();
                    let fname = extract_param(&disp, "filename");
                    let name = extract_param(&disp, "name");
                    if let Some(fnm) = fname {{
                        let base = Path::new(&fnm).file_name().and_then(|n| n.to_str()).unwrap_or(&fnm).to_string();
                        if base.is_empty() {{ continue; }}
                        if let Some(ref mt) = cfg.media_type {{
                            let ok = match mt {{
                                MediaType::Image => matches!(Path::new(&base).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase().as_str(), "jpg"|"jpeg"|"png"|"gif"|"bmp"|"webp"|"svg"|"ico"),
                                MediaType::Audio => matches!(Path::new(&base).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase().as_str(), "mp3"|"wav"|"ogg"|"flac"|"aac"),
                                MediaType::Video => matches!(Path::new(&base).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase().as_str(), "mp4"|"avi"|"mkv"|"mov"|"webm"),
                            }};
                            if !ok {{
                                let body = format!("File type not allowed: {{}}", base).into_bytes();
                                let resp = HttpResponse{{status:400, reason:"Bad Request".to_string(), headers: vec![("Content-Type".to_string(),"text/plain".to_string()),("Content-Length".to_string(), body.len().to_string())], body}};
                                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                                return Ok(());
                            }}
                        }}
                        let target_dir = fs_from_url(&cfg, &upload_path_param);
                        if !target_dir.is_dir() {{
                            let body = format!("Invalid path\\ncaused by: cannot upload file to {{}}, since it's not a directory", target_dir.display()).into_bytes();
                            let resp = HttpResponse{{status:400, reason:"Bad Request".to_string(), headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(), body.len().to_string())], body}};
                            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                            return Ok(());
                        }}
                        let mut dest = target_dir.join(&base);
                        match cfg.on_duplicate {{
                            OnDuplicate::Error => if dest.exists() {{
                                let body = format!("File {{}} already exists", base).into_bytes();
                                let resp = HttpResponse{{status:400, reason:"Bad Request".to_string(), headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(), body.len().to_string())], body}};
                                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                                return Ok(());
                            }},
                            OnDuplicate::Rename => if dest.exists() {{
                                dest = gen_rename(&target_dir, &base);
                            }},
                            OnDuplicate::Overwrite => {{}},
                        }}
                        let res = if let Some(ref td) = cfg.temp_dir {{
                            let tmp = td.join(format!("miniserve_tmp_{{}}", Utc::now().timestamp_nanos_opt().unwrap_or(0)));
                            match std::fs::write(&tmp, &part.body) {{
                                Ok(_) => std::fs::rename(&tmp, &dest).or_else(|_| {{ std::fs::copy(&tmp, &dest).map(|_| ()).map(|_| {{ let _ = std::fs::remove_file(&tmp); }}).map_err(|e| e) }}),
                                Err(e) => Err(e),
                            }}
                        }} else {{
                            std::fs::write(&dest, &part.body)
                        }};
                        if res.is_err() {{
                            let resp = simple_resp(500, "Internal Server Error", &cfg);
                            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                            return Ok(());
                        }}
                        if let Some(mode) = cfg.chmod {{
                            #[cfg(unix)] {{
                                use std::os::unix::fs::PermissionsExt;
                                let _ = std::fs::set_permissions(&dest, std::fs::Permissions::from_mode(mode));
                            }}
                        }}
                    }} else {{
                        if name.as_deref()==Some("mkdir") {{
                            if !cfg.mkdir {{
                                let body = format!("Insufficient permissions to create file in {{}}", fs_from_url(&cfg, &upload_path_param).display()).into_bytes();
                                let resp = HttpResponse{{status:403, reason:"Forbidden".to_string(), headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(), body.len().to_string())], body}};
                                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                                return Ok(());
                            }}
                            let dir_name = String::from_utf8_lossy(&part.body).trim().to_string();
                            if dir_name.is_empty() || dir_name.contains('/') || dir_name.contains("..") {{
                                let resp = simple_resp(400, "Bad Request", &cfg);
                                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                                return Ok(());
                            }}
                            let target = fs_from_url(&cfg, &upload_path_param).join(&dir_name);
                            if let Err(e) = std::fs::create_dir(&target) {{
                                let resp = simple_resp(500, "Internal Server Error", &cfg);
                                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                                return Ok(());
                            }}
                        }}
                    }}
                }}
                let loc = {{
                    let mut l = upload_path_param.clone();
                    if !l.starts_with('/') {{ l = format!("/{{}}", l); }}
                    if let Some(ref rp) = cfg.route_prefix {{ format!("{{}}{{}}", rp, l) }} else {{ l }}
                }};
                let mut hdr = vec![
                    ("Location".to_string(), loc),
                    ("Content-Length".to_string(), "0".to_string()),
                    ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
                ];
                let resp = HttpResponse{{status:303, reason:"See Other".to_string(), headers: hdr, body: vec![]}};
                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                return Ok(());
            }} else {{
                let resp = simple_resp(400, "Bad Request", &cfg);
                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                return Ok(());
            }}
        }}
    }}

    if effective_path.starts_with("/rm") && method=="POST" {{
        if cfg.rm_files.is_none() {{
            let resp = simple_resp(403, "Forbidden", &cfg);
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
        let rm_path = query_flat.get("path").cloned().unwrap_or("/".to_string());
        if let Some(Some(ref allowed)) = cfg.rm_files {{
            let an = if allowed.ends_with('/') {{ allowed.clone() }} else {{ format!("{{}}/", allowed) }};
            let pn = if rm_path.ends_with('/') {{ rm_path.clone() }} else {{ format!("{{}}/", rm_path) }};
            if rm_path != *allowed && !pn.starts_with(&an) {{
                let body = b"Deletion not allowed".to_vec();
                let resp = HttpResponse{{status:403, reason:"Forbidden".to_string(), headers: vec![("Content-Type".to_string(),"text/plain; charset=utf-8".to_string()),("Content-Length".to_string(), body.len().to_string())], body}};
                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                return Ok(());
            }}
        }}
        let target = fs_from_url(&cfg, &rm_path);
        if !target.exists() {{
            let resp = simple_resp(404, "Not Found", &cfg);
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
        let _ = if target.is_dir() {{ std::fs::remove_dir_all(&target) }} else {{ std::fs::remove_file(&target) }};
        let mut hdr = vec![("Location".to_string(), "/".to_string()),("Content-Length".to_string(),"0".to_string())];
        let resp = HttpResponse{{status:303, reason:"See Other".to_string(), headers: hdr, body: vec![]}};
        write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
        return Ok(());
    }}

    if cfg.serve_is_file {{
        if effective_path=="/" {{
            serve_file(&mut stream, &cfg, &cfg.serve_path, &method, &headers, &query_flat, &client_ip, &raw_path)?;
            return Ok(());
        }} else {{
            let resp = build_404(&cfg, &effective_path, &raw_path, &query_flat);
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
    }}

    let fs_path = fs_from_url(&cfg, &effective_path);

    if cfg.no_symlinks {{
        if let Ok(m) = std::fs::symlink_metadata(&fs_path) {{
            if m.file_type().is_symlink() {{
                let resp = build_404(&cfg, &effective_path, &raw_path, &query_flat);
                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                return Ok(());
            }}
        }}
    }}

    // check outside
    if let Ok(canon) = fs_path.canonicalize() {{
        if let Ok(serve_canon) = cfg.serve_path.canonicalize() {{
            if !canon.starts_with(serve_canon) {{
                let resp = build_404(&cfg, &effective_path, &raw_path, &query_flat);
                write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                return Ok(());
            }}
        }}
    }} else {{
        // If not exists, check parent
        if let Some(parent) = fs_path.parent() {{
            if let Ok(p_canon) = parent.canonicalize() {{
                if let Ok(s_canon) = cfg.serve_path.canonicalize() {{
                    if !p_canon.starts_with(s_canon) {{
                        let resp = build_404(&cfg, &effective_path, &raw_path, &query_flat);
                        write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
                        return Ok(());
                    }}
                }}
            }}
        }}
    }}

    if fs_path.is_file() {{
        serve_file(&mut stream, &cfg, &fs_path, &method, &headers, &query_flat, &client_ip, &raw_path)?;
        return Ok(());
    }}

    if fs_path.is_dir() {{
        if let Some(dl) = query_flat.get("download") {{
            if dl=="tar" && cfg.enable_tar {{
                serve_tar(&mut stream, &cfg, &fs_path, false, &method, &headers, &query_flat, &client_ip, &raw_path)?;
                return Ok(());
            }}
            if dl=="tar_gz" && cfg.enable_tar_gz {{
                serve_tar(&mut stream, &cfg, &fs_path, true, &method, &headers, &query_flat, &client_ip, &raw_path)?;
                return Ok(());
            }}
            if dl=="zip" && cfg.enable_zip {{
                serve_zip(&mut stream, &cfg, &fs_path, &method, &headers, &query_flat, &client_ip, &raw_path)?;
                return Ok(());
            }}
        }}
        if let Some(ref idx) = cfg.index {{
            let p = fs_path.join(idx);
            if p.is_file() {{
                serve_file(&mut stream, &cfg, &p, &method, &headers, &query_flat, &client_ip, &raw_path)?;
                return Ok(());
            }}
        }}
        if cfg.disable_indexing {{
            let resp = build_404_file_not_found(&cfg, &effective_path, &raw_path, &query_flat);
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
        if !effective_path.ends_with('/') {{
            let mut newp = effective_path.clone() + "/";
            if let Some(q) = query_part {{
                newp = format!("{{}}?{{}}", newp, q);
            }}
            let loc = if let Some(ref rp) = cfg.route_prefix {{ format!("{{}}{{}}", rp, newp) }} else {{ newp }};
            let resp = HttpResponse{{status:301, reason:"Moved Permanently".to_string(), headers: vec![("Location".to_string(), loc),("Content-Length".to_string(),"0".to_string())], body: vec![]}};
            write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
            return Ok(());
        }}
        serve_dir(&mut stream, &cfg, &fs_path, &effective_path, &raw_path, &method, &headers, &query_flat, &client_ip)?;
        return Ok(());
    }}

    if cfg.pretty_urls {{
        let mut cand = fs_path.clone();
        cand.set_extension("html");
        if cand.is_file() {{
            serve_file(&mut stream, &cfg, &cand, &method, &headers, &query_flat, &client_ip, &raw_path)?;
            return Ok(());
        }}
    }}

    if cfg.spa {{
        if let Some(ref idx) = cfg.index {{
            let p = cfg.serve_path.join(idx);
            if p.is_file() {{
                serve_file(&mut stream, &cfg, &p, &method, &headers, &query_flat, &client_ip, &raw_path)?;
                return Ok(());
            }}
        }}
    }}

    let resp = build_404(&cfg, &effective_path, &raw_path, &query_flat);
    write_resp(&mut stream, &cfg, resp, &method, &headers, &query_flat)?;
    Ok(())
}}

fn fs_from_url(cfg: &Config, url_path: &str) -> PathBuf {{
    let trimmed = url_path.trim_start_matches('/');
    let mut pb = cfg.serve_path.clone();
    for comp in Path::new(trimmed).components() {{
        match comp {{
            Component::Normal(os) => pb.push(os),
            Component::ParentDir => {{ pb.pop(); }},
            Component::CurDir => {{}},
            _ => {{}},
        }}
    }}
    pb
}}

fn fmt_size(size: u64, disp: &SizeDisplay) -> String {{
    match disp {{
        SizeDisplay::Exact => format!("{{}} B", size),
        SizeDisplay::Human => {{
            if size < 1024 {{ format!("{{}} B", size) }}
            else if size < 1024*1024 {{ format!("{{:.1}} KiB", size as f64/1024.0) }}
            else if size < 1024*1024*1024 {{ format!("{{:.1}} MiB", size as f64/(1024.0*1024.0)) }}
            else {{ format!("{{:.1}} GiB", size as f64/(1024.0*1024.0*1024.0)) }}
        }}
    }}
}}

fn calc_dir_size(path: &Path, cfg: &Config) -> u64 {{
    let mut total = 0u64;
    if let Ok(rd) = std::fs::read_dir(path) {{
        for ent in rd.flatten() {{
            let p = ent.path();
            if !cfg.hidden {{
                if let Some(name) = p.file_name().and_then(|n| n.to_str()) {{ if name.starts_with('.') {{ continue; }} }}
            }}
            if cfg.no_symlinks {{
                if let Ok(m) = std::fs::symlink_metadata(&p) {{ if m.file_type().is_symlink() {{ continue; }} }}
            }}
            if let Ok(m) = std::fs::metadata(&p) {{
                if m.is_dir() {{ total += calc_dir_size(&p, cfg); }} else {{ total += m.len(); }}
            }}
        }}
    }}
    total
}}

struct HttpResponse {{
    status: u16,
    reason: String,
    headers: Vec<(String,String)>,
    body: Vec<u8>,
}}

fn simple_resp(code: u16, text: &str, cfg: &Config) -> HttpResponse {{
    let body = text.as_bytes().to_vec();
    let mut hdr = vec![
        ("Content-Type".to_string(), "text/plain; charset=utf-8".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &cfg.headers {{ hdr.push((k.clone(), v.clone())); }}
    HttpResponse{{status: code, reason: match code {{200=>"OK", 404=>"Not Found", 403=>"Forbidden", _=>"OK"}}.to_string(), headers: hdr, body}}
}}

fn build_404(cfg: &Config, eff: &str, raw: &str, query: &HashMap<String,String>) -> HttpResponse {{
    let rp = cfg.route_prefix.clone().unwrap_or_default();
    let footer = if cfg.hide_version {{ "".to_string() }} else {{ format!(r#"<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/{}</div>"#, VERSION) }};
    let root = cfg.route_prefix.clone().unwrap_or_else(|| "/".to_string());
    let html = format!(r#"<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{}/__miniserve_internal/style.css"><title>404 Not Found</title><script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {{
                        if (name && name != "default") {{
                            localStorage.setItem('theme', name);
                            document.body.setAttribute("data-theme", name)
                        }} else {{
                            localStorage.removeItem('theme');
                            document.body.removeAttribute("data-theme")
                        }}
                    }}

                    // read theme from local storage and apply it to body
                    function loadColorScheme() {{
                        var name = localStorage.getItem('theme');
                        updateColorScheme(name);
                    }}

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script><script>const API_ROUTE = '{}/__miniserve_internal/api';
                    let dirSizeCache = {{}};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {{
                        return fetch(API_ROUTE, {{
                            headers: {{
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            }},
                            method: 'POST',
                            body: JSON.stringify({{
                                DirSize: dir
                            }})
                        }}).then(resp => resp.ok ? resp.text() : "~")
                    }}

                    function updateSizeCells() {{
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {{
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {{
                                cell.dataset.size = dirSizeCache[target];
                            }} else {{
                                fetchDirSize(target).then(dir_size => {{
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                }})
                                .catch(error => console.error("Error fetching dir size:", error));
                            }}
                        }})
                    }}
                    setInterval(updateSizeCells, 1000);
                </script></head><body><div class="error"><p>404 Not Found</p><p>Route {} could not be found</p><div class="error-nav"><a class="error-back" href="{}">Go back to file listing</a></div><p class="footer">{}</p></div></body></html>"#, rp, rp, rp, eff, root, footer);
    let body = html.into_bytes();
    let mut hdr = vec![
        ("Content-Type".to_string(), "text/html".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &cfg.headers {{ hdr.push((k.clone(), v.clone())); }}
    HttpResponse{{status:404, reason:"Not Found".to_string(), headers: hdr, body}}
}}

fn build_404_file_not_found(cfg: &Config, eff: &str, raw: &str, query: &HashMap<String,String>) -> HttpResponse {{
    let rp = cfg.route_prefix.clone().unwrap_or_default();
    let footer = if cfg.hide_version {{ "".to_string() }} else {{ format!(r#"<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/{}</div>"#, VERSION) }};
    let html = format!(r#"<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{}/__miniserve_internal/style.css"><title>404 Not Found</title><script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {{
                        if (name && name != "default") {{
                            localStorage.setItem('theme', name);
