                        updateColorScheme(name);
                    }}

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script><script>const API_ROUTE = '{}/__miniserve_internal/api';
                    let dirSizeCache = {{}};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {{
                        return fetch(API_ROUTE, {{
                            headers: {{
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            }},
                            method: 'POST',
                            body: JSON.stringify({{
                                DirSize: dir
                            }})
                        }}).then(resp => resp.ok ? resp.text() : "~")
                    }}

                    function updateSizeCells() {{
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {{
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {{
                                cell.dataset.size = dirSizeCache[target];
                            }} else {{
                                fetchDirSize(target).then(dir_size => {{
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                }})
                                .catch(error => console.error("Error fetching dir size:", error));
                            }}
                        }})
                    }}
                    setInterval(updateSizeCells, 1000);
                </script></head><body><div class="error"><p>404 Not Found</p><p>File not found.</p><p class="footer">{}</p></div></body></html>"#, rp, rp, rp, footer);
    let body = html.into_bytes();
    let mut hdr = vec![
        ("Content-Type".to_string(), "text/html".to_string()),
        ("Content-Length".to_string(), body.len().to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    for (k,v) in &cfg.headers {{ hdr.push((k.clone(), v.clone())); }}
    HttpResponse{{status:404, reason:"Not Found".to_string(), headers: hdr, body}}
}}

struct MultipartPart {{
    headers: HashMap<String,String>,
    body: Vec<u8>,
}}

fn parse_multipart(data: &[u8], boundary: &str) -> Result<Vec<MultipartPart>, String> {{
    if boundary.is_empty() {{ return Err("no boundary".to_string()); }}
    let b_marker = format!("--{{}}", boundary).into_bytes();
    let b_sep = format!("\\r\\n--{{}}", boundary).into_bytes();
    let mut parts = Vec::new();
    let mut pos = 0usize;
    while pos < data.len() {{
        if let Some(idx) = data[pos..].windows(b_marker.len()).position(|w| w==b_marker.as_slice()) {{
            let abs = pos+idx;
            let mut hs = abs + b_marker.len();
            if data.len()>hs+1 && data[hs]==b'\\r' && data[hs+1]==b'\\n' {{ hs+=2; }}
            if let Some(he) = data[hs..].windows(4).position(|w| w==b"\\r\\n\\r\\n") {{
                let header_end = hs+he;
                let body_start = header_end+4;
                if let Some(next) = data[body_start..].windows(b_sep.len()).position(|w| w==b_sep.as_slice()) {{
                    let body_end = body_start+next;
                    let header_bytes = &data[hs..header_end];
                    let body_bytes = &data[body_start..body_end];
                    let header_str = String::from_utf8_lossy(header_bytes);
                    let mut hm = HashMap::new();
                    for line in header_str.lines() {{
                        if let Some((k,v)) = line.split_once(':') {{ hm.insert(k.trim().to_lowercase(), v.trim().to_string()); }}
                    }}
                    parts.push(MultipartPart{{headers: hm, body: body_bytes.to_vec()}});
                    pos = body_end;
                    continue;
                }} else {{
                    let end_marker = format!("--{{}}--", boundary).into_bytes();
                    if let Some(end) = data[body_start..].windows(end_marker.len()).position(|w| w==end_marker.as_slice()) {{
                        let mut body_end = body_start+end;
                        if body_end>=2 && data[body_end-2]==b'\\r' && data[body_end-1]==b'\\n' {{ body_end-=2; }}
                        let header_bytes = &data[hs..header_end];
                        let body_bytes = &data[body_start..body_end];
                        let header_str = String::from_utf8_lossy(header_bytes);
                        let mut hm = HashMap::new();
                        for line in header_str.lines() {{
                            if let Some((k,v)) = line.split_once(':') {{ hm.insert(k.trim().to_lowercase(), v.trim().to_string()); }}
                        }}
                        parts.push(MultipartPart{{headers: hm, body: body_bytes.to_vec()}});
                        break;
                    }} else {{ break; }}
                }}
            }} else {{ break; }}
        }} else {{ break; }}
    }}
    Ok(parts)
}}

fn extract_param(disp: &str, param: &str) -> Option<String> {{
    for part in disp.split(';') {{
        let p = part.trim();
        if let Some((k,v)) = p.split_once('=') {{
            if k.trim()==param {{
                let mut val = v.trim().to_string();
                if val.starts_with('"') && val.ends_with('"') && val.len()>=2 {{ val = val[1..val.len()-1].to_string(); }}
                return Some(val);
            }}
        }}
    }}
    None
}}

fn gen_rename(dir: &Path, original: &str) -> PathBuf {{
    let path = Path::new(original);
    let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or(original);
    let ext = path.extension().and_then(|s| s.to_str()).map(|s| format!(".{{}}", s)).unwrap_or_default();
    let mut c = 1;
    loop {{
        let new_name = format!("{{}}-{{}}{{}}", stem, c, ext);
        let new_path = dir.join(&new_name);
        if !new_path.exists() {{ return new_path; }}
        c+=1;
    }}
}}

fn serve_file(stream: &mut TcpStream, cfg: &Config, file_path: &Path, method: &str, headers: &HashMap<String,String>, query: &HashMap<String,String>, client_ip: &str, raw_path: &str) -> std::io::Result<()> {{
    let meta = std::fs::metadata(file_path)?;
    let size = meta.len();
    let mtime = meta.modified().unwrap_or(SystemTime::now());
    let mtime_secs = mtime.duration_since(UNIX_EPOCH).unwrap_or(Duration::new(0,0)).as_secs();
    let last_mod = Utc.timestamp_opt(mtime_secs as i64, 0).unwrap().format("%a, %d %b %Y %H:%M:%S GMT").to_string();
    let etag = format!("\\"%x:%x:%x\\"", mtime_secs, size, file_path.display().to_string().len());

    if let Some(if_none) = headers.get("if-none-match") {{
        if if_none.trim()==etag || if_none.trim()==etag.trim_matches('"') {{
            let mut hdr = vec![
                ("Content-Disposition".to_string(), format!("inline; filename=\\"{}\\"", file_path.file_name().and_then(|n| n.to_str()).unwrap_or("file"))),
                ("Accept-Ranges".to_string(), "bytes".to_string()),
                ("Last-Modified".to_string(), last_mod.clone()),
                ("ETag".to_string(), etag.clone()),
                ("Content-Type".to_string(), mime_guess(file_path)),
                ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
            ];
            let resp = HttpResponse{{status:304, reason:"Not Modified".to_string(), headers: hdr, body: vec![]}};
            write_resp(stream, cfg, resp, method, headers, query)?;
            if cfg.verbose {{ println!("{{}} [INFO] {{}} \\"{{}} {{}} HTTP/1.1\\" 304 0 \\"-\\" \\"-\\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path); }}
            return Ok(());
        }}
    }}

    let mut start: u64 = 0;
    let mut end: u64 = size.saturating_sub(1);
    let mut partial = false;
    if let Some(rh) = headers.get("range") {{
        if rh.starts_with("bytes=") {{
            let spec = &rh[6..];
            if let Some((s,e)) = spec.split_once('-') {{
                let sp = if s.is_empty() {{ None }} else {{ s.parse::<u64>().ok() }};
                let ep = if e.is_empty() {{ None }} else {{ e.parse::<u64>().ok() }};
                match (sp, ep) {{
                    (Some(sv), Some(ev)) => {{ start = sv.min(size.saturating_sub(1)); end = ev.min(size.saturating_sub(1)); partial=true; }},
                    (Some(sv), None) => {{ start = sv; end = size.saturating_sub(1); partial=true; }},
                    (None, Some(ev)) => {{ if ev <= size {{ start = size-ev; end = size-1; partial=true; }} }},
                    _ => {{}}
                }}
            }}
        }}
    }}
    let clen = if partial {{ end-start+1 }} else {{ size }};
    let mut file = File::open(file_path)?;
    let mut body = Vec::with_capacity(clen as usize);
    if partial {{
        use std::io::Seek;
        file.seek(std::io::SeekFrom::Start(start))?;
        let mut limited = file.take(clen);
        limited.read_to_end(&mut body)?;
    }} else {{
        if method!="HEAD" {{ file.read_to_end(&mut body)?; }}
    }}
    let mime = mime_guess(file_path);
    let disp_type = if file_path.file_name().and_then(|n| n.to_str()).map(|n| n.starts_with('.')).unwrap_or(false) {{ "attachment" }} else {{ if mime=="application/octet-stream" {{ "attachment" }} else {{ "inline" }} }};
    let fname = file_path.file_name().and_then(|n| n.to_str()).unwrap_or("file");
    let mut hdr = vec![
        ("Content-Length".to_string(), clen.to_string()),
        ("Content-Type".to_string(), mime.clone()),
        ("Content-Disposition".to_string(), format!("{{}}; filename=\\"{}\\"", disp_type, fname)),
        ("Accept-Ranges".to_string(), "bytes".to_string()),
        ("Last-Modified".to_string(), last_mod),
        ("ETag".to_string(), etag),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    if partial {{ hdr.push(("Content-Range".to_string(), format!("bytes {{}}-{{}}/{{}}", start, end, size))); }}
    for (k,v) in &cfg.headers {{ if !hdr.iter().any(|(hk,_)| hk.to_lowercase()==k.to_lowercase()) {{ hdr.push((k.clone(), v.clone())); }} }}
    let status = if partial {{206}} else {{200}};
    let reason = if partial {{"Partial Content"}} else {{"OK"}};
    let resp = HttpResponse{{status, reason: reason.to_string(), headers: hdr, body: if method=="HEAD" {{vec![]}} else {{body}}}};
    let blen = resp.body.len();
    write_resp(stream, cfg, resp, method, headers, query)?;
    if cfg.verbose {{ println!("{{}} [INFO] {{}} \\"{{}} {{}} HTTP/1.1\\" {{}} {{}} \\"-\\" \\"-\\" 0.000000", Local::now().format("%a, %d %b %Y %H:%M:%S %z"), client_ip, method, raw_path, status, blen); }}
    Ok(())
}}

fn mime_guess(path: &Path) -> String {{
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match ext.as_str() {{
        "html"|"htm" => "text/html; charset=utf-8".to_string(),
        "css" => "text/css; charset=utf-8".to_string(),
        "js" => "text/javascript; charset=utf-8".to_string(),
        "json" => "application/json".to_string(),
        "txt"|"md"|"rs"|"toml"|"yaml"|"yml" => "text/plain; charset=utf-8".to_string(),
        "svg" => "image/svg+xml".to_string(),
        "png" => "image/png".to_string(),
        "jpg"|"jpeg" => "image/jpeg".to_string(),
        "gif" => "image/gif".to_string(),
        "webp" => "image/webp".to_string(),
        "ico" => "image/x-icon".to_string(),
        "mp3" => "audio/mpeg".to_string(),
        "wav" => "audio/wav".to_string(),
        "mp4" => "video/mp4".to_string(),
        "pdf" => "application/pdf".to_string(),
        "zip" => "application/zip".to_string(),
        "tar" => "application/x-tar".to_string(),
        "gz"|"tgz" => "application/gzip".to_string(),
        _ => "application/octet-stream".to_string(),
    }}
}}

fn write_resp(stream: &mut TcpStream, cfg: &Config, resp: HttpResponse, method: &str, req_headers: &HashMap<String,String>, query: &HashMap<String,String>) -> std::io::Result<()> {{
    let mut body = resp.body;
    let mut hdrs = resp.headers;
    let should_compress = cfg.compress && req_headers.get("accept-encoding").map(|v| v.contains("gzip")).unwrap_or(false) && body.len()>0 && hdrs.iter().any(|(k,v)| k.to_lowercase()=="content-type" && (v.contains("text/html") || v.contains("text/plain") || v.contains("application/json") || v.contains("text/css")));
    if should_compress {{
        let mut enc = GzEncoder::new(Vec::new(), FlateCompression::default());
        if enc.write_all(&body).is_ok() {{
            if let Ok(comp) = enc.finish() {{
                body = comp;
                hdrs.retain(|(k,_)| k.to_lowercase()!="content-length");
                hdrs.push(("Content-Length".to_string(), body.len().to_string()));
                hdrs.push(("Content-Encoding".to_string(), "gzip".to_string()));
                hdrs.push(("Vary".to_string(), "accept-encoding".to_string()));
            }}
        }}
    }}
    if !hdrs.iter().any(|(k,_)| k.to_lowercase()=="date") {{
        hdrs.push(("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()));
    }}
    let mut out = format!("HTTP/1.1 {{}} {{}}\\r\\n", resp.status, resp.reason);
    for (k,v) in &hdrs {{ out.push_str(&format!("{{}}: {{}}\\r\\n", k, v)); }}
    out.push_str("\\r\\n");
    stream.write_all(out.as_bytes())?;
    if method!="HEAD" {{ stream.write_all(&body)?; }}
    stream.flush()?;
    Ok(())
}}

fn serve_dir(stream: &mut TcpStream, cfg: &Config, fs_path: &Path, eff_path: &str, raw_path: &str, method: &str, req_headers: &HashMap<String,String>, query_flat: &HashMap<String,String>, client_ip: &str) -> std::io::Result<()> {{
    // Simplified dir listing that matches earlier Python version but in Rust
    let sort_method = query_flat.get("sort").map(|s| match s.as_str() {{"name"=>SortingMethod::Name, "size"=>SortingMethod::Size, "date"=>SortingMethod::Date, _=>cfg.sorting_method.clone()}}).unwrap_or(cfg.sorting_method.clone());
    let sort_order = query_flat.get("order").map(|s| match s.as_str() {{"asc"=>SortingOrder::Asc, "desc"=>SortingOrder::Desc, _=>cfg.sorting_order.clone()}}).unwrap_or(cfg.sorting_order.clone());

    struct EntryInfo {{
        name: String,
        is_dir: bool,
        is_symlink: bool,
        symlink_target: Option<String>,
        size: u64,
        mtime: SystemTime,
        mtime_str: String,
    }}

    let mut infos: Vec<EntryInfo> = Vec::new();
    if let Ok(rd) = std::fs::read_dir(fs_path) {{
        for ent in rd.flatten() {{
            let name = ent.file_name().to_string_lossy().to_string();
            if !cfg.hidden && name.starts_with('.') {{ continue; }}
            let p = ent.path();
            let is_symlink = std::fs::symlink_metadata(&p).map(|m| m.file_type().is_symlink()).unwrap_or(false);
            if cfg.no_symlinks && is_symlink {{ continue; }}
            let mut target: Option<String> = None;
            if is_symlink && cfg.symlink_info {{
                if let Ok(t) = std::fs::read_link(&p) {{ target = Some(t.to_string_lossy().to_string()); }}
            }}
            let meta = if is_symlink {{ std::fs::metadata(&p).or_else(|_| std::fs::symlink_metadata(&p)).ok() }} else {{ std::fs::metadata(&p).ok() }};
            let (sz, mt) = if let Some(m) = meta {{ (if m.is_dir() {{0}} else {{m.len()}}, m.modified().unwrap_or(SystemTime::now())) }} else {{ (0, SystemTime::now()) }};
            let local_dt: DateTime<Local> = mt.into();
            let mstr = local_dt.format("%Y-%m-%d %H:%M:%S %:z").to_string();
            infos.push(EntryInfo{{name, is_dir: p.is_dir(), is_symlink, symlink_target: target, size: sz, mtime: mt, mtime_str: mstr}});
        }}
    }}

    infos.sort_by(|a,b| {{
        if cfg.dirs_first {{
            match (a.is_dir, b.is_dir) {{
                (true,false) => return std::cmp::Ordering::Less,
                (false,true) => return std::cmp::Ordering::Greater,
                _=>{{}}
            }}
        }}
        let ord = match sort_method {{
            SortingMethod::Name => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
            SortingMethod::Size => a.size.cmp(&b.size),
            SortingMethod::Date => a.mtime.cmp(&b.mtime),
        }};
        match sort_order {{ SortingOrder::Asc => ord, SortingOrder::Desc => ord.reverse() }}
    }});

    let is_raw = query_flat.get("raw").map(|v| v=="true").unwrap_or(false);
    if is_raw {{
        let mut html = String::new();
        html.push_str(r#"<!DOCTYPE html><html><body><table><thead><th class="name">Name</th><th class="size">Size</th><th class="date">Last modification</th></thead><tbody>"#);
        if eff_path != "/" {{
            let trimmed = eff_path.trim_end_matches('/');
            let parent = if let Some(pos) = trimmed.rfind('/') {{ if pos==0 {{"/".to_string()}} else {{trimmed[..pos].to_string() + "/"}} }} else {{"/".to_string()}};
            html.push_str(&format!(r#"<tr><td colspan="3"><p><a class="root" href="{{}}?raw=true">..</a></p></td></tr>"#, parent));
        }}
        for e in &infos {{
            let href = if e.is_dir {{
                if eff_path=="/" {{ format!("/{{}}/?raw=true", e.name) }} else {{ format!("{{}}{{}}/?raw=true", eff_path, e.name) }}
            }} else {{
                if eff_path=="/" {{ format!("/{{}}", e.name) }} else {{ format!("{{}}{{}}", eff_path, e.name) }}
            }};
            let size_disp = if e.is_dir {{ "".to_string() }} else {{ fmt_size(e.size, &cfg.size_display) }};
            html.push_str(&format!(r#"<tr class="entry-type-{{}}"><td><p><a class="{{}}" href="{{}}">{{}}{{}}</a></p></td><td class="size-cell">{{}}</td><td class="date-cell"><span>{{}} </span><span class="history">{{}}</span></td></tr>"#,
                if e.is_dir {{"directory"}} else {{"file"}}, if e.is_dir {{"directory"}} else {{"file"}}, href, e.name, if e.is_dir {{"/"}} else {{""}}, size_disp, e.mtime_str, relative_time(e.mtime)
            ));
        }}
        html.push_str("</tbody></table></body></html>");
        let body = html.into_bytes();
        let mut hdr = vec![
            ("Content-Type".to_string(), "text/html; charset=utf-8".to_string()),
            ("Content-Length".to_string(), body.len().to_string()),
            ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
        ];
        let resp = HttpResponse{{status:200, reason:"OK".to_string(), headers: hdr, body}};
        write_resp(stream, cfg, resp, method, req_headers, query_flat)?;
        return Ok(());
    }}

    let host_display = if let Some(ref t) = cfg.title {{ t.clone() }} else {{ req_headers.get("host").cloned().unwrap_or_else(|| format!("127.0.0.1:{{}}", cfg.port)) }};
