fn parse_auth(s: &str) -> Option<AuthEntry> {{
    if s.is_empty() {{ return None; }}
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len()==1 {{
        Some(AuthEntry{{username: parts[0].to_string(), hash_type: None, hash: "".to_string()}})
    }} else if parts.len()==2 {{
        Some(AuthEntry{{username: parts[0].to_string(), hash_type: None, hash: parts[1].to_string()}})
    }} else if parts.len()==3 {{
        if parts[1]!="sha256" && parts[1]!="sha512" {{ return None; }}
        Some(AuthEntry{{username: parts[0].to_string(), hash_type: Some(parts[1].to_string()), hash: parts[2].to_string()}})
    }} else {{
        if parts[1]=="sha256" || parts[1]=="sha512" {{
            Some(AuthEntry{{username: parts[0].to_string(), hash_type: Some(parts[1].to_string()), hash: parts[2..].join(":")}})
        }} else {{
            Some(AuthEntry{{username: parts[0].to_string(), hash_type: None, hash: parts[1..].join(":")}})
        }}
    }}
}}

fn check_auth(entry: &AuthEntry, pw: &str) -> bool {{
    match &entry.hash_type {{
        None => entry.hash == pw,
        Some(t) => {{
            if t=="sha256" {{
                let mut h = Sha256::new();
                h.update(pw.as_bytes());
                format!("{{:x}}", h.finalize()) == entry.hash.to_lowercase()
            }} else if t=="sha512" {{
                let mut h = Sha512::new();
                h.update(pw.as_bytes());
                format!("{{:x}}", h.finalize()) == entry.hash.to_lowercase()
            }} else {{ false }}
        }}
    }}
}}

