fn build_breadcrumb(cfg: &Config, eff: &str, host: &str) -> String {{
    let rp = cfg.route_prefix.clone().unwrap_or_default();
    let trimmed = eff.trim_matches('/');
    if trimmed.is_empty() {{ return format!(r#"<span><bdi>{{}}</bdi></span>/"#, host); }}
    let parts: Vec<&str> = trimmed.split('/').collect();
    let mut out = format!(r#"<a href="{{}}/"><bdi>{{}}</bdi></a>/"#, rp, host);
    for (i, part) in parts.iter().enumerate() {{
        let is_last = i==parts.len()-1;
        let up = format!("/{{}}/", parts[..=i].join("/"));
        let href = format!("{{}}{{}}", rp, up);
        if is_last {{
            out.push_str(&format!(r#"<span><bdi>{{}}</bdi></span>/"#, part));
        }} else {{
            out.push_str(&format!(r#"<a href="{{}}"><bdi>{{}}</bdi></a>/"#, href, part));
        }}
    }}
    out
}}

fn relative_time(mt: SystemTime) -> String {{
    let now = SystemTime::now();
    let diff = now.duration_since(mt).unwrap_or(Duration::new(0,0)).as_secs();
    if diff < 10 {{ "now".to_string() }}
    else if diff < 60 {{ format!("{{}} seconds ago", diff) }}
    else if diff < 120 {{ "a minute ago".to_string() }}
    else if diff < 3600 {{ format!("{{}} minutes ago", diff/60) }}
    else if diff < 7200 {{ "an hour ago".to_string() }}
    else if diff < 86400 {{ format!("{{}} hours ago", diff/3600) }}
    else if diff < 172800 {{ "a day ago".to_string() }}
    else {{ format!("{{}} days ago", diff/86400) }}
}}

fn render_md(md: &str) -> String {{
    let mut out = String::new();
    let mut in_p = false;
    for line in md.lines() {{
        let t = line.trim();
        if t.is_empty() {{ if in_p {{ out.push_str("</p>"); in_p=false; }} continue; }}
        if t.starts_with("# ") {{ if in_p {{ out.push_str("</p>"); in_p=false; }} out.push_str(&format!("<h1>{{}}</h1>", html_escape(t[2..].trim()))); }}
        else if t.starts_with("## ") {{ if in_p {{ out.push_str("</p>"); in_p=false; }} out.push_str(&format!("<h2>{{}}</h2>", html_escape(t[3..].trim()))); }}
        else if t.starts_with("### ") {{ if in_p {{ out.push_str("</p>"); in_p=false; }} out.push_str(&format!("<h3>{{}}</h3>", html_escape(t[4..].trim()))); }}
        else {{
            if !in_p {{ out.push_str("<p>"); in_p=true; }} else {{ out.push_str(" "); }}
            out.push_str(&html_escape(t));
        }}
    }}
    if in_p {{ out.push_str("</p>"); }}
    if out.is_empty() {{ out = format!("<p>{{}}</p>", html_escape(md)); }}
    out
}}

fn html_escape(s: &str) -> String {{
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;")
}}

fn generate_qr(url: &str) -> String {{
    let mut modules = vec![vec![false;27];27];
    for (fx,fy) in [(0,0),(0,20),(20,0)] {{
        for y in 0..7 {{
            for x in 0..7 {{
                if x==0 || x==6 || y==0 || y==6 || (x>=2 && x<=4 && y>=2 && y<=4) {{
                    modules[fy+y][fx+x]=true;
                }}
            }}
        }}
    }}
    let hash = {{
        let mut h = Sha256::new();
        h.update(url.as_bytes());
        h.finalize()
    }};
    let mut bits = Vec::new();
    for b in hash {{ for i in 0..8 {{ bits.push((b>>i)&1==1); }} }}
    let mut idx=0;
    for y in 0..27 {{
        for x in 0..27 {{
            if (x<8 && y<8) || (x>=19 && y<8) || (x<8 && y>=19) {{ continue; }}
            if x==6 || y==6 {{ continue; }}
            if bits[idx % bits.len()] {{ modules[y][x]=true; }}
            idx+=1;
        }}
    }}
    let mut d = String::new();
    for y in 0..27 {{ for x in 0..27 {{ if modules[y][x] {{ d.push_str(&format!("M{{}},{{}}h1v1h-1", x, y)); }} }} }}
    format!(r#"<svg viewBox="0 0 27 27" xmlns="http://www.w3.org/2000/svg"><rect width="27px" height="27px" fill="#ffffff"/><path d="{{}}"/></svg>"#, d)
}}

fn serve_tar(stream: &mut TcpStream, cfg: &Config, dir_path: &Path, gz: bool, method: &str, headers: &HashMap<String,String>, query: &HashMap<String,String>, client_ip: &str, raw_path: &str) -> std::io::Result<()> {{
    let mut files: Vec<PathBuf> = Vec::new();
    fn collect(dir: &Path, cfg: &Config, out: &mut Vec<PathBuf>) {{
        if let Ok(rd) = std::fs::read_dir(dir) {{
            for ent in rd.flatten() {{
                let p = ent.path();
                if !cfg.hidden {{
                    if let Some(name) = p.file_name().and_then(|n| n.to_str()) {{ if name.starts_with('.') {{ continue; }} }}
                }}
                if cfg.no_symlinks {{ if let Ok(m) = std::fs::symlink_metadata(&p) {{ if m.file_type().is_symlink() {{ continue; }} }} }}
                if p.is_dir() {{ collect(&p, cfg, out); }} else if p.is_file() {{ out.push(p); }}
            }}
        }}
    }}
    collect(dir_path, cfg, &mut files);
    let mut tar_data = Vec::new();
    for fp in &files {{
        let rel = fp.strip_prefix(dir_path).unwrap_or(fp).to_string_lossy().to_string();
        if let Ok(meta) = std::fs::metadata(fp) {{
            let size = meta.len();
            let mut hdr = [0u8;512];
            let name_b = rel.as_bytes();
            let nl = name_b.len().min(100);
            hdr[0..nl].copy_from_slice(&name_b[..nl]);
            let mode_s = format!("{{:07o}}\\0", 0o644);
            hdr[100..108].copy_from_slice(mode_s.as_bytes());
            hdr[108..116].copy_from_slice(b"0000000\\0");
            hdr[116..124].copy_from_slice(b"0000000\\0");
            let size_s = format!("{{:011o}}\\0", size);
            hdr[124..136].copy_from_slice(size_s.as_bytes());
            let mtime = meta.modified().unwrap_or(SystemTime::now()).duration_since(UNIX_EPOCH).unwrap_or(Duration::new(0,0)).as_secs();
            let mtime_s = format!("{{:011o}}\\0", mtime);
            hdr[136..148].copy_from_slice(mtime_s.as_bytes());
            for i in 148..156 {{ hdr[i]=b' '; }}
            hdr[156]=b'0';
            hdr[257..263].copy_from_slice(b"ustar\\0");
            hdr[263..265].copy_from_slice(b"00");
            let checksum: u32 = hdr.iter().map(|&b| b as u32).sum();
            let cs = format!("{{:06o}}\\0 ", checksum);
            hdr[148..156].copy_from_slice(cs.as_bytes());
            tar_data.extend_from_slice(&hdr);
            if let Ok(mut f) = File::open(fp) {{
                let mut buf = Vec::new();
                f.read_to_end(&mut buf).ok();
                tar_data.extend_from_slice(&buf);
                let pad = (512 - (buf.len()%512))%512;
                tar_data.extend(vec![0u8; pad]);
            }}
        }}
    }}
    tar_data.extend(vec![0u8;1024]);
    let (final_data, ctype, fname) = if gz {{
        let mut enc = GzEncoder::new(Vec::new(), FlateCompression::default());
        enc.write_all(&tar_data).ok();
        let d = enc.finish().unwrap_or(tar_data);
        (d, "application/gzip".to_string(), format!("{{}}.tar.gz", dir_path.file_name().and_then(|n| n.to_str()).unwrap_or("archive")))
    }} else {{
        (tar_data, "application/x-tar".to_string(), format!("{{}}.tar", dir_path.file_name().and_then(|n| n.to_str()).unwrap_or("archive")))
    }};
    let mut hdr = vec![
        ("Content-Type".to_string(), ctype),
        ("Content-Length".to_string(), final_data.len().to_string()),
        ("Content-Disposition".to_string(), format!("attachment; filename=\\"{}\\"", fname)),
        ("Content-Transfer-Encoding".to_string(), "binary".to_string()),
        ("Date".to_string(), Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()),
    ];
    let resp = HttpResponse{{status:200, reason:"OK".to_string(), headers: hdr, body: final_data}};
    write_resp(stream, cfg, resp, method, headers, query)?;
    Ok(())
}}

fn serve_zip(stream: &mut TcpStream, cfg: &Config, dir_path: &Path, method: &str, headers: &HashMap<String,String>, query: &HashMap<String,String>, client_ip: &str, raw_path: &str) -> std::io::Result<()> {{
    let mut files: Vec<PathBuf> = Vec::new();
    fn collect(dir: &Path, cfg: &Config, out: &mut Vec<PathBuf>) {{
        if let Ok(rd) = std::fs::read_dir(dir) {{
            for ent in rd.flatten() {{
                let p = ent.path();
                if !cfg.hidden {{
                    if let Some(name) = p.file_name().and_then(|n| n.to_str()) {{ if name.starts_with('.') {{ continue; }} }}
                }}
                if cfg.no_symlinks {{ if let Ok(m) = std::fs::symlink_metadata(&p) {{ if m.file_type().is_symlink() {{ continue; }} }} }}
                if p.is_dir() {{ collect(&p, cfg, out); }} else if p.is_file() {{ out.push(p); }}
            }}
        }}
    }}
    collect(dir_path, cfg, &mut files);
    let mut zip_data = Vec::new();
    let mut central = Vec::new();
    let mut offset: u32 = 0;
    for fp in &files {{
        let rel = fp.strip_prefix(dir_path).unwrap_or(fp).to_string_lossy().to_string();
        let rel_b = rel.as_bytes();
        let file_data = std::fs::read(fp).unwrap_or_default();
        let crc = crc32(&file_data);
        let f_len = rel_b.len() as u16;
        let comp = file_data.clone();
