    def resolve_fs(self, url_path):
        trimmed=url_path.lstrip("/")
        parts=[]
        for comp in pathlib.PurePosixPath(trimmed).parts:
            if comp==".":
                continue
            elif comp=="..":
                if parts:
                    parts.pop()
            else:
                parts.append(comp)
        p=self.server.config["serve_path"]
        for part in parts:
            p=p/part
        return p

    def calc_dir_size(self, path):
        total=0
        if not path.exists():
            return 0
        for root, dirs, files in os.walk(path):
            if not self.server.config.get("hidden"):
                dirs[:]=[d for d in dirs if not d.startswith(".")]
                files=[f for f in files if not f.startswith(".")]
            if self.server.config.get("no_symlinks"):
                dirs[:]=[d for d in dirs if not os.path.islink(os.path.join(root,d))]
                files=[f for f in files if not os.path.islink(os.path.join(root,f))]
            for f in files:
                fp=os.path.join(root,f)
                try:
                    total+=os.path.getsize(fp)
                except:
                    pass
        return total

    def gen_rename(self, dir_path, original_name):
        p=pathlib.Path(original_name)
        stem=p.stem
        suffix=p.suffix
        c=1
        while True:
            new_name=f"{stem}-{c}{suffix}"
            new_path=dir_path / new_name
            if not new_path.exists():
                return new_path
            c+=1

    def check_media_type(self, filename, mt):
        ext=pathlib.Path(filename).suffix.lower()
        if mt=="image":
            return ext in [".jpg",".jpeg",".png",".gif",".bmp",".webp",".svg",".ico"]
        elif mt=="audio":
            return ext in [".mp3",".wav",".ogg",".flac",".aac",".m4a"]
        elif mt=="video":
            return ext in [".mp4",".avi",".mkv",".mov",".webm",".m4v"]
        return True

    def parse_multipart(self, data, boundary):
        b_marker = f"--{boundary}".encode()
        b_sep = f"\r\n--{boundary}".encode()
        parts=[]
        pos=0
        while pos < len(data):
            idx=data.find(b_marker, pos)
            if idx==-1:
                break
            start=idx+len(b_marker)
            if data[start:start+2]==b"\r\n":
                start+=2
            h_end=data.find(b"\r\n\r\n", start)
            if h_end==-1:
                break
            header_bytes=data[start:h_end]
            body_start=h_end+4
            next_idx=data.find(b_sep, body_start)
            end_marker=f"--{boundary}--".encode()
            end_idx=data.find(end_marker, body_start)
            if next_idx!=-1 and (end_idx==-1 or next_idx < end_idx):
                body_end=next_idx
                if data[body_end-2:body_end]==b"\r\n":
                    body_end-=2
                h_str=header_bytes.decode(errors="ignore")
                hdrs={}
                for line in h_str.split("\r\n"):
                    if ":" in line:
                        k,v=line.split(":",1)
                        hdrs[k.strip().lower()]=v.strip()
                parts.append({"headers":hdrs,"body":data[body_start:body_end]})
                pos=next_idx
                continue
            elif end_idx!=-1:
                body_end=end_idx
                if body_end>=2 and data[body_end-2:body_end]==b"\r\n":
                    body_end-=2
                h_str=header_bytes.decode(errors="ignore")
                hdrs={}
                for line in h_str.split("\r\n"):
                    if ":" in line:
                        k,v=line.split(":",1)
                        hdrs[k.strip().lower()]=v.strip()
                parts.append({"headers":hdrs,"body":data[body_start:body_end]})
                break
            else:
                break
        return parts

    def serve_file(self, file_path, method, raw_path_full, query_flat):
        try:
            st = file_path.stat()
        except:
            self.send_404(str(file_path), raw_path_full, query_flat)
            return
        size = st.st_size
        mtime = st.st_mtime
        last_mod = email.utils.formatdate(mtime, usegmt=True)
        etag = f'"{int(mtime):x}:{size:x}:{hash(str(file_path)) & 0xFFFFFFFF:x}"'
        if_none = self.headers.get("If-None-Match")
        if if_none and (if_none.strip()==etag or if_none.strip()==etag.strip('"')):
            self.send_response(304)
            self.send_header("Content-Disposition", f'inline; filename="{file_path.name}"')
            self.send_header("Accept-Ranges","bytes")
            self.send_header("Last-Modified", last_mod)
            self.send_header("ETag", etag)
            self.send_header("Content-Type", get_mime_type(str(file_path)))
            self.send_header("Date", email.utils.formatdate(None, False, True))
            for k,v in self.server.config.get("custom_headers", []):
                self.send_header(k,v)
            self.end_headers()
            if self.server.config.get("verbose"):
                now = datetime.datetime.now().astimezone().strftime("%a, %d %b %Y %H:%M:%S %z")
                sys.stderr.write(f'{now} [INFO] {self.client_address[0]} "GET {raw_path_full} HTTP/1.1" 304 0 "-" "-" 0.000000\n')
            return

        range_header = self.headers.get("Range")
        start=0
        end=size-1
        partial=False
        if range_header and range_header.startswith("bytes="):
            spec=range_header[6:]
            if "-" in spec:
                s,e=spec.split("-",1)
                try:
                    if s=="" and e!="":
                        suffix=int(e)
                        if suffix<=size:
                            start=size-suffix
                            end=size-1
                            partial=True
                    elif s!="" and e=="":
                        start=int(s)
                        end=size-1
                        partial=True
                    elif s!="" and e!="":
                        start=int(s)
                        end=int(e)
                        if start<size:
                            if end>=size:
                                end=size-1
                            partial=True
                except:
                    pass
        clen = end-start+1 if partial else size
        try:
            f=open(file_path,"rb")
            if partial:
                f.seek(start)
                data=f.read(clen)
            else:
                data=f.read() if method!="HEAD" else b""
            f.close()
        except Exception as e:
            self.send_response(500)
            self.end_headers()
            return
        mime=get_mime_type(str(file_path))
        disp="attachment" if file_path.name.startswith(".") or mime=="application/octet-stream" else "inline"
        if mime.startswith("text/") or "html" in mime:
            disp="inline"
        self.send_response(206 if partial else 200)
        self.send_header("Content-Length", str(clen))
        self.send_header("Content-Type", mime)
        self.send_header("Content-Disposition", f'{disp}; filename="{file_path.name}"')
        self.send_header("Accept-Ranges","bytes")
        self.send_header("Last-Modified", last_mod)
        self.send_header("ETag", etag)
        self.send_header("Date", email.utils.formatdate(None, False, True))
        if partial:
            self.send_header("Content-Range", f"bytes {start}-{end}/{size}")
        for k,v in self.server.config.get("custom_headers", []):
            if k.lower() not in ["content-length","content-type","content-disposition","accept-ranges","last-modified","etag","date","content-range","content-encoding"]:
                self.send_header(k,v)
        self.end_headers()
        if method!="HEAD":
            self.wfile.write(data)
        if self.server.config.get("verbose"):
            now=datetime.datetime.now().astimezone().strftime("%a, %d %b %Y %H:%M:%S %z")
            sys.stderr.write(f'{now} [INFO] {self.client_address[0]} "{method} {raw_path_full} HTTP/1.1" {206 if partial else 200} {clen} "-" "-" 0.000000\n')

    def serve_directory(self, fs_path, effective_path, raw_path_full, query_flat, method):
        sort_method = query_flat.get("sort", self.server.config.get("default_sorting_method","name"))
        sort_order = query_flat.get("order", self.server.config.get("default_sorting_order","desc"))
        entries=[]
        for entry in os.scandir(fs_path):
            name=entry.name
            if not self.server.config.get("hidden") and name.startswith("."):
                continue
            if self.server.config.get("no_symlinks") and entry.is_symlink():
                continue
            is_dir = entry.is_dir()
            is_symlink = entry.is_symlink()
            symlink_target = None
            if is_symlink and self.server.config.get("show_symlink_info"):
                try:
                    symlink_target=os.readlink(entry.path)
                except:
                    pass
            try:
                st=entry.stat(follow_symlinks=True)
                sz=0 if is_dir else st.st_size
                mt=st.st_mtime
            except:
                sz=0
                mt=time.time()
            entries.append({"name":name,"is_dir":is_dir,"is_symlink":is_symlink,"symlink_target":symlink_target,"size":sz,"mtime":mt})

        def keyfunc(e):
            if sort_method=="size":
                return e["size"]
            elif sort_method=="date":
                return e["mtime"]
            else:
                return e["name"].lower()
        reverse = (sort_order=="desc")
        if self.server.config.get("dirs_first"):
            entries.sort(key=keyfunc, reverse=reverse)
            dirs=[e for e in entries if e["is_dir"]]
            files=[e for e in entries if not e["is_dir"]]
            entries=dirs+files
        else:
            entries.sort(key=keyfunc, reverse=reverse)

        is_raw = query_flat.get("raw")=="true"
        if is_raw:
            html_out='<!DOCTYPE html><html><body><table><thead><th class="name">Name</th><th class="size">Size</th><th class="date">Last modification</th></thead><tbody>'
            if effective_path!="/":
                trimmed=effective_path.rstrip("/")
                parent="/".join(trimmed.split("/")[:-1])
                if parent=="":
                    parent="/"
                else:
                    if not parent.startswith("/"):
                        parent="/"+parent
                    if not parent.endswith("/"):
                        parent+="/"
                html_out+=f'<tr><td colspan="3"><p><a class="root" href="{parent}?raw=true">..</a></p></td></tr>'
            for e in entries:
                if e["is_dir"]:
                    href=f"/{e['name']}/?raw=true" if effective_path=="/" else f"{effective_path}{e['name']}/?raw=true"
                    html_out+=f'<tr class="entry-type-directory"><td><p><a class="directory" href="{href}">{e["name"]}/</a></p></td><td class="size-cell"></td><td class="date-cell"><span>{datetime.datetime.fromtimestamp(e["mtime"]).strftime("%Y-%m-%d %H:%M:%S %z")} </span><span class="history">{relative_time(e["mtime"])}</span></td></tr>'
                else:
                    href=f"/{e['name']}" if effective_path=="/" else f"{effective_path}{e['name']}"
                    ext=self.server.config.get("file_external_url")
                    if ext:
                        href=ext.rstrip("/")+href
                    html_out+=f'<tr class="entry-type-file"><td><p><a class="file" href="{href}">{e["name"]}</a></p></td><td class="size-cell">{format_size(e["size"], self.server.config.get("size_display","human"))}</td><td class="date-cell"><span>{datetime.datetime.fromtimestamp(e["mtime"]).strftime("%Y-%m-%d %H:%M:%S %z")} </span><span class="history">{relative_time(e["mtime"])}</span></td></tr>'
            html_out+='</tbody></table></body></html>'
            body=html_out.encode()
            self.send_response(200)
            self.send_header("Content-Type","text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            if method!="HEAD":
                self.wfile.write(body)
            return

        host_display = self.server.config.get("title") or self.headers.get("Host") or f"127.0.0.1:{self.server.config.get('port',8080)}"
        rp = self.server.config.get("route_prefix") or ""
        # breadcrumb
        trimmed=effective_path.strip("/")
        if not trimmed:
            breadcrumb=f'<span><bdi>{escape_html(host_display)}</bdi></span>/'
        else:
            parts=trimmed.split("/")
            breadcrumb=f'<a href="{rp}/"><bdi>{escape_html(host_display)}</bdi></a>/'
            for i,part in enumerate(parts):
                is_last=i==len(parts)-1
                up="/"+"/".join(parts[:i+1])+"/"
                href=rp+up
                if is_last:
                    breadcrumb+=f'<span><bdi>{escape_html(part)}</bdi></span>/'
                else:
                    breadcrumb+=f'<a href="{href}"><bdi>{escape_html(part)}</bdi></a>/'

        # toolbar download
        toolbar_download=""
        if self.server.config.get("enable_tar") or self.server.config.get("enable_tar_gz") or self.server.config.get("enable_zip"):
            toolbar_download='<div class="download">'
            if self.server.config.get("enable_tar_gz"):
                toolbar_download+='<a href="?download=tar_gz">Download .tar.gz</a>'
            if self.server.config.get("enable_tar"):
                toolbar_download+='<a href="?download=tar">Download .tar</a>'
            if self.server.config.get("enable_zip"):
                toolbar_download+='<a href="?download=zip">Download .zip</a>'
            toolbar_download+='</div>'

        upload_enabled=self.server.config.get("upload_enabled")
        mkdir_enabled=self.server.config.get("mkdir")
        toolbar_box=""
        if upload_enabled or mkdir_enabled:
            toolbar_box='<div class="toolbar_box_group">'
            if upload_enabled:
                up_path=effective_path
                action=f"{rp}/upload?path={up_path}"
                toolbar_box+=f'<div class="toolbar_box"><form id="file_submit" action="{action}" method="POST" enctype="multipart/form-data"><p>Select a file to upload or drag it anywhere into the window</p><div><input id="file-input" type="file" name="file_to_upload" required="" multiple></input><button type="submit">Upload file</button></div></form></div>'
            if mkdir_enabled:
                up_path=effective_path
                action=f"{rp}/upload?path={up_path}"
                toolbar_box+=f'<div class="toolbar_box"><form id="mkdir" action="{action}" method="POST" enctype="multipart/form-data"><p>Specify a directory name to create</p><div class="toolbar_box"><input type="text" name="mkdir" required="" placeholder="Directory name"></input><button type="submit">Create directory</button></div></form></div>'
            toolbar_box+='</div>'
        else:
            toolbar_box='<div class="toolbar_box_group"></div>'

        toolbar=f'<div class="toolbar">{toolbar_download}{toolbar_box}</div>'

        rows=""
        if effective_path!="/":
            trimmed=effective_path.rstrip("/")
            parent="/".join(trimmed.split("/")[:-1])
            if parent=="":
                parent="/"
            else:
                if not parent.startswith("/"):
                    parent="/"+parent
                if not parent.endswith("/"):
                    parent+="/"
            parent_href=rp+parent
            sq=""
            if "sort" in query_flat or "order" in query_flat:
                parts=[]
                if "sort" in query_flat:
                    parts.append(f"sort={query_flat['sort']}")
                if "order" in query_flat:
                    parts.append(f"order={query_flat['order']}")
                sq="?"+"&".join(parts)
                parent_href+=sq
            rows+=f'<tr><td colspan="3"><p><span class="root-chevron">◂</span><a class="root" href="{parent_href}">Parent directory</a></p></td></tr>'

        for e in entries:
            if e["is_dir"]:
                href=f"/{e['name']}/" if effective_path=="/" else f"{effective_path}{e['name']}/"
            else:
                href=f"/{e['name']}" if effective_path=="/" else f"{effective_path}{e['name']}"
                ext=self.server.config.get("file_external_url")
                if ext and not e["is_dir"]:
                    href=ext.rstrip("/")+href
            if rp and not (self.server.config.get("file_external_url") and not e["is_dir"]):
                href=rp+href
            if e["is_dir"]:
                if "sort" in query_flat or "order" in query_flat:
                    parts=[]
                    if "sort" in query_flat:
                        parts.append(f"sort={query_flat['sort']}")
                    if "order" in query_flat:
                        parts.append(f"order={query_flat['order']}")
                    href+= "?" + "&".join(parts)

            size_disp="" if e["is_dir"] else format_size(e["size"], self.server.config.get("size_display","human"))
            mtime_str=datetime.datetime.fromtimestamp(e["mtime"]).astimezone().strftime("%Y-%m-%d %H:%M:%S %:z")
            rel=relative_time(e["mtime"])

            if e["is_symlink"] and self.server.config.get("show_symlink_info"):
                tgt=e["symlink_target"] or ""
                rows+=f'<tr class="entry-type-file"><td><p><a class="symlink" href="{href}">{escape_html(e["name"])}<span class="symlink-symbol"></span><a class="file">{escape_html(tgt)}</a></a><span class="mobile-info size"><span class=""><span class="chevron">▾</span><a href="?sort=size&amp;order=asc" title="Sort by size in ascending order">{size_disp} </a></span></span><span class="mobile-info history"><span class=""><span class="chevron">▾</span><a href="?sort=date&amp;order=asc" title="Sort by date in ascending order">{rel}</a></span></span></p></td><td class="size-cell">{size_disp}</td><td class="date-cell"><span>{mtime_str} </span><span class="history">{rel}</span></td>'
            else:
                if e["is_dir"]:
                    rows+=f'<tr class="entry-type-directory"><td><p><a class="directory" href="{href}">{escape_html(e["name"])}/</a></p></td><td class="size-cell"></td><td class="date-cell"><span>{mtime_str} </span><span class="history">{rel}</span></td>'
                else:
                    rows+=f'<tr class="entry-type-file"><td><p><a class="file" href="{href}">{escape_html(e["name"])}</a><span class="mobile-info size"><span class=""><span class="chevron">▾</span><a href="?sort=size&amp;order=asc" title="Sort by size in ascending order">{size_disp} </a></span></span><span class="mobile-info history"><span class=""><span class="chevron">▾</span><a href="?sort=date&amp;order=asc" title="Sort by date in ascending order">{rel}</a></span></span></p></td><td class="size-cell">{size_disp}</td><td class="date-cell"><span>{mtime_str} </span><span class="history">{rel}</span></td>'

            if self.server.config.get("rm_enabled"):
                rm_path=f"/{e['name']}" if effective_path=="/" else f"{effective_path}{e['name']}"
                rm_action=f"{rp}/rm?path={rm_path}"
                rows+=f'<td class="actions-cell"><form class="rm_form" action="{rm_action}" method="POST"><button type="submit" title="Delete">✗</button></form></td>'
            rows+='</tr>'

        wget_footer=""
        if self.server.config.get("show_wget_footer"):
            host=self.headers.get("Host") or f"127.0.0.1:{self.server.config.get('port',8080)}"
            cur=effective_path
            url_wget=f"http://{host}{rp}{cur}?raw=true"
            wget_footer=f'<div class="downloadDirectory"><p>Download folder:</p><a class="cmd" title="Click to copy!" style="cursor: pointer;" onclick="navigator.clipboard.writeText(&quot;wget -rcnp -R \'index.html*\' -nH -P \'{host_display}\' \'{url_wget}\'&quot;)">wget -rcnp -R \'index.html*\' -nH -P \'{host_display}\' \'{url_wget}\'</a></div>'

        version_footer="" if self.server.config.get("hide_version_footer") else f'<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/{VERSION}</div>'

        if self.server.config.get("hide_theme_selector"):
            if self.server.config.get("qrcode"):
                cur_url=f"http://{self.headers.get('Host','127.0.0.1')}{rp}{effective_path}"
                qr=generate_qr(cur_url)
                nav=f'<nav><div><p>QR code</p><div class="qrcode" id="qrcode" title="{cur_url}">{qr}</div></div></nav>'
            else:
                nav='<nav></nav>'
        else:
            qr_part=""
            if self.server.config.get("qrcode"):
                cur_url=f"http://{self.headers.get('Host','127.0.0.1')}{rp}{effective_path}"
                qr=generate_qr(cur_url)
                qr_part=f'<div><p>QR code</p><div class="qrcode" id="qrcode" title="{cur_url}">{qr}</div></div>'
            nav=f'<nav>{qr_part}<div><p>Change theme...</p><ul class="theme"><li data-theme="default"><a href="javascript:updateColorScheme(&quot;default&quot;)" title="Switch to Default (light/dark) theme">Default (light/dark)</a></li><li data-theme="squirrel"><a href="javascript:updateColorScheme(&quot;squirrel&quot;)" title="Switch to Squirrel (light) theme">Squirrel (light)</a></li><li data-theme="archlinux"><a href="javascript:updateColorScheme(&quot;archlinux&quot;)" title="Switch to Arch Linux (dark) theme">Arch Linux (dark)</a></li><li data-theme="zenburn"><a href="javascript:updateColorScheme(&quot;zenburn&quot;)" title="Switch to Zenburn (dark) theme">Zenburn (dark)</a></li><li data-theme="monokai"><a href="javascript:updateColorScheme(&quot;monokai&quot;)" title="Switch to Monokai (dark) theme">Monokai (dark)</a></li></ul></div></nav>'

        readme_html=""
        if self.server.config.get("readme"):
            readme_path=fs_path / "README.md"
            if readme_path.is_file():
                try:
                    content=readme_path.read_text()
                    rendered=render_md(content)
                    readme_html=f'<div id="readme"><h3 id="readme-filename">README.md</h3><div id="readme-contents">{rendered}</div></div>'
                except:
                    pass

        has_sort="sort" in query_flat
        def order_link(cm):
            if has_sort and query_flat.get("sort")==cm:
                return "desc" if query_flat.get("order","desc")=="asc" else "asc"
            else:
                return "asc"
        def chev(cm):
            if has_sort and query_flat.get("sort")==cm:
                return "▴" if query_flat.get("order")=="asc" else "▾"
            else:
                return "▾"
        def active(cm):
            return "active" if has_sort and query_flat.get("sort")==cm else ""

        table_header=f'<table><thead><th class="name"><span class="{active("name")}"><span class="chevron">{chev("name")}</span><a href="?sort=name&amp;order={order_link("name")}" title="Sort by name in {"ascending" if order_link("name")=="asc" else "descending"} order">Name</a></span></th><th class="size"><span class="{active("size")}"><span class="chevron">{chev("size")}</span><a href="?sort=size&amp;order={order_link("size")}" title="Sort by size in {"ascending" if order_link("size")=="asc" else "descending"} order">Size</a></span></th><th class="date"><span class="{active("date")}"><span class="chevron">{chev("date")}</span><a href="?sort=date&amp;order={order_link("date")}" title="Sort by date in {"ascending" if order_link("date")=="asc" else "descending"} order">Last modification</a></span></th>'
        if self.server.config.get("rm_enabled"):
            table_header+='<th class="actions"><span>Actions</span></th>'
        table_header+='</thead><tbody>'

        page_title=host_display if effective_path=="/" else f"{host_display}{effective_path.rstrip('/')}"

        color_script="""<script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {
                        if (name && name != "default") {
                            localStorage.setItem('theme', name);
                            document.body.setAttribute("data-theme", name)
                        } else {
                            localStorage.removeItem('theme');
                            document.body.removeAttribute("data-theme")
                        }
                    }

                    // read theme from local storage and apply it to body
                    function loadColorScheme() {
                        var name = localStorage.getItem('theme');
                        updateColorScheme(name);
                    }

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script>"""
        dir_script=f"""<script>const API_ROUTE = '{rp}/__miniserve_internal/api';
                    let dirSizeCache = {{}};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {{
                        return fetch(API_ROUTE, {{
                            headers: {{
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            }},
                            method: 'POST',
                            body: JSON.stringify({{
                                DirSize: dir
                            }})
                        }}).then(resp => resp.ok ? resp.text() : "~")
                    }}

                    function updateSizeCells() {{
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {{
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {{
                                cell.dataset.size = dirSizeCache[target];
                            }} else {{
                                fetchDirSize(target).then(dir_size => {{
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                }})
                                .catch(error => console.error("Error fetching dir size:", error));
                            }}
                        }})
                    }}
                    setInterval(updateSizeCells, 1000);
                </script>"""

        web_conc=self.server.config.get("web_upload_concurrency",0)
        if upload_enabled:
            upload_script=f"""<script>const CONCURRENCY = {web_conc};
                    window.onload = function() {{
                        const form = document.querySelector('#file_submit');
                        const uploadArea = document.querySelector('#upload_area');
                        const uploadTitle = document.querySelector('#upload_title');
                        const uploadActionText = document.querySelector('#upload_action_text');
                        const uploadCancelButton = document.querySelector('#upload_cancel');
                        const uploadList = document.querySelector('#upload_file_list');
                        const fileUploadItemTemplate = document.querySelector('#upload_file_item');
                        const uploadWidgetToggle = document.querySelector('#upload-toggle');
                        const dropContainer = document.querySelector('#drop-container');
                        const dragForm = document.querySelector('.drag-form');
                        const fileInput = document.querySelector('#file-input');
                    }}
                    </script>"""
        else:
            upload_script=""

        html_doc=f'<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{rp}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{rp}/__miniserve_internal/style.css"><title>{escape_html(page_title)}</title>{color_script}{dir_script}{upload_script}</head><body id="drop-container"><div class="toolbar_box_group"></div>{nav}<div class="container"><span id="top"></span><h1 class="title" dir="ltr">{breadcrumb}</h1>{toolbar}{table_header}{rows}</tbody></table>{readme_html}<a class="back" href="#top">⇪</a><div class="footer">{wget_footer}{version_footer}</div></div><div class="upload_area" id="upload_area"><template id="upload_file_item"><li class="upload_file_item"><div class="upload_file_container"><div class="upload_file_text"><span class="file_upload_percent"></span> - <span class="file_size"></span> - <span class="file_name"></span></div><button class="file_cancel_upload">✖</button></div><div class="file_progress_bar"></div></li></template><div class="upload_container"><div class="upload_header"><h4 style="margin:0px" id="upload_title"></h4><svg id="upload-toggle" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="size-6"><path stroke-linecap="round" stroke-linejoin="round" d="m4.5 15.75 7.5-7.5 7.5 7.5"></path></svg></div><div class="upload_action"><p id="upload_action_text">Starting upload...</p><button class="upload_cancel" id="upload_cancel">CANCEL</button></div><div class="upload_files"><ul class="upload_file_list" id="upload_file_list"></ul></div></div></div></body></html>'

        body=html_doc.encode()
        if self.server.config.get("compress_response"):
            accept=self.headers.get("Accept-Encoding","")
            if "gzip" in accept:
                out=io.BytesIO()
                with gzip.GzipFile(fileobj=out, mode="wb") as f:
                    f.write(body)
                gz_body=out.getvalue()
                self.send_response(200)
                self.send_header("Content-Type","text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(gz_body)))
                self.send_header("Content-Encoding","gzip")
                self.send_header("Vary","accept-encoding")
                self.send_header("Date", email.utils.formatdate(None, False, True))
                for k,v in self.server.config.get("custom_headers", []):
                    self.send_header(k,v)
                self.end_headers()
                if method!="HEAD":
                    self.wfile.write(gz_body)
                if self.server.config.get("verbose"):
                    now=datetime.datetime.now().astimezone().strftime("%a, %d %b %Y %H:%M:%S %z")
                    sys.stderr.write(f'{now} [INFO] {self.client_address[0]} "{method} {raw_path_full} HTTP/1.1" 200 {len(body)} "-" "-" 0.000000\n')
                return

        self.send_response(200)
        self.send_header("Content-Type","text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Date", email.utils.formatdate(None, False, True))
