                s,e=spec.split("-",1)
                try:
                    if s=="" and e!="":
                        suffix=int(e)
                        if suffix<=size:
                            start=size-suffix
                            end=size-1
                            partial=True
                    elif s!="" and e=="":
                        start=int(s)
                        end=size-1
                        partial=True
                    elif s!="" and e!="":
                        start=int(s)
                        end=int(e)
                        if start<size:
                            if end>=size:
                                end=size-1
                            partial=True
                except:
                    pass
        clen = end-start+1 if partial else size
        try:
            f=open(file_path,"rb")
            if partial:
