                continue
            elif comp=="..":
                if parts:
                    parts.pop()
            else:
                parts.append(comp)
        p=self.server.config["serve_path"]
        for part in parts:
            p=p/part
        return p

    def calc_dir_size(self, path):
        total=0
        if not path.exists():
            return 0
        for root, dirs, files in os.walk(path):
