def format_size(size, display):
    if display == "exact":
        return f"{size} B"
    else:
        if size < 1024:
            return f"{size} B"
        elif size < 1024*1024:
            return f"{size/1024:.1f} KiB"
        elif size < 1024*1024*1024:
            return f"{size/(1024*1024):.1f} MiB"
        else:
            return f"{size/(1024*1024*1024):.1f} GiB"

def relative_time(mtime):
    now = time.time()
    diff = now - mtime
    if diff < 10:
        return "now"
    elif diff < 60:
        return f"{int(diff)} seconds ago"
    elif diff < 120:
        return "a minute ago"
    elif diff < 3600:
        return f"{int(diff//60)} minutes ago"
    elif diff < 7200:
        return "an hour ago"
    elif diff < 86400:
        return f"{int(diff//3600)} hours ago"
    elif diff < 172800:
        return "a day ago"
    else:
        return f"{int(diff//86400)} days ago"

def escape_html(s):
    return html.escape(s)

def render_md(md):
    out=""
    in_p=False
    for line in md.splitlines():
        t=line.strip()
        if not t:
            if in_p:
                out+="</p>"
                in_p=False
            continue
        if t.startswith("# "):
            if in_p:
                out+="</p>"
                in_p=False
            out+=f"<h1>{escape_html(t[2:].strip())}</h1>"
        elif t.startswith("## "):
            if in_p:
                out+="</p>"
                in_p=False
            out+=f"<h2>{escape_html(t[3:].strip())}</h2>"
        elif t.startswith("### "):
            if in_p:
                out+="</p>"
                in_p=False
            out+=f"<h3>{escape_html(t[4:].strip())}</h3>"
        else:
            if not in_p:
                out+="<p>"
                in_p=True
            else:
                out+=" "
            out+=escape_html(t)
    if in_p:
        out+="</p>"
    if not out:
        out=f"<p>{escape_html(md)}</p>"
    return out

def generate_qr(url):
    modules=[[False]*27 for _ in range(27)]
    for fx,fy in [(0,0),(0,20),(20,0)]:
        for y in range(7):
            for x in range(7):
                if x==0 or x==6 or y==0 or y==6 or (2<=x<=4 and 2<=y<=4):
                    modules[fy+y][fx+x]=True
    h=hashlib.sha256(url.encode()).digest()
    bits=[]
    for b in h:
        for i in range(8):
            bits.append((b>>i)&1==1)
    idx=0
    for y in range(27):
        for x in range(27):
            if (x<8 and y<8) or (x>=19 and y<8) or (x<8 and y>=19):
                continue
            if x==6 or y==6:
                continue
            if bits[idx % len(bits)]:
                modules[y][x]=True
            idx+=1
    d=""
    for y in range(27):
        for x in range(27):
            if modules[y][x]:
                d+=f"M{x},{y}h1v1h-1"
    return f'<svg viewBox="0 0 27 27" xmlns="http://www.w3.org/2000/svg"><rect width="27px" height="27px" fill="#ffffff"/><path d="{d}"/></svg>'

