def format_size(sz, disp):
    if disp=="exact":
        return f"{sz} B"
    if sz<1024:
        return f"{sz} B"
    elif sz<1024*1024:
        return f"{sz/1024:.1f} KiB"
    else:
        return f"{sz/(1024*1024):.1f} MiB"

def relative_time(mt):
    now=time.time()
    diff=now-mt
    if diff<10:
        return "now"
    elif diff<60:
        return f"{int(diff)} seconds ago"
    elif diff<120:
        return "a minute ago"
    elif diff<3600:
        return f"{int(diff//60)} minutes ago"
    elif diff<7200:
        return "an hour ago"
    elif diff<86400:
        return f"{int(diff//3600)} hours ago"
    elif diff<172800:
