            return {"username":parts[0],"type":None,"hash":':'.join(parts[1:])}

def check_auth_entry(ent, pw):
    if ent["type"] is None:
        return ent["hash"]==pw
    elif ent["type"]=="sha256":
        return hashlib.sha256(pw.encode()).hexdigest()==ent["hash"].lower()
    elif ent["type"]=="sha512":
        return hashlib.sha512(pw.encode()).hexdigest()==ent["hash"].lower()
    else:
        return False

