def generate_random_route():
    return ''.join(random.choices('0123456789abcdef', k=6))

def build_breadcrumb(route_prefix, effective_path, host_display):
    rp = route_prefix or ""
    trimmed = effective_path.strip("/")
    if not trimmed:
        return f'<span><bdi>{escape_html(host_display)}</bdi></span>/'
    parts = trimmed.split("/")
    breadcrumb = f'<a href="{rp}/"><bdi>{escape_html(host_display)}</bdi></a>/'
    for i, part in enumerate(parts):
        is_last = i==len(parts)-1
        up = "/" + "/".join(parts[:i+1]) + "/"
        href = rp + up
        if is_last:
            breadcrumb += f'<span><bdi>{escape_html(part)}</bdi></span>/'
        else:
            breadcrumb += f'<a href="{href}"><bdi>{escape_html(part)}</bdi></a>/'
    return breadcrumb

class MyHandler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        return
    def do_GET(self):
        self.handle_all("GET")
    def do_HEAD(self):
        self.handle_all("HEAD")
    def do_POST(self):
        self.handle_all("POST")
    def do_PROPFIND(self):
        self.handle_all("PROPFIND")

    def handle_all(self, method):
        parsed = urllib.parse.urlparse(self.path)
        raw_path_full = self.path
        path_part = parsed.path
        query_string = parsed.query
        query_params = urllib.parse.parse_qs(query_string)
        query_flat = {k: v[0] for k, v in query_params.items()} if query_params else {}
        effective_path = urllib.parse.unquote(path_part)

        route_prefix = self.server.config.get("route_prefix")
        if route_prefix:
            rp = route_prefix
            if effective_path == rp:
                effective_path = "/"
            elif effective_path.startswith(rp + "/"):
                effective_path = effective_path[len(rp):]
                if not effective_path.startswith("/"):
                    effective_path = "/" + effective_path
            else:
                self.send_404(effective_path, raw_path_full, query_flat, is_route=True)
                return

        auth_entries = self.server.config.get("auth_entries", [])
        if auth_entries:
            ah = self.headers.get("Authorization")
            ok=False
            if ah and ah.lower().startswith("basic "):
                try:
                    dec = base64.b64decode(ah[6:].strip()).decode()
                    if ":" in dec:
                        u,p = dec.split(":",1)
                        for ent in auth_entries:
                            if ent["username"]==u and check_auth_entry(ent,p):
                                ok=True
                                break
                except:
                    pass
            if not ok:
                self.send_response(401)
                self.send_header("WWW-Authenticate","Basic")
                self.send_header("Content-Length","0")
                self.send_header("Date", email.utils.formatdate(None, False, True))
                for k,v in self.server.config.get("custom_headers", []):
                    self.send_header(k,v)
                self.end_headers()
                if self.server.config.get("verbose"):
                    now = datetime.datetime.now().astimezone().strftime("%a, %d %b %Y %H:%M:%S %z")
                    sys.stderr.write(f'{now} [INFO] {self.client_address[0]} "{method} {raw_path_full} HTTP/1.1" 401 0 "-" "-" 0.000000\n')
                return

        if effective_path.startswith("/__miniserve_internal/"):
            if effective_path == "/__miniserve_internal/favicon.svg":
                body = FAVICON_SVG.encode()
                self.send_response(200)
                self.send_header("Content-Type","image/svg+xml")
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Date", email.utils.formatdate(None, False, True))
                for k,v in self.server.config.get("custom_headers", []):
                    self.send_header(k,v)
                self.end_headers()
                if method!="HEAD":
                    self.wfile.write(body)
                return
            elif effective_path == "/__miniserve_internal/style.css":
                body = STYLE_CSS.encode()
                self.send_response(200)
                self.send_header("Content-Type","text/css; charset=utf-8")
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Date", email.utils.formatdate(None, False, True))
                for k,v in self.server.config.get("custom_headers", []):
                    self.send_header(k,v)
                self.end_headers()
                if method!="HEAD":
                    self.wfile.write(body)
                return
            elif effective_path == "/__miniserve_internal/api":
                if method=="POST":
                    clen = int(self.headers.get("Content-Length",0))
                    data = self.rfile.read(clen) if clen>0 else b""
                    try:
                        j = json.loads(data.decode())
                        dp = j.get("DirSize")
                        if dp and self.server.config.get("directory_size"):
                            fs_path = self.resolve_fs(dp)
                            sz = self.calc_dir_size(fs_path)
                            sd = self.server.config.get("size_display","human")
                            sz_str = format_size(sz, sd)
                            body = sz_str.encode()
                            self.send_response(200)
                            self.send_header("Content-Type","text/plain; charset=utf-8")
                            self.send_header("Content-Length", str(len(body)))
                            self.send_header("Date", email.utils.formatdate(None, False, True))
                            for k,v in self.server.config.get("custom_headers", []):
                                self.send_header(k,v)
                            self.end_headers()
                            if method!="HEAD":
                                self.wfile.write(body)
                            return
                    except:
                        pass
                    self.send_response(404)
                    self.send_header("Content-Length","0")
                    self.end_headers()
                    return
                else:
                    self.send_response(404)
                    self.end_headers()
                    return
            else:
                self.send_404(effective_path, raw_path_full, query_flat)
                return

        # upload handling
        if effective_path.startswith("/upload") and method=="POST":
            up_param = query_flat.get("path","/")
            if not self.server.config.get("upload_enabled"):
                self.send_response(403)
                self.end_headers()
                return
            allowed = self.server.config.get("allowed_upload_dir")
            if allowed is not None:
                def norm(p):
                    return p if p.endswith("/") else p+"/"
                if up_param != allowed and not norm(up_param).startswith(norm(allowed)) and allowed != "/":
                    body = b"Upload not allowed to this directory"
                    self.send_response(403)
                    self.send_header("Content-Type","text/plain; charset=utf-8")
                    self.send_header("Content-Length", str(len(body)))
                    self.end_headers()
                    self.wfile.write(body)
                    return
            ctype = self.headers.get("Content-Type","")
            clen = int(self.headers.get("Content-Length",0))
            data = self.rfile.read(clen) if clen>0 else b""
            if "multipart/form-data" in ctype:
                m = re.search(r"boundary=([^;]+)", ctype)
                if not m:
                    self.send_response(400)
                    self.end_headers()
                    return
                boundary = m.group(1).strip('"')
                parts = self.parse_multipart(data, boundary)
                for part in parts:
                    disp = part["headers"].get("content-disposition","")
                    fm = re.search(r'filename="([^"]+)"', disp)
                    nm = re.search(r'name="([^"]+)"', disp)
                    fname = fm.group(1) if fm else None
                    name = nm.group(1) if nm else None
                    if fname:
                        base = os.path.basename(fname)
                        if not base:
                            continue
                        target_dir = self.resolve_fs(up_param)
                        if not target_dir.is_dir():
                            body = f"Invalid path\ncaused by: cannot upload file to {target_dir}, since it's not a directory".encode()
                            self.send_response(400)
                            self.send_header("Content-Type","text/plain; charset=utf-8")
                            self.send_header("Content-Length", str(len(body)))
                            self.end_headers()
                            self.wfile.write(body)
                            return
                        dest = target_dir / base
                        dup = self.server.config.get("on_duplicate","error")
                        if dup == "error" and dest.exists():
                            body = f"File {base} already exists".encode()
                            self.send_response(400)
                            self.send_header("Content-Length", str(len(body)))
                            self.end_headers()
                            self.wfile.write(body)
                            return
                        elif dup == "rename" and dest.exists():
                            dest = self.gen_rename(target_dir, base)
                        try:
                            td = self.server.config.get("temp_dir")
                            if td:
                                tmp = pathlib.Path(td) / f"miniserve_tmp_{time.time_ns()}"
                                tmp.write_bytes(part["body"])
                                shutil.move(str(tmp), str(dest))
                            else:
                                dest.write_bytes(part["body"])
                            chmod = self.server.config.get("chmod")
                            if chmod:
                                try:
                                    mode = int(chmod, 8)
                                    os.chmod(dest, mode)
                                except:
                                    pass
                        except Exception as e:
                            self.send_response(500)
                            self.end_headers()
                            self.wfile.write(str(e).encode())
                            return
                    else:
                        if name == "mkdir":
                            if not self.server.config.get("mkdir"):
                                body = f"Insufficient permissions to create file in {self.resolve_fs(up_param)}".encode()
                                self.send_response(403)
                                self.send_header("Content-Length", str(len(body)))
                                self.end_headers()
                                self.wfile.write(body)
                                return
                            dname = part["body"].decode().strip()
                            if not dname or "/" in dname or ".." in dname:
                                self.send_response(400)
                                self.end_headers()
                                self.wfile.write(b"Invalid directory name")
                                return
                            target_dir = self.resolve_fs(up_param)
                            new_dir = target_dir / dname
                            try:
                                new_dir.mkdir()
                            except Exception as e:
                                self.send_response(500)
                                self.end_headers()
                                self.wfile.write(str(e).encode())
                                return
                loc = up_param
                if not loc.startswith("/"):
                    loc = "/" + loc
                rp = self.server.config.get("route_prefix") or ""
                loc = rp + loc
                self.send_response(303)
                self.send_header("Location", loc)
                self.send_header("Content-Length","0")
                self.end_headers()
                return
            else:
                self.send_response(400)
                self.end_headers()
                return

        if effective_path.startswith("/rm") and method=="POST":
            if not self.server.config.get("rm_enabled"):
                self.send_response(403)
                self.end_headers()
                return
            rm_param = query_flat.get("path","/")
            allowed_rm = self.server.config.get("allowed_rm_dir")
            if allowed_rm is not None:
                def norm(p):
                    return p if p.endswith("/") else p+"/"
                if rm_param != allowed_rm and not norm(rm_param).startswith(norm(allowed_rm)) and allowed_rm != "/":
                    self.send_response(403)
                    self.end_headers()
                    return
            target = self.resolve_fs(rm_param)
            if not target.exists():
                self.send_404(effective_path, raw_path_full, query_flat)
                return
            serve_real = self.server.config["serve_path"].resolve()
            try:
                if not str(target.resolve()).startswith(str(serve_real)):
                    self.send_response(403)
                    self.end_headers()
                    return
            except:
                pass
            try:
                if target.is_dir():
                    shutil.rmtree(target)
                else:
                    target.unlink()
            except Exception as e:
                self.send_response(500)
                self.end_headers()
                self.wfile.write(str(e).encode())
                return
            self.send_response(303)
            self.send_header("Location","/")
            self.send_header("Content-Length","0")
            self.end_headers()
            return

        serve_path = self.server.config["serve_path"]
        serve_is_file = self.server.config["serve_path_is_file"]
        if serve_is_file:
            if effective_path == "/":
                self.serve_file(serve_path, method, raw_path_full, query_flat)
                return
            else:
                self.send_404(effective_path, raw_path_full, query_flat)
                return

        fs_path = self.resolve_fs(effective_path)

        if self.server.config.get("no_symlinks"):
            if fs_path.is_symlink():
                self.send_404(effective_path, raw_path_full, query_flat)
                return
        try:
            serve_real = serve_path.resolve()
            if fs_path.exists():
                real = fs_path.resolve()
            else:
                if fs_path.parent.exists():
                    real = fs_path.parent.resolve() / fs_path.name
                else:
                    real = fs_path
            if not str(real).startswith(str(serve_real)):
                self.send_404(effective_path, raw_path_full, query_flat)
                return
        except:
            pass

        if fs_path.is_file():
            self.serve_file(fs_path, method, raw_path_full, query_flat)
            return
        if fs_path.is_dir():
            dl = query_flat.get("download")
            if dl:
                if dl=="tar" and self.server.config.get("enable_tar"):
                    self.serve_tar(fs_path, False, method, raw_path_full, query_flat)
                    return
                if dl=="tar_gz" and self.server.config.get("enable_tar_gz"):
                    self.serve_tar(fs_path, True, method, raw_path_full, query_flat)
                    return
                if dl=="zip" and self.server.config.get("enable_zip"):
                    self.serve_zip(fs_path, method, raw_path_full, query_flat)
                    return
            idx = self.server.config.get("index")
            if idx:
                ip = fs_path / idx
                if ip.is_file():
                    self.serve_file(ip, method, raw_path_full, query_flat)
                    return
            if self.server.config.get("disable_indexing"):
                self.send_404_file_not_found(effective_path, raw_path_full, query_flat)
                return
            if not effective_path.endswith("/"):
                newp = effective_path + "/"
                if query_string:
                    newp += "?" + query_string
                rp = self.server.config.get("route_prefix") or ""
                loc = rp + newp
                self.send_response(301)
                self.send_header("Location", loc)
                self.send_header("Content-Length","0")
                self.end_headers()
                return
            self.serve_directory(fs_path, effective_path, raw_path_full, query_flat, method)
            return

        if self.server.config.get("pretty_urls"):
            cand = pathlib.Path(str(fs_path) + ".html")
            if cand.is_file():
                self.serve_file(cand, method, raw_path_full, query_flat)
                return
        if self.server.config.get("spa"):
            idx = self.server.config.get("index")
            if idx:
                ip = serve_path / idx
                if ip.is_file():
                    self.serve_file(ip, method, raw_path_full, query_flat)
                    return
        self.send_404(effective_path, raw_path_full, query_flat)

    def resolve_fs(self, url_path):
        trimmed=url_path.lstrip("/")
        parts=[]
        for comp in pathlib.PurePosixPath(trimmed).parts:
            if comp==".":
                continue
            elif comp=="..":
                if parts:
                    parts.pop()
            else:
                parts.append(comp)
        p=self.server.config["serve_path"]
        for part in parts:
            p=p/part
        return p

    def calc_dir_size(self, path):
        total=0
        if not path.exists():
            return 0
        for root, dirs, files in os.walk(path):
            if not self.server.config.get("hidden"):
                dirs[:]=[d for d in dirs if not d.startswith(".")]
                files=[f for f in files if not f.startswith(".")]
            if self.server.config.get("no_symlinks"):
                dirs[:]=[d for d in dirs if not os.path.islink(os.path.join(root,d))]
                files=[f for f in files if not os.path.islink(os.path.join(root,f))]
            for f in files:
                fp=os.path.join(root,f)
                try:
                    total+=os.path.getsize(fp)
                except:
                    pass
        return total

    def gen_rename(self, dir_path, original_name):
        p=pathlib.Path(original_name)
        stem=p.stem
        suffix=p.suffix
        c=1
        while True:
            new_name=f"{stem}-{c}{suffix}"
            new_path=dir_path / new_name
            if not new_path.exists():
                return new_path
            c+=1

    def check_media_type(self, filename, mt):
        ext=pathlib.Path(filename).suffix.lower()
        if mt=="image":
            return ext in [".jpg",".jpeg",".png",".gif",".bmp",".webp",".svg",".ico"]
        elif mt=="audio":
            return ext in [".mp3",".wav",".ogg",".flac",".aac",".m4a"]
        elif mt=="video":
            return ext in [".mp4",".avi",".mkv",".mov",".webm",".m4v"]
        return True

    def parse_multipart(self, data, boundary):
        b_marker = ("--" + boundary).encode()
        crlf = b"\r\n"
        crlf2 = b"\r\n\r\n"
        b_sep = crlf + b_marker
        parts=[]
        pos=0
        while pos < len(data):
            idx=data.find(b_marker, pos)
            if idx==-1:
                break
            start=idx+len(b_marker)
            if data[start:start+2]==crlf:
                start+=2
            h_end=data.find(crlf2, start)
            if h_end==-1:
                break
            header_bytes=data[start:h_end]
            body_start=h_end+4
            next_idx=data.find(b_sep, body_start)
            end_marker=("--" + boundary + "--").encode()
            end_idx=data.find(end_marker, body_start)
            if next_idx!=-1 and (end_idx==-1 or next_idx < end_idx):
                body_end=next_idx
                if data[body_end-2:body_end]==crlf:
                    body_end-=2
                h_str=header_bytes.decode(errors="ignore")
                hdrs={}
                for line in h_str.split("\r\n"):
                    if ":" in line:
                        k,v=line.split(":",1)
                        hdrs[k.strip().lower()]=v.strip()
                parts.append({"headers":hdrs,"body":data[body_start:body_end]})
                pos=next_idx
                continue
            elif end_idx!=-1:
                body_end=end_idx
                if body_end>=2 and data[body_end-2:body_end]==crlf:
                    body_end-=2
                h_str=header_bytes.decode(errors="ignore")
                hdrs={}
                for line in h_str.split("\r\n"):
                    if ":" in line:
                        k,v=line.split(":",1)
                        hdrs[k.strip().lower()]=v.strip()
                parts.append({"headers":hdrs,"body":data[body_start:body_end]})
                break
            else:
                break
        return parts

    def serve_file(self, file_path, method, raw_path_full, query_flat):
        try:
            st = file_path.stat()
        except:
            self.send_404(str(file_path), raw_path_full, query_flat)
            return
        size = st.st_size
        mtime = st.st_mtime
        last_mod = email.utils.formatdate(mtime, usegmt=True)
        etag = '"%x:%x"' % (int(mtime), size)
        if_none = self.headers.get("If-None-Match")
        if if_none and (if_none.strip()==etag or if_none.strip()==etag.strip('"')):
            self.send_response(304)
            self.end_headers()
            return
        range_header = self.headers.get("Range")
        start=0
        end=size-1
        partial=False
        if range_header and range_header.startswith("bytes="):
            spec=range_header[6:]
            if "-" in spec:
                s,e=spec.split("-",1)
                try:
                    if s=="" and e!="":
                        suffix=int(e)
                        if suffix<=size:
                            start=size-suffix
                            end=size-1
                            partial=True
                    elif s!="" and e=="":
                        start=int(s)
                        end=size-1
                        partial=True
                    elif s!="" and e!="":
                        start=int(s)
                        end=int(e)
                        if start<size:
                            if end>=size:
                                end=size-1
                            partial=True
                except:
                    pass
        clen = end-start+1 if partial else size
        try:
            f=open(file_path,"rb")
            if partial:
                f.seek(start)
                data=f.read(clen)
            else:
                data=f.read() if method!="HEAD" else b""
            f.close()
        except:
            self.send_response(500)
            self.end_headers()
            return
        mime=get_mime_type(str(file_path))
        disp="inline"
        self.send_response(206 if partial else 200)
        self.send_header("Content-Length", str(clen))
        self.send_header("Content-Type", mime)
        self.send_header("Content-Disposition", '%s; filename="%s"' % (disp, file_path.name))
        self.send_header("Accept-Ranges","bytes")
        self.send_header("Last-Modified", last_mod)
        self.send_header("ETag", etag)
        self.send_header("Date", email.utils.formatdate(None, False, True))
        if partial:
            self.send_header("Content-Range", "bytes %d-%d/%d" % (start, end, size))
        for k,v in self.server.config.get("custom_headers", []):
            self.send_header(k,v)
        self.end_headers()
        if method!="HEAD":
            self.wfile.write(data)

    def serve_directory(self, fs_path, effective_path, raw_path_full, query_flat, method):
        import os, datetime
        sort_method = query_flat.get("sort", self.server.config.get("default_sorting_method","name"))
        sort_order = query_flat.get("order", self.server.config.get("default_sorting_order","desc"))
        entries=[]
        for entry in os.scandir(fs_path):
            name=entry.name
            if not self.server.config.get("hidden") and name.startswith("."):
                continue
            if self.server.config.get("no_symlinks") and entry.is_symlink():
                continue
            is_dir = entry.is_dir()
            try:
                st=entry.stat(follow_symlinks=True)
                sz=0 if is_dir else st.st_size
                mt=st.st_mtime
            except:
                sz=0
                mt=time.time()
            entries.append({"name":name,"is_dir":is_dir,"size":sz,"mtime":mt})
        def kf(e):
            if sort_method=="size":
                return e["size"]
            elif sort_method=="date":
                return e["mtime"]
            else:
                return e["name"].lower()
        reverse = (sort_order=="desc")
        if self.server.config.get("dirs_first"):
            entries.sort(key=kf, reverse=reverse)
            dirs=[e for e in entries if e["is_dir"]]
            files=[e for e in entries if not e["is_dir"]]
            entries=dirs+files
        else:
            entries.sort(key=kf, reverse=reverse)

        is_raw = query_flat.get("raw")=="true"
        if is_raw:
            html_out='<!DOCTYPE html><html><body><table><thead><th class="name">Name</th><th class="size">Size</th><th class="date">Last modification</th></thead><tbody>'
            if effective_path!="/":
                trimmed=effective_path.rstrip("/")
                parent="/".join(trimmed.split("/")[:-1])
                if parent=="":
                    parent="/"
                else:
                    if not parent.startswith("/"):
                        parent="/"+parent
                    if not parent.endswith("/"):
                        parent+="/"
                html_out+='<tr><td colspan="3"><p><a class="root" href="%s?raw=true">..</a></p></td></tr>' % parent
            for e in entries:
                if e["is_dir"]:
                    href="/%s/?raw=true" % e["name"] if effective_path=="/" else "%s%s/?raw=true" % (effective_path, e["name"])
                    html_out+='<tr class="entry-type-directory"><td><p><a class="directory" href="%s">%s/</a></p></td><td class="size-cell"></td><td class="date-cell"><span>%s </span><span class="history">%s</span></td></tr>' % (href, escape_html(e["name"]), datetime.datetime.fromtimestamp(e["mtime"]).strftime("%Y-%m-%d %H:%M:%S %z"), relative_time(e["mtime"]))
                else:
                    href="/%s" % e["name"] if effective_path=="/" else "%s%s" % (effective_path, e["name"])
                    ext_url=self.server.config.get("file_external_url")
                    if ext_url:
                        href=ext_url.rstrip("/")+href
                    html_out+='<tr class="entry-type-file"><td><p><a class="file" href="%s">%s</a></p></td><td class="size-cell">%s</td><td class="date-cell"><span>%s </span><span class="history">%s</span></td></tr>' % (href, escape_html(e["name"]), format_size(e["size"], self.server.config.get("size_display","human")), datetime.datetime.fromtimestamp(e["mtime"]).strftime("%Y-%m-%d %H:%M:%S %z"), relative_time(e["mtime"]))
            html_out+='</tbody></table></body></html>'
            body=html_out.encode()
            self.send_response(200)
            self.send_header("Content-Type","text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            if method!="HEAD":
                self.wfile.write(body)
            return

        host_display = self.server.config.get("title") or self.headers.get("Host") or "127.0.0.1:8080"
        rp = self.server.config.get("route_prefix") or ""
        trimmed=effective_path.strip("/")
        if not trimmed:
            breadcrumb='<span><bdi>%s</bdi></span>/' % escape_html(host_display)
        else:
            parts=trimmed.split("/")
            breadcrumb='<a href="%s/"><bdi>%s</bdi></a>/' % (rp, escape_html(host_display))
            for i,part in enumerate(parts):
                is_last=i==len(parts)-1
                up="/"+"/".join(parts[:i+1])+"/"
                href=rp+up
                if is_last:
                    breadcrumb+='<span><bdi>%s</bdi></span>/' % escape_html(part)
                else:
                    breadcrumb+='<a href="%s"><bdi>%s</bdi></a>/' % (href, escape_html(part))

        toolbar_download=""
        if self.server.config.get("enable_tar") or self.server.config.get("enable_tar_gz") or self.server.config.get("enable_zip"):
            toolbar_download='<div class="download">'
            if self.server.config.get("enable_tar_gz"):
                toolbar_download+='<a href="?download=tar_gz">Download .tar.gz</a>'
            if self.server.config.get("enable_tar"):
                toolbar_download+='<a href="?download=tar">Download .tar</a>'
            if self.server.config.get("enable_zip"):
                toolbar_download+='<a href="?download=zip">Download .zip</a>'
            toolbar_download+='</div>'

        upload_enabled=self.server.config.get("upload_enabled")
        mkdir_enabled=self.server.config.get("mkdir")
        toolbar_box=""
        if upload_enabled or mkdir_enabled:
            toolbar_box='<div class="toolbar_box_group">'
            if upload_enabled:
                up_path=effective_path
                action="%s/upload?path=%s" % (rp, up_path)
                toolbar_box+='<div class="toolbar_box"><form id="file_submit" action="%s" method="POST" enctype="multipart/form-data"><p>Select a file to upload or drag it anywhere into the window</p><div><input id="file-input" type="file" name="file_to_upload" required="" multiple></input><button type="submit">Upload file</button></div></form></div>' % action
            if mkdir_enabled:
                up_path=effective_path
                action="%s/upload?path=%s" % (rp, up_path)
                toolbar_box+='<div class="toolbar_box"><form id="mkdir" action="%s" method="POST" enctype="multipart/form-data"><p>Specify a directory name to create</p><div class="toolbar_box"><input type="text" name="mkdir" required="" placeholder="Directory name"></input><button type="submit">Create directory</button></div></form></div>' % action
            toolbar_box+='</div>'
        else:
            toolbar_box='<div class="toolbar_box_group"></div>'

        toolbar='<div class="toolbar">%s%s</div>' % (toolbar_download, toolbar_box)

        rows=""
        if effective_path!="/":
            trimmed=effective_path.rstrip("/")
            parent="/".join(trimmed.split("/")[:-1])
            if parent=="":
                parent="/"
            else:
                if not parent.startswith("/"):
                    parent="/"+parent
                if not parent.endswith("/"):
                    parent+="/"
            parent_href=rp+parent
            sq=""
            if "sort" in query_flat or "order" in query_flat:
                parts=[]
                if "sort" in query_flat:
                    parts.append("sort=%s" % query_flat["sort"])
                if "order" in query_flat:
                    parts.append("order=%s" % query_flat["order"])
                sq="?"+"&".join(parts)
                parent_href+=sq
            rows+='<tr><td colspan="3"><p><span class="root-chevron">◂</span><a class="root" href="%s">Parent directory</a></p></td></tr>' % parent_href
        for e in entries:
            href="/%s/" % e["name"] if effective_path=="/" else "%s%s/" % (effective_path, e["name"]) if e["is_dir"] else "/%s" % e["name"] if effective_path=="/" else "%s%s" % (effective_path, e["name"])
            if rp and not (self.server.config.get("file_external_url") and not e["is_dir"]):
                href=rp+href
            if e["is_dir"]:
                if "sort" in query_flat or "order" in query_flat:
                    sq=""
                    if "sort" in query_flat:
                        sq+="sort=%s" % query_flat["sort"]
                    if "order" in query_flat:
                        if sq:
                            sq+="&"
                        sq+="order=%s" % query_flat["order"]
                    href+="?"+sq
            else:
                ext_url=self.server.config.get("file_external_url")
                if ext_url and not e["is_dir"]:
                    href=ext_url.rstrip("/")+ ("/%s" % e["name"] if effective_path=="/" else "%s%s" % (effective_path, e["name"]))

            size_disp="" if e["is_dir"] else format_size(e["size"], self.server.config.get("size_display","human"))
            mtime_str=datetime.datetime.fromtimestamp(e["mtime"]).astimezone().strftime("%Y-%m-%d %H:%M:%S %:z")
            rel=relative_time(e["mtime"])
            if e["is_dir"]:
                rows+='<tr class="entry-type-directory"><td><p><a class="directory" href="%s">%s/</a></p></td><td class="size-cell"></td><td class="date-cell"><span>%s </span><span class="history">%s</span></td></tr>' % (href, escape_html(e["name"]), mtime_str, rel)
            else:
                rows+='<tr class="entry-type-file"><td><p><a class="file" href="%s">%s</a><span class="mobile-info size"><span class=""><span class="chevron">▾</span><a href="?sort=size&amp;order=asc" title="Sort by size in ascending order">%s </a></span></span></p></td><td class="size-cell">%s</td><td class="date-cell"><span>%s </span><span class="history">%s</span></td></tr>' % (href, escape_html(e["name"]), size_disp, size_disp, mtime_str, rel)
            if self.server.config.get("rm_enabled"):
                rm_path="/%s" % e["name"] if effective_path=="/" else "%s%s" % (effective_path, e["name"])
                rm_action="%s/rm?path=%s" % (rp, rm_path)
                rows+='<td class="actions-cell"><form class="rm_form" action="%s" method="POST"><button type="submit" title="Delete">✗</button></form></td></tr>' % rm_action

        version_footer='' if self.server.config.get("hide_version_footer") else '<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/%s</div>' % VERSION
