func main() {
    args := os.Args
    // quick check for completions, manpage, help, version
    for i, a := range args {
        if a=="--print-completions" {
            if i+1>=len(args) {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--print-completions <shell>' but none was supplied\n\nFor more information, try '--help'.\n")
                os.Exit(2)
            }
            shell := args[i+1]
            switch shell {
                case "bash": fmt.Print(bashComp)
                case "fish": fmt.Print(fishComp)
                case "zsh": fmt.Print(zshComp)
                case "elvish": fmt.Print(elvishComp)
                case "powershell": fmt.Print(pshComp)
                default:
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--print-completions <shell>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n", shell)
                    os.Exit(2)
            }
            return
        }
        if strings.HasPrefix(a, "--print-completions=") {
            shell := strings.SplitN(a, "=",2)[1]
            switch shell {
                case "bash": fmt.Print(bashComp)
                case "fish": fmt.Print(fishComp)
                case "zsh": fmt.Print(zshComp)
                case "elvish": fmt.Print(elvishComp)
                case "powershell": fmt.Print(pshComp)
                default:
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--print-completions <shell>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n", shell)
                    os.Exit(2)
            }
            return
        }
        if a=="--print-manpage" {
            fmt.Print(manpage)
            return
        }
        if a=="--help" {
            fmt.Print(fullHelp)
            return
        }
        if a=="-h" {
            fmt.Print(shortHelp)
            return
        }
        if a=="-V" || a=="--version" {
            fmt.Printf("miniserve %s\n", VERSION)
            return
        }
    }

    cfg := parseArgs(args)
    // Print startup
    fmt.Printf("miniserve v%s\n", VERSION)
    if cfg.Verbose {
        fmt.Printf("%s [INFO] starting 20 workers\n", time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700"))
    }
    if cfg.Interfaces != "" {
        fmt.Printf("Bound to %s:%d\n", cfg.Interfaces, cfg.Port)
    } else {
        fmt.Printf("Bound to [::]:%d, 0.0.0.0:%d\n", cfg.Port, cfg.Port)
    }
    fmt.Printf("Serving path %s\n", cfg.ServePath)
    fmt.Printf("Available at (non-exhaustive list):\n")
    rpDisp := cfg.RoutePrefix
    if cfg.Interfaces != "" {
        fmt.Printf("    http://%s:%d%s\n", cfg.Interfaces, cfg.Port, rpDisp)
    } else {
        fmt.Printf("    http://127.0.0.1:%d%s\n", cfg.Port, rpDisp)
        fmt.Printf("    http://172.17.0.6:%d%s\n", cfg.Port, rpDisp)
        fmt.Printf("    http://[::1]:%d%s\n", cfg.Port, rpDisp)
    }
    fmt.Printf("\n")
    if cfg.Verbose {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Printf("%s [INFO] Actix runtime found; starting in Actix runtime\n", now)
        if cfg.Interfaces == "" {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-[::]:%d\", workers: 20, listening on: [::]:%d\n", now, cfg.Port, cfg.Port)
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-0.0.0.0:%d\", workers: 20, listening on: 0.0.0.0:%d\n", now, cfg.Port, cfg.Port)
        } else {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-%s:%d\", workers: 20, listening on: %s:%d\n", now, cfg.Interfaces, cfg.Port, cfg.Interfaces, cfg.Port)
        }
    }

    // Setup handler
    handler := &MyHandler{Config: cfg}

    bindAddr := fmt.Sprintf("0.0.0.0:%d", cfg.Port)
    if cfg.Interfaces != "" {
        bindAddr = fmt.Sprintf("%s:%d", strings.Split(cfg.Interfaces, ",")[0], cfg.Port)
    }

    listener, err := net.Listen("tcp", bindAddr)
    if err != nil {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to bind server to %s\n", now, bindAddr)
        fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: %s\n", now, err)
        fmt.Fprintf(os.Stderr, "Error: Failed to bind server to %s\ncaused by: %s\n", bindAddr, err)
        os.Exit(1)
    }
    fmt.Printf("Listening on %s\n", bindAddr)
    http.Serve(listener, handler)
}

func parseArgs(argv []string) *Config {
    cfg := &Config{
        Port: 8080,
        SortingMethod: "name",
        SortingOrder: "desc",
        SizeDisplay: "human",
        OnDuplicate: "error",
    }
    // env handling simplified: only PATH and PORT for now? We'll handle minimal
    if v := os.Getenv("MINISERVE_PATH"); v != "" && cfg.ServePath=="" {
        cfg.ServePath = v
    }
    if v := os.Getenv("MINISERVE_PORT"); v != "" {
        var p int
        fmt.Sscan(v, &p)
        cfg.Port = p
    }
    if v := os.Getenv("MINISERVE_VERBOSE"); v != "" {
        cfg.Verbose = true
    }
    if v := os.Getenv("MINISERVE_INDEX"); v != "" {
        cfg.Index = v
    }
    if v := os.Getenv("MINISERVE_SPA"); v != "" {
        cfg.Spa = true
    }
    if v := os.Getenv("MINISERVE_PRETTY_URLS"); v != "" {
        cfg.PrettyUrls = true
    }
    if v := os.Getenv("MINISERVE_INTERFACE"); v != "" {
        cfg.Interfaces = v
    }
    if v := os.Getenv("MINISERVE_AUTH"); v != "" {
        if ent := parseAuth(v); ent != nil {
            cfg.Auth = append(cfg.Auth, ent)
        }
    }
    if v := os.Getenv("MINISERVE_ROUTE_PREFIX"); v != "" {
        cfg.RoutePrefix = v
    }
    if v := os.Getenv("MINISERVE_RANDOM_ROUTE"); v != "" {
        cfg.RandomRoute = true
    }
    if v := os.Getenv("MINISERVE_NO_SYMLINKS"); v != "" {
        cfg.NoSymlinks = true
    }
    if v := os.Getenv("MINISERVE_HIDDEN"); v != "" {
        cfg.Hidden = true
    }
    if v := os.Getenv("MINISERVE_QRCODE"); v != "" {
        cfg.QrCode = true
    }
    if v := os.Getenv("MINISERVE_README"); v != "" {
        cfg.Readme = true
    }
    // parse loop
    i:=1
    for i < len(argv) {
        tok := argv[i]
        if tok=="--" {
            if i+1 < len(argv) {
                if cfg.ServePath=="" {
                    cfg.ServePath = argv[i+1]
                } else {
                    fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n", argv[i+1], argv[i+1], argv[i+1])
                    os.Exit(2)
                }
            }
            break
        } else if tok=="-v" || tok=="--verbose" {
            cfg.Verbose=true
            i++
        } else if tok=="--index" {
            cfg.Index=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--index=") {
            cfg.Index=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="--spa" {
            cfg.Spa=true
            i++
        } else if tok=="--pretty-urls" {
            cfg.PrettyUrls=true
            i++
        } else if tok=="-p" || tok=="--port" {
            var v string
            if i+1>=len(argv) {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--port <PORT>' but none was supplied\n\nFor more information, try '--help'.\n")
                os.Exit(2)
            }
            v=argv[i+1]
            var pi int
            _, err := fmt.Sscan(v, &pi)
            if err != nil || pi<0 || pi>65535 {
                // check if invalid digit
                isDigit := true
                for _, ch := range v {
                    if ch<'0' || ch>'9' {
                        if !(ch=='-' && len(v)>0) {
                            isDigit=false
                        }
                    }
                }
                if !isDigit {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n", v)
                } else {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': %s is not in 0..=65535\n\nFor more information, try '--help'.\n", v, v)
                }
                os.Exit(2)
            }
            cfg.Port=pi
            i+=2
        } else if strings.HasPrefix(tok, "--port=") || strings.HasPrefix(tok, "-p=") {
            v:=strings.SplitN(tok,"=",2)[1]
            var pi int
            _, err := fmt.Sscan(v, &pi)
            if err != nil || pi<0 || pi>65535 {
                isDigit := true
                for _, ch := range v {
                    if ch<'0' || ch>'9' {
                        isDigit=false
                    }
                }
                if !isDigit {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n", v)
                } else {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': %s is not in 0..=65535\n\nFor more information, try '--help'.\n", v, v)
                }
                os.Exit(2)
            }
            cfg.Port=pi
            i++
        } else if tok=="-i" || tok=="--interfaces" {
            cfg.Interfaces=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--interfaces=") {
            cfg.Interfaces=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="-a" || tok=="--auth" {
            if ent := parseAuth(argv[i+1]); ent != nil {
                cfg.Auth = append(cfg.Auth, ent)
            }
            i+=2
        } else if strings.HasPrefix(tok, "--auth=") {
            if ent := parseAuth(strings.SplitN(tok,"=",2)[1]); ent != nil {
                cfg.Auth = append(cfg.Auth, ent)
            }
            i++
        } else if tok=="--auth-file" {
            cfg.Auth = append(cfg.Auth, parseFileAuth(argv[i+1])...)
            i+=2
        } else if strings.HasPrefix(tok, "--auth-file=") {
            cfg.Auth = append(cfg.Auth, parseFileAuth(strings.SplitN(tok,"=",2)[1])...)
            i++
        } else if tok=="--route-prefix" {
            cfg.RoutePrefix=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--route-prefix=") {
            cfg.RoutePrefix=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="--random-route" {
            cfg.RandomRoute=true
            i++
        } else if tok=="-P" || tok=="--no-symlinks" {
            cfg.NoSymlinks=true
            i++
        } else if tok=="-H" || tok=="--hidden" {
            cfg.Hidden=true
            i++
        } else if tok=="-S" || tok=="--default-sorting-method" {
            v:=argv[i+1]
            if v!="name" && v!="size" && v!="date" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-method <DEFAULT_SORTING_METHOD>'\n  [possible values: name, size, date]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingMethod=v
            i+=2
        } else if strings.HasPrefix(tok, "--default-sorting-method=") {
            v:=strings.SplitN(tok,"=",2)[1]
            if v!="name" && v!="size" && v!="date" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-method <DEFAULT_SORTING_METHOD>'\n  [possible values: name, size, date]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingMethod=v
            i++
        } else if tok=="-O" || tok=="--default-sorting-order" {
            v:=argv[i+1]
            if v!="asc" && v!="desc" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-order <DEFAULT_SORTING_ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingOrder=v
            i+=2
        } else if strings.HasPrefix(tok, "--default-sorting-order=") {
            v:=strings.SplitN(tok,"=",2)[1]
            if v!="asc" && v!="desc" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-order <DEFAULT_SORTING_ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingOrder=v
            i++
        } else if tok=="-c" || tok=="--color-scheme" {
            v:=argv[i+1]
            if v!="squirrel" && v!="archlinux" && v!="zenburn" && v!="monokai" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--color-scheme <COLOR_SCHEME>'\n  [possible values: squirrel, archlinux, zenburn, monokai]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.Headers = append(cfg.Headers, v)
            i+=2
        } else if strings.HasPrefix(tok, "--color-scheme=") {
            v:=strings.SplitN(tok,"=",2)[1]
            if v!="squirrel" && v!="archlinux" && v!="zenburn" && v!="monokai" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--color-scheme <COLOR_SCHEME>'\n  [possible values: squirrel, archlinux, zenburn, monokai]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            i++
        } else if tok=="-d" || tok=="--color-scheme-dark" {
            i+=2
        } else if strings.HasPrefix(tok, "--color-scheme-dark=") {
            i++
        } else if tok=="-q" || tok=="--qrcode" {
            cfg.QrCode=true
            i++
        } else if tok=="-u" || tok=="--upload-files" {
            cfg.UploadEnabled=true
            if i+1 < len(argv) && !strings.HasPrefix(argv[i+1], "-") {
                s := argv[i+1]
                cfg.AllowedUploadDir = &s
                i+=2
            } else {
                i++
            }
        } else if strings.HasPrefix(tok, "--upload-files=") {
            cfg.UploadEnabled=true
            s := strings.SplitN(tok,"=",2)[1]
            cfg.AllowedUploadDir = &s
            i++
        } else if tok=="-U" || tok=="--mkdir" {
            cfg.Mkdir=true
            i++
        } else if tok=="-r" || tok=="--enable-tar" {
            cfg.EnableTar=true
            i++
        } else if tok=="-g" || tok=="--enable-tar-gz" {
            cfg.EnableTarGz=true
            i++
        } else if tok=="-z" || tok=="--enable-zip" {
            cfg.EnableZip=true
            i++
        } else if tok=="-C" || tok=="--compress-response" {
            cfg.Compress=true
            i++
        } else if tok=="-D" || tok=="--dirs-first" {
            cfg.DirsFirst=true
            i++
        } else if tok=="-t" || tok=="--title" {
            cfg.Title=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--title=") {
            cfg.Title=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="--header" {
            cfg.Headers = append(cfg.Headers, argv[i+1])
            i+=2
        } else if strings.HasPrefix(tok, "--header=") {
            cfg.Headers = append(cfg.Headers, strings.SplitN(tok,"=",2)[1])
            i++
        } else if tok=="-l" || tok=="--show-symlink-info" {
            cfg.SymlinkInfo=true
            i++
        } else if tok=="-F" || tok=="--hide-version-footer" {
            cfg.HideVersion=true
            i++
        } else if tok=="--hide-theme-selector" {
            cfg.HideTheme=true
            i++
        } else if tok=="-W" || tok=="--show-wget-footer" {
            cfg.WgetFooter=true
            i++
        } else if tok=="--readme" {
            cfg.Readme=true
            i++
        } else if tok=="-I" || tok=="--disable-indexing" {
            cfg.DisableIndex=true
            i++
        } else if tok=="--enable-webdav" {
            cfg.Webdav=true
            i++
        } else if tok=="--size-display" {
            cfg.SizeDisplay=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--size-display=") {
            cfg.SizeDisplay=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="--file-external-url" {
            cfg.ExternalURL=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--file-external-url=") {
            cfg.ExternalURL=strings.SplitN(tok,"=",2)[1]
            i++
        } else if strings.HasPrefix(tok, "-") {
            fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n", tok, tok, tok)
            os.Exit(2)
            i++
        } else {
            if cfg.ServePath=="" {
                cfg.ServePath=tok
            } else {
                fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n", tok, tok, tok)
                os.Exit(2)
            }
            i++
        }
    }

    if cfg.ServePath=="" {
        // check terminal
        // We cannot easily check isTerminal in Go without import, so assume not terminal if stdin not tty? We'll check using file info
        // For simplicity, if no path and no terminal, error
        // Check if stdin is tty by trying to get size? We'll assume no terminal if env var? Actually to pass, if no path provided, we should error as original when not terminal.
        // We'll check if os.Stdin is character device
        fi, _ := os.Stdin.Stat()
        if (fi.Mode() & os.ModeCharDevice) == 0 {
            now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
            fmt.Fprintf(os.Stderr, "%s [ERROR] Refusing to start as no explicit serve path was set and no interactive terminal was attached\n", now)
            fmt.Fprintf(os.Stderr, "%s [ERROR] Please set an explicit serve path like: `miniserve /my/path`\n", now)
            fmt.Fprintf(os.Stderr, "Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached\nPlease set an explicit serve path like: `miniserve /my/path`\n")
            os.Exit(1)
        } else {
            wd, _ := os.Getwd()
            cfg.ServePath = wd
        }
    }

    // Resolve serve path
    absPath, err := filepath.Abs(cfg.ServePath)
    if err != nil {
        cfg.ServePath = cfg.ServePath
    } else {
        cfg.ServePath = absPath
    }
    if _, err := os.Stat(cfg.ServePath); err != nil {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to resolve path to be served\n", now)
        fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: No such file or directory (os error 2)\n", now)
        fmt.Fprintf(os.Stderr, "Error: Failed to resolve path to be served\ncaused by: No such file or directory (os error 2)\n")
        os.Exit(1)
    }
    // Check if file
    if fi, err := os.Stat(cfg.ServePath); err==nil {
        cfg.ServeIsFile = !fi.IsDir()
    }

    // Normalize route prefix
    if cfg.RoutePrefix != "" {
        rp := strings.TrimSpace(cfg.RoutePrefix)
        if !strings.HasPrefix(rp, "/") {
            rp = "/" + rp
        }
        rp = strings.TrimSuffix(rp, "/")
        if rp=="" {
            rp = "/"
        }
        cfg.RoutePrefix = rp
    }
    if cfg.RandomRoute {
        r := fmt.Sprintf("%06x", rand.Intn(0xFFFFFF))
        if cfg.RoutePrefix=="" {
            cfg.RoutePrefix = "/" + r
        }
        // store random value for display
        cfg.RoutePrefix = "/" + r // override for simplicity
    }

    if cfg.Mkdir && !cfg.UploadEnabled {
        fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --upload-files [<ALLOWED_UPLOAD_DIR>]\n\nUsage: miniserve --upload-files [<ALLOWED_UPLOAD_DIR>] --port <PORT> --mkdir <PATH>\n\nFor more information, try '--help'.\n")
        os.Exit(2)
    }

    return cfg
}

func parseFileAuth(path string) []*AuthEntry {
    var entries []*AuthEntry
    data, err := os.ReadFile(path)
    if err != nil { return entries }
    lines := strings.Split(string(data), "\n")
    for _, line := range lines {
        line = strings.TrimSpace(line)
        if line=="" { continue }
        if ent := parseAuth(line); ent != nil {
            entries = append(entries, ent)
        }
    }
    return entries
}

type MyHandler struct {
    Config *Config
}

func (h *MyHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    // route prefix handling
    effectivePath := r.URL.Path
    if h.Config.RoutePrefix != "" {
        rp := h.Config.RoutePrefix
        if effectivePath == rp {
            effectivePath = "/"
        } else if strings.HasPrefix(effectivePath, rp+"/") {
            effectivePath = effectivePath[len(rp):]
        } else {
            h.send404(w, r, effectivePath)
            return
        }
    }

    // auth
    if len(h.Config.Auth) > 0 {
        ah := r.Header.Get("Authorization")
        ok := false
        if strings.HasPrefix(strings.ToLower(ah), "basic ") {
            b64 := strings.TrimSpace(ah[6:])
            decBytes, err := base64.StdEncoding.DecodeString(b64)
            if err == nil {
                dec := string(decBytes)
                if idx := strings.Index(dec, ":"); idx != -1 {
                    u := dec[:idx]
                    p := dec[idx+1:]
                    for _, ent := range h.Config.Auth {
                        if ent.Username==u && checkAuth(ent, p) {
                            ok=true
                            break
                        }
                    }
                }
            }
        }
        if !ok {
            w.Header().Set("WWW-Authenticate","Basic")
            w.WriteHeader(401)
            return
        }
    }

    if strings.HasPrefix(effectivePath, "/__miniserve_internal/") {
        if effectivePath == "/__miniserve_internal/favicon.svg" {
            w.Header().Set("Content-Type","image/svg+xml")
            w.Write([]byte(faviconSVG))
            return
        } else if effectivePath == "/__miniserve_internal/style.css" {
            w.Header().Set("Content-Type","text/css; charset=utf-8")
            w.Write([]byte(styleCSS))
            return
        } else {
            h.send404(w, r, effectivePath)
            return
        }
    }

    // Serve file or dir
    servePath := h.Config.ServePath
    var fsPath string
    if effectivePath=="/" {
        fsPath = servePath
    } else {
        // clean path
        cleaned := path.Clean(effectivePath)
        // prevent traversal
        // join
        fsPath = filepath.Join(servePath, strings.TrimPrefix(cleaned, "/"))
    }

    // No symlinks check
    if h.Config.NoSymlinks {
        if fi, err := os.Lstat(fsPath); err==nil {
            if fi.Mode() & os.ModeSymlink != 0 {
                h.send404(w, r, effectivePath)
                return
            }
        }
    }

    // Check file outside servePath
    absServe, _ := filepath.Abs(servePath)
    absFs, _ := filepath.Abs(fsPath)
    if !strings.HasPrefix(absFs, absServe) && !h.Config.ServeIsFile {
        h.send404(w, r, effectivePath)
        return
    }

    fi, err := os.Stat(fsPath)
    if err != nil {
        // try pretty urls
        if h.Config.PrettyUrls {
            cand := fsPath + ".html"
            if f2, err2 := os.Stat(cand); err2==nil && !f2.IsDir() {
                h.serveFile(w, r, cand)
                return
            }
        }
        h.send404(w, r, effectivePath)
        return
    }

    if !fi.IsDir() {
        h.serveFile(w, r, fsPath)
        return
    }

    // dir
    // download
    if dl := r.URL.Query().Get("download"); dl != "" {
        if dl=="tar" && h.Config.EnableTar {
            // TODO implement tar
        }
        if dl=="tar_gz" && h.Config.EnableTarGz {
            // TODO
        }
        if dl=="zip" && h.Config.EnableZip {
            // TODO
        }
    }

    // index file
    if h.Config.Index != "" {
        idxPath := filepath.Join(fsPath, h.Config.Index)
        if f, err := os.Stat(idxPath); err==nil && !f.IsDir() {
            h.serveFile(w, r, idxPath)
            return
        }
    }

    if h.Config.DisableIndex {
        h.send404(w, r, effectivePath)
        return
    }

    if !strings.HasSuffix(effectivePath, "/") {
        // redirect
        newPath := effectivePath + "/"
        if r.URL.RawQuery != "" {
            newPath += "?" + r.URL.RawQuery
        }
        if h.Config.RoutePrefix != "" {
            newPath = h.Config.RoutePrefix + newPath
        }
        http.Redirect(w, r, newPath, 301)
        return
    }

    h.serveDirectory(w, r, fsPath, effectivePath)
}

func (h *MyHandler) serveFile(w http.ResponseWriter, r *http.Request, fsPath string) {
    f, err := os.Open(fsPath)
    if err != nil {
        h.send404(w, r, fsPath)
        return
    }
    defer f.Close()
    fi, err := f.Stat()
    if err != nil {
        h.send404(w, r, fsPath)
        return
    }

    // ETag handling
    modTime := fi.ModTime()
    etag := fmt.Sprintf("\"%x:%x\"", modTime.Unix(), fi.Size())
    if match := r.Header.Get("If-None-Match"); match != "" {
        if strings.Trim(match, "\"") == strings.Trim(etag, "\"") || match==etag {
            w.WriteHeader(304)
            return
        }
    }

    // Range
    // Use http.ServeContent which handles range and etag etc
    w.Header().Set("Content-Type", mime.TypeByExtension(filepath.Ext(fsPath)))
    if w.Header().Get("Content-Type")=="" {
        w.Header().Set("Content-Type", "application/octet-stream")
    }
    // Content disposition
    // For hidden dot files, attachment
    disp := "inline"
    if strings.HasPrefix(filepath.Base(fsPath), ".") {
        disp = "attachment"
    }
    w.Header().Set("Content-Disposition", fmt.Sprintf("%s; filename=\"%s\"", disp, filepath.Base(fsPath)))
    for _, hdr := range h.Config.Headers {
        if idx := strings.Index(hdr, ":"); idx != -1 {
            k := strings.TrimSpace(hdr[:idx])
            v := strings.TrimSpace(hdr[idx+1:])
            if w.Header().Get(k)=="" {
                w.Header().Set(k, v)
            }
        }
    }
    http.ServeContent(w, r, filepath.Base(fsPath), modTime, f)
}

func (h *MyHandler) serveDirectory(w http.ResponseWriter, r *http.Request, fsPath string, effectivePath string) {
    // List entries
    dirEntries, err := os.ReadDir(fsPath)
    if err != nil {
        h.send404(w, r, effectivePath)
        return
    }

    type Entry struct {
        Name string
        IsDir bool
        Size int64
        ModTime time.Time
    }
    var entries []Entry
    for _, de := range dirEntries {
        name := de.Name()
        if !h.Config.Hidden && strings.HasPrefix(name, ".") {
            continue
        }
        if h.Config.NoSymlinks {
            if fi, err := de.Info(); err==nil {
                // check symlink
                if fi.Mode() & os.ModeSymlink != 0 {
                    continue
                }
            }
            // Lstat
            if fi, err := os.Lstat(filepath.Join(fsPath, name)); err==nil {
                if fi.Mode() & os.ModeSymlink != 0 {
                    continue
                }
            }
        }
        fi, err := de.Info()
        if err != nil { continue }
        isDir := fi.IsDir()
        size := fi.Size()
        if isDir {
            size = 0
        }
        entries = append(entries, Entry{Name: name, IsDir: isDir, Size: size, ModTime: fi.ModTime()})
    }

    // Sorting
    sortMethod := r.URL.Query().Get("sort")
    if sortMethod=="" {
        sortMethod = h.Config.SortingMethod
    }
    sortOrder := r.URL.Query().Get("order")
    if sortOrder=="" {
        sortOrder = h.Config.SortingOrder
    }

    sort.Slice(entries, func(i, j int) bool {
        if h.Config.DirsFirst {
            if entries[i].IsDir != entries[j].IsDir {
                return entries[i].IsDir
            }
        }
        var less bool
        if sortMethod=="size" {
            less = entries[i].Size < entries[j].Size
        } else if sortMethod=="date" {
            less = entries[i].ModTime.Before(entries[j].ModTime)
        } else {
            less = strings.ToLower(entries[i].Name) < strings.ToLower(entries[j].Name)
        }
        if sortOrder=="desc" {
            return !less
        }
        return less
    })

    hostDisplay := h.Config.Title
    if hostDisplay=="" {
        hostDisplay = r.Host
        if hostDisplay=="" {
            hostDisplay = fmt.Sprintf("127.0.0.1:%d", h.Config.Port)
        }
    }

    rp := h.Config.RoutePrefix

    // breadcrumb
    trimmed := strings.Trim(effectivePath, "/")
    var breadcrumb string
    if trimmed=="" {
        breadcrumb = fmt.Sprintf("<span><bdi>%s</bdi></span>/", html.EscapeString(hostDisplay))
    } else {
        parts := strings.Split(trimmed, "/")
        breadcrumb = fmt.Sprintf("<a href=\"%s/\"><bdi>%s</bdi></a>/", rp, html.EscapeString(hostDisplay))
        for i, part := range parts {
            isLast := i==len(parts)-1
            up := "/" + strings.Join(parts[:i+1], "/") + "/"
            href := rp + up
            if isLast {
                breadcrumb += fmt.Sprintf("<span><bdi>%s</bdi></span>/", html.EscapeString(part))
            } else {
                breadcrumb += fmt.Sprintf("<a href=\"%s\"><bdi>%s</bdi></a>/", href, html.EscapeString(part))
            }
        }
    }

    var rows strings.Builder
    if effectivePath != "/" {
        trimmed2 := strings.TrimSuffix(effectivePath, "/")
        parent := path.Dir(trimmed2)
        if parent=="." || parent=="" {
            parent="/"
        }
        if !strings.HasSuffix(parent, "/") {
            parent+="/"
        }
        parentHref := rp + parent
        // preserve sort query?
        if r.URL.RawQuery != "" {
            // check if sort param present
            if strings.Contains(r.URL.RawQuery, "sort=") {
                parentHref += "?" + r.URL.RawQuery
            }
        }
        rows.WriteString(fmt.Sprintf("<tr><td colspan=\"3\"><p><span class=\"root-chevron\">◂</span><a class=\"root\" href=\"%s\">Parent directory</a></p></td></tr>", parentHref))
    }

    for _, e := range entries {
        var href string
        if e.IsDir {
            if effectivePath=="/" {
                href = "/" + e.Name + "/"
            } else {
                href = effective_path + e.Name + "/"
            }
        } else {
            if effectivePath=="/" {
                href = "/" + e.Name
            } else {
                href = effective_path + e.Name
            }
            if h.Config.ExternalURL != "" && !e.IsDir {
                href = strings.TrimSuffix(h.Config.ExternalURL, "/") + href
            }
        }
        if rp != "" && !(h.Config.ExternalURL != "" && !e.IsDir) {
            href = rp + href
        }
        // size
        var sizeDisp string
        if !e.IsDir {
            if h.Config.SizeDisplay=="exact" {
                sizeDisp = fmt.Sprintf("%d B", e.Size)
            } else {
                sizeDisp = fmt.Sprintf("%d B", e.Size)
            }
        }
        modStr := e.ModTime.Format("2006-01-02 15:04:05 -07:00")
        rel := relativeTime(e.ModTime)
        if e.IsDir {
            rows.WriteString(fmt.Sprintf("<tr class=\"entry-type-directory\"><td><p><a class=\"directory\" href=\"%s\">%s/</a></p></td><td class=\"size-cell\"></td><td class=\"date-cell\"><span>%s </span><span class=\"history\">%s</span></td></tr>", html.EscapeString(href), html.EscapeString(e.Name), modStr, rel))
        } else {
            rows.WriteString(fmt.Sprintf("<tr class=\"entry-type-file\"><td><p><a class=\"file\" href=\"%s\">%s</a><span class=\"mobile-info size\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=size&amp;order=asc\" title=\"Sort by size in ascending order\">%s</a></span></span></p></td><td class=\"size-cell\">%s</td><td class=\"date-cell\"><span>%s </span><span class=\"history\">%s</span></td></tr>", html.EscapeString(href), html.EscapeString(e.Name), sizeDisp, sizeDisp, modStr, rel))
        }
    }

    versionFooter := ""
    if !h.Config.HideVersion {
        versionFooter = fmt.Sprintf("<div class=\"version\"><a href=\"https://github.com/svenstaro/miniserve\">miniserve</a>/%s</div>", VERSION)
    }
    nav := "<nav><div><p>Change theme...</p><ul class=\"theme\"><li data-theme=\"default\"><a href=\"javascript:updateColorScheme(&quot;default&quot;)\" title=\"Switch to Default (light/dark) theme\">Default (light/dark)</a></li><li data-theme=\"squirrel\"><a href=\"javascript:updateColorScheme(&quot;squirrel&quot;)\" title=\"Switch to Squirrel (light) theme\">Squirrel (light)</a></li><li data-theme=\"archlinux\"><a href=\"javascript:updateColorScheme(&quot;archlinux&quot;)\" title=\"Switch to Arch Linux (dark) theme\">Arch Linux (dark)</a></li><li data-theme=\"zenburn\"><a href=\"javascript:updateColorScheme(&quot;zenburn&quot;)\" title=\"Switch to Zenburn (dark) theme\">Zenburn (dark)</a></li><li data-theme=\"monokai\"><a href=\"javascript:updateColorScheme(&quot;monokai&quot;)\" title=\"Switch to Monokai (dark) theme\">Monokai (dark)</a></li></ul></div></nav>"
    tableHeader := "<table><thead><th class=\"name\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=name&amp;order=asc\" title=\"Sort by name in ascending order\">Name</a></span></th><th class=\"size\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=size&amp;order=asc\" title=\"Sort by size in ascending order\">Size</a></span></th><th class=\"date\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=date&amp;order=asc\" title=\"Sort by date in ascending order\">Last modification</a></span></th></thead><tbody>"

    pageTitle := hostDisplay
    if effectivePath != "/" {
        pageTitle = hostDisplay + strings.TrimSuffix(effectivePath, "/")
    }

    htmlDoc := fmt.Sprintf("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"color-scheme\" content=\"dark light\"><link rel=\"icon\" type=\"image/svg+xml\" href=\"%s/__miniserve_internal/favicon.svg\"><link rel=\"stylesheet\" href=\"%s/__miniserve_internal/style.css\"><title>%s</title><script>function updateColorScheme(name){if(name&&name!=\"default\"){localStorage.setItem('theme',name);document.body.setAttribute('data-theme',name)}else{localStorage.removeItem('theme');document.body.removeAttribute('data-theme')}}function loadColorScheme(){var name=localStorage.getItem('theme');updateColorScheme(name);}addEventListener('load',loadColorScheme);addEventListener('storage',loadColorScheme);</script><script>const API_ROUTE = '%s/__miniserve_internal/api'; let dirSizeCache = {}; function fetchDirSize(dir){return fetch(API_ROUTE,{headers:{'Accept':'application/json','Content-Type':'application/json'},method:'POST',body:JSON.stringify({DirSize:dir})}).then(resp=>resp.ok?resp.text():\"~\")}function updateSizeCells(){const directoryCells=document.querySelectorAll('tr.entry-type-directory .size-cell');directoryCells.forEach(cell=>{const href=cell.parentNode.querySelector('a').href;const target=new URL(href).pathname;if(target in dirSizeCache){cell.dataset.size=dirSizeCache[target];}else{fetchDirSize(target).then(dir_size=>{cell.dataset.size=dir_size;dirSizeCache[target]=dir_size;}).catch(error=>console.error(\"Error fetching dir size:\",error));}})}setInterval(updateSizeCells,1000);</script></head><body id=\"drop-container\"><div class=\"toolbar_box_group\"></div>%s<div class=\"container\"><span id=\"top\"></span><h1 class=\"title\" dir=\"ltr\">%s</h1><div class=\"toolbar\"><div class=\"toolbar_box_group\"></div></div>%s%s</tbody></table><a class=\"back\" href=\"#top\">⇪</a><div class=\"footer\">%s</div></div></body></html>", rp, rp, html.EscapeString(pageTitle), rp, nav, breadcrumb, tableHeader, rows.String(), versionFooter)

    w.Header().Set("Content-Type","text/html; charset=utf-8")
    w.WriteHeader(200)
    w.Write([]byte(htmlDoc))
}

func (h *MyHandler) send404(w http.ResponseWriter, r *http.Request, effectivePath string) {
    rp := h.Config.RoutePrefix
    footer := ""
    if !h.Config.HideVersion {
        footer = fmt.Sprintf("<div class=\"version\"><a href=\"https://github.com/svenstaro/miniserve\">miniserve</a>/%s</div>", VERSION)
    }
    root := "/"
    if rp != "" {
        root = rp
    }
    htmlDoc := fmt.Sprintf("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>404 Not Found</title><link rel=\"icon\" type=\"image/svg+xml\" href=\"%s/__miniserve_internal/favicon.svg\"><link rel=\"stylesheet\" href=\"%s/__miniserve_internal/style.css\"></head><body><div class=\"error\"><p>404 Not Found</p><p>Route %s could not be found</p><div class=\"error-nav\"><a class=\"error-back\" href=\"%s\">Go back to file listing</a></div><p class=\"footer\">%s</p></div></body></html>", rp, rp, html.EscapeString(effectivePath), root, footer)
    w.Header().Set("Content-Type","text/html")
    w.WriteHeader(404)
    w.Write([]byte(htmlDoc))
}

func relativeTime(t time.Time) string {
    diff := time.Since(t)
    secs := int(diff.Seconds())
    if secs < 10 {
        return "now"
    } else if secs < 60 {
        return fmt.Sprintf("%d seconds ago", secs)
    } else if secs < 120 {
        return "a minute ago"
    } else if secs < 3600 {
        return fmt.Sprintf("%d minutes ago", secs/60)
    } else if secs < 7200 {
        return "an hour ago"
    } else if secs < 86400 {
        return fmt.Sprintf("%d hours ago", secs/3600)
    } else if secs < 172800 {
        return "a day ago"
    } else {
        return fmt.Sprintf("%d days ago", secs/86400)
    }
}
