        fmt.Printf("%s [INFO] Actix runtime found; starting in Actix runtime\n", now)
        if cfg.Interfaces == "" {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-[::]:%d\", workers: 20, listening on: [::]:%d\n", now, cfg.Port, cfg.Port)
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-0.0.0.0:%d\", workers: 20, listening on: 0.0.0.0:%d\n", now, cfg.Port, cfg.Port)
        } else {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-%s:%d\", workers: 20, listening on: %s:%d\n", now, cfg.Interfaces, cfg.Port, cfg.Interfaces, cfg.Port)
        }
    }

    // Setup handler
    handler := &MyHandler{Config: cfg}

    bindAddr := fmt.Sprintf("0.0.0.0:%d", cfg.Port)
    if cfg.Interfaces != "" {
        bindAddr = fmt.Sprintf("%s:%d", strings.Split(cfg.Interfaces, ",")[0], cfg.Port)
    }

    listener, err := net.Listen("tcp", bindAddr)
    if err != nil {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to bind server to %s\n", now, bindAddr)
        fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: %s\n", now, err)
        fmt.Fprintf(os.Stderr, "Error: Failed to bind server to %s\ncaused by: %s\n", bindAddr, err)
        os.Exit(1)
    }
    fmt.Printf("Listening on %s\n", bindAddr)
    http.Serve(listener, handler)
}

func parseArgs(argv []string) *Config {
    cfg := &Config{
        Port: 8080,
        SortingMethod: "name",
        SortingOrder: "desc",
        SizeDisplay: "human",
        OnDuplicate: "error",
    }
    // env handling simplified: only PATH and PORT for now? We'll handle minimal
    if v := os.Getenv("MINISERVE_PATH"); v != "" && cfg.ServePath=="" {
        cfg.ServePath = v
    }
    if v := os.Getenv("MINISERVE_PORT"); v != "" {
        var p int
        fmt.Sscan(v, &p)
        cfg.Port = p
    }
    if v := os.Getenv("MINISERVE_VERBOSE"); v != "" {
        cfg.Verbose = true
    }
    if v := os.Getenv("MINISERVE_INDEX"); v != "" {
        cfg.Index = v
    }
    if v := os.Getenv("MINISERVE_SPA"); v != "" {
        cfg.Spa = true
    }
    if v := os.Getenv("MINISERVE_PRETTY_URLS"); v != "" {
        cfg.PrettyUrls = true
    }
    if v := os.Getenv("MINISERVE_INTERFACE"); v != "" {
        cfg.Interfaces = v
    }
    if v := os.Getenv("MINISERVE_AUTH"); v != "" {
        if ent := parseAuth(v); ent != nil {
            cfg.Auth = append(cfg.Auth, ent)
        }
    }
    if v := os.Getenv("MINISERVE_ROUTE_PREFIX"); v != "" {
        cfg.RoutePrefix = v
    }
    if v := os.Getenv("MINISERVE_RANDOM_ROUTE"); v != "" {
        cfg.RandomRoute = true
    }
    if v := os.Getenv("MINISERVE_NO_SYMLINKS"); v != "" {
        cfg.NoSymlinks = true
    }
    if v := os.Getenv("MINISERVE_HIDDEN"); v != "" {
        cfg.Hidden = true
    }
    if v := os.Getenv("MINISERVE_QRCODE"); v != "" {
        cfg.QrCode = true
    }
    if v := os.Getenv("MINISERVE_README"); v != "" {
        cfg.Readme = true
    }
    // parse loop
    i:=1
    for i < len(argv) {
        tok := argv[i]
        if tok=="--" {
            if i+1 < len(argv) {
                if cfg.ServePath=="" {
                    cfg.ServePath = argv[i+1]
                } else {
                    fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n", argv[i+1], argv[i+1], argv[i+1])
                    os.Exit(2)
                }
            }
            break
        } else if tok=="-v" || tok=="--verbose" {
            cfg.Verbose=true
            i++
        } else if tok=="--index" {
            cfg.Index=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--index=") {
            cfg.Index=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="--spa" {
            cfg.Spa=true
            i++
        } else if tok=="--pretty-urls" {
            cfg.PrettyUrls=true
            i++
        } else if tok=="-p" || tok=="--port" {
            var v string
            if i+1>=len(argv) {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--port <PORT>' but none was supplied\n\nFor more information, try '--help'.\n")
                os.Exit(2)
            }
            v=argv[i+1]
            var pi int
            _, err := fmt.Sscan(v, &pi)
            if err != nil || pi<0 || pi>65535 {
                // check if invalid digit
                isDigit := true
                for _, ch := range v {
                    if ch<'0' || ch>'9' {
                        if !(ch=='-' && len(v)>0) {
                            isDigit=false
                        }
                    }
                }
                if !isDigit {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n", v)
                } else {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': %s is not in 0..=65535\n\nFor more information, try '--help'.\n", v, v)
                }
                os.Exit(2)
            }
            cfg.Port=pi
            i+=2
        } else if strings.HasPrefix(tok, "--port=") || strings.HasPrefix(tok, "-p=") {
            v:=strings.SplitN(tok,"=",2)[1]
            var pi int
            _, err := fmt.Sscan(v, &pi)
            if err != nil || pi<0 || pi>65535 {
                isDigit := true
                for _, ch := range v {
                    if ch<'0' || ch>'9' {
                        isDigit=false
                    }
                }
                if !isDigit {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n", v)
                } else {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': %s is not in 0..=65535\n\nFor more information, try '--help'.\n", v, v)
                }
                os.Exit(2)
            }
            cfg.Port=pi
            i++
        } else if tok=="-i" || tok=="--interfaces" {
            cfg.Interfaces=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--interfaces=") {
            cfg.Interfaces=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="-a" || tok=="--auth" {
            if ent := parseAuth(argv[i+1]); ent != nil {
                cfg.Auth = append(cfg.Auth, ent)
            }
            i+=2
        } else if strings.HasPrefix(tok, "--auth=") {
            if ent := parseAuth(strings.SplitN(tok,"=",2)[1]); ent != nil {
                cfg.Auth = append(cfg.Auth, ent)
            }
            i++
        } else if tok=="--auth-file" {
            cfg.Auth = append(cfg.Auth, parseFileAuth(argv[i+1])...)
            i+=2
        } else if strings.HasPrefix(tok, "--auth-file=") {
            cfg.Auth = append(cfg.Auth, parseFileAuth(strings.SplitN(tok,"=",2)[1])...)
            i++
        } else if tok=="--route-prefix" {
            cfg.RoutePrefix=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--route-prefix=") {
            cfg.RoutePrefix=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="--random-route" {
            cfg.RandomRoute=true
            i++
        } else if tok=="-P" || tok=="--no-symlinks" {
            cfg.NoSymlinks=true
            i++
        } else if tok=="-H" || tok=="--hidden" {
            cfg.Hidden=true
            i++
        } else if tok=="-S" || tok=="--default-sorting-method" {
            v:=argv[i+1]
            if v!="name" && v!="size" && v!="date" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-method <DEFAULT_SORTING_METHOD>'\n  [possible values: name, size, date]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingMethod=v
            i+=2
        } else if strings.HasPrefix(tok, "--default-sorting-method=") {
            v:=strings.SplitN(tok,"=",2)[1]
            if v!="name" && v!="size" && v!="date" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-method <DEFAULT_SORTING_METHOD>'\n  [possible values: name, size, date]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingMethod=v
            i++
        } else if tok=="-O" || tok=="--default-sorting-order" {
            v:=argv[i+1]
            if v!="asc" && v!="desc" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-order <DEFAULT_SORTING_ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingOrder=v
            i+=2
        } else if strings.HasPrefix(tok, "--default-sorting-order=") {
            v:=strings.SplitN(tok,"=",2)[1]
            if v!="asc" && v!="desc" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--default-sorting-order <DEFAULT_SORTING_ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.SortingOrder=v
            i++
        } else if tok=="-c" || tok=="--color-scheme" {
            v:=argv[i+1]
            if v!="squirrel" && v!="archlinux" && v!="zenburn" && v!="monokai" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--color-scheme <COLOR_SCHEME>'\n  [possible values: squirrel, archlinux, zenburn, monokai]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            cfg.Headers = append(cfg.Headers, v)
            i+=2
        } else if strings.HasPrefix(tok, "--color-scheme=") {
            v:=strings.SplitN(tok,"=",2)[1]
            if v!="squirrel" && v!="archlinux" && v!="zenburn" && v!="monokai" {
                fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--color-scheme <COLOR_SCHEME>'\n  [possible values: squirrel, archlinux, zenburn, monokai]\n\nFor more information, try '--help'.\n", v)
                os.Exit(2)
            }
            i++
        } else if tok=="-d" || tok=="--color-scheme-dark" {
            i+=2
        } else if strings.HasPrefix(tok, "--color-scheme-dark=") {
            i++
        } else if tok=="-q" || tok=="--qrcode" {
            cfg.QrCode=true
            i++
        } else if tok=="-u" || tok=="--upload-files" {
            cfg.UploadEnabled=true
            if i+1 < len(argv) && !strings.HasPrefix(argv[i+1], "-") {
                s := argv[i+1]
                cfg.AllowedUploadDir = &s
                i+=2
            } else {
                i++
            }
        } else if strings.HasPrefix(tok, "--upload-files=") {
            cfg.UploadEnabled=true
            s := strings.SplitN(tok,"=",2)[1]
            cfg.AllowedUploadDir = &s
            i++
        } else if tok=="-U" || tok=="--mkdir" {
            cfg.Mkdir=true
            i++
        } else if tok=="-r" || tok=="--enable-tar" {
            cfg.EnableTar=true
            i++
        } else if tok=="-g" || tok=="--enable-tar-gz" {
            cfg.EnableTarGz=true
            i++
        } else if tok=="-z" || tok=="--enable-zip" {
            cfg.EnableZip=true
            i++
        } else if tok=="-C" || tok=="--compress-response" {
            cfg.Compress=true
            i++
        } else if tok=="-D" || tok=="--dirs-first" {
            cfg.DirsFirst=true
            i++
        } else if tok=="-t" || tok=="--title" {
            cfg.Title=argv[i+1]
            i+=2
        } else if strings.HasPrefix(tok, "--title=") {
            cfg.Title=strings.SplitN(tok,"=",2)[1]
            i++
        } else if tok=="--header" {
            cfg.Headers = append(cfg.Headers, argv[i+1])
            i+=2
        } else if strings.HasPrefix(tok, "--header=") {
            cfg.Headers = append(cfg.Headers, strings.SplitN(tok,"=",2)[1])
            i++
        } else if tok=="-l" || tok=="--show-symlink-info" {
            cfg.SymlinkInfo=true
            i++
        } else if tok=="-F" || tok=="--hide-version-footer" {
            cfg.HideVersion=true
            i++
        } else if tok=="--hide-theme-selector" {
