                s := argv[i+1]
                cfg.AllowedRmDir = &s
                i+=2
            } else {
                i++
            }
        } else if len(tok)>11 && tok[:11]=="--rm-files=" {
            cfg.RmEnabled=true
            s := tok[11:]
            cfg.AllowedRmDir = &s
            i++
        } else if len(tok)>2 && tok[:3]=="--t" {
