type AuthEntry struct {
    Username string
    Type string
    Hash string
}

func parseAuth(s string) *AuthEntry {
    if s=="" { return nil }
    parts := strings.Split(s, ":")
    if len(parts)==1 {
        return &AuthEntry{Username: parts[0], Type: "", Hash: ""}
    } else if len(parts)==2 {
        return &AuthEntry{Username: parts[0], Type: "", Hash: parts[1]}
    } else if len(parts)==3 {
        if parts[1]!="sha256" && parts[1]!="sha512" { return nil }
        return &AuthEntry{Username: parts[0], Type: parts[1], Hash: parts[2]}
    } else {
        if parts[1]=="sha256" || parts[1]=="sha512" {
            return &AuthEntry{Username: parts[0], Type: parts[1], Hash: strings.Join(parts[2:], ":")}
        } else {
            return &AuthEntry{Username: parts[0], Type: "", Hash: strings.Join(parts[1:], ":")}
        }
    }
}

func checkAuth(ent *AuthEntry, pw string) bool {
    if ent.Type=="" {
        return ent.Hash==pw
    } else if ent.Type=="sha256" {
        h:=sha256.Sum256([]byte(pw))
        return hex.EncodeToString(h[:])==strings.ToLower(ent.Hash)
    } else if ent.Type=="sha512" {
        h:=sha512.Sum512([]byte(pw))
        return hex.EncodeToString(h[:])==strings.ToLower(ent.Hash)
    }
    return false
}

