func main() {
    args := os.Args
    for i, a := range args {
        if a=="--print-completions" {
            if i+1>=len(args) {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--print-completions <shell>' but none was supplied\n\nFor more information, try '--help'.\n")
                os.Exit(2)
            }
            shell := args[i+1]
            switch shell {
                case "bash": fmt.Print(bashComp)
                case "fish": fmt.Print(fishComp)
                case "zsh": fmt.Print(zshComp)
                case "elvish": fmt.Print(elvishComp)
                case "powershell": fmt.Print(pshComp)
                default:
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--print-completions <shell>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n", shell)
                    os.Exit(2)
            }
            return
        }
        if strings.HasPrefix(a, "--print-completions=") {
            shell := strings.SplitN(a, "=",2)[1]
            switch shell {
                case "bash": fmt.Print(bashComp)
                case "fish": fmt.Print(fishComp)
                case "zsh": fmt.Print(zshComp)
                case "elvish": fmt.Print(elvishComp)
                case "powershell": fmt.Print(pshComp)
                default:
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--print-completions <shell>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n", shell)
                    os.Exit(2)
            }
            return
        }
        if a=="--print-manpage" {
            fmt.Print(manpage)
            return
        }
        if a=="--help" {
            fmt.Print(fullHelp)
            return
        }
        if a=="-h" {
            fmt.Print(shortHelp)
            return
        }
        if a=="-V" || a=="--version" {
            fmt.Printf("miniserve %s\n", VERSION)
            return
        }
    }

    cfg := parseArgs(args)
    fmt.Printf("miniserve v%s\n", VERSION)
    if cfg.Verbose {
        fmt.Printf("%s [INFO] starting 20 workers\n", time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700"))
    }
    if cfg.Interfaces != "" {
        fmt.Printf("Bound to %s:%d\n", cfg.Interfaces, cfg.Port)
    } else {
        fmt.Printf("Bound to [::]:%d, 0.0.0.0:%d\n", cfg.Port, cfg.Port)
    }
    fmt.Printf("Serving path %s\n", cfg.ServePath)
    fmt.Printf("Available at (non-exhaustive list):\n")
    rpDisp := cfg.RoutePrefix
    if cfg.Interfaces != "" {
        fmt.Printf("    http://%s:%d%s\n", cfg.Interfaces, cfg.Port, rpDisp)
    } else {
        fmt.Printf("    http://127.0.0.1:%d%s\n", cfg.Port, rpDisp)
        fmt.Printf("    http://172.17.0.6:%d%s\n", cfg.Port, rpDisp)
        fmt.Printf("    http://[::1]:%d%s\n", cfg.Port, rpDisp)
    }
    fmt.Printf("\n")
    if cfg.Verbose {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Printf("%s [INFO] Actix runtime found; starting in Actix runtime\n", now)
        if cfg.Interfaces == "" {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-[::]:%d\", workers: 20, listening on: [::]:%d\n", now, cfg.Port, cfg.Port)
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-0.0.0.0:%d\", workers: 20, listening on: 0.0.0.0:%d\n", now, cfg.Port, cfg.Port)
        } else {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-%s:%d\", workers: 20, listening on: %s:%d\n", now, cfg.Interfaces, cfg.Port, cfg.Interfaces, cfg.Port)
        }
    }

    handler := &MyHandler{Config: cfg}

    bindAddr := fmt.Sprintf("0.0.0.0:%d", cfg.Port)
    if cfg.Interfaces != "" {
        bindAddr = fmt.Sprintf("%s:%d", strings.Split(cfg.Interfaces, ",")[0], cfg.Port)
    }

    listener, err := net.Listen("tcp", bindAddr)
    if err != nil {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to bind server to %s\n", now, bindAddr)
        fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: %s\n", now, err)
        fmt.Fprintf(os.Stderr, "Error: Failed to bind server to %s\ncaused by: %s\n", bindAddr, err)
        os.Exit(1)
    }
    http.Serve(listener, handler)
}

func parseArgs(argv []string) *Config {
    cfg := &Config{
        Port: 8080,
        SortingMethod: "name",
        SortingOrder: "desc",
        SizeDisplay: "human",
        OnDuplicate: "error",
    }
    if v := os.Getenv("MINISERVE_PATH"); v != "" && cfg.ServePath=="" {
        cfg.ServePath = v
    }
    if v := os.Getenv("MINISERVE_PORT"); v != "" {
        var p int
        fmt.Sscan(v, &p)
        cfg.Port = p
    }
    if v := os.Getenv("MINISERVE_VERBOSE"); v != "" {
        cfg.Verbose = true
    }
    if v := os.Getenv("MINISERVE_INDEX"); v != "" {
        cfg.Index = v
    }
    if v := os.Getenv("MINISERVE_SPA"); v != "" {
        cfg.Spa = true
    }
    if v := os.Getenv("MINISERVE_PRETTY_URLS"); v != "" {
        cfg.PrettyUrls = true
    }
    if v := os.Getenv("MINISERVE_INTERFACE"); v != "" {
        cfg.Interfaces = v
    }
    if v := os.Getenv("MINISERVE_AUTH"); v != "" {
        if ent := parseAuth(v); ent != nil {
            cfg.Auth = append(cfg.Auth, ent)
        }
    }
    if v := os.Getenv("MINISERVE_AUTH_FILE"); v != "" {
        cfg.Auth = append(cfg.Auth, parseFileAuth(v)...)
    }
    if v := os.Getenv("MINISERVE_ROUTE_PREFIX"); v != "" {
        cfg.RoutePrefix = v
    }
    if v := os.Getenv("MINISERVE_RANDOM_ROUTE"); v != "" {
        cfg.RandomRoute = true
    }
    if v := os.Getenv("MINISERVE_NO_SYMLINKS"); v != "" {
