    if v := os.Getenv("MINISERVE_DEFAULT_SORTING_ORDER"); v != "" {
        cfg.SortingOrder = v
    }
    if v := os.Getenv("MINISERVE_QRCODE"); v != "" {
        cfg.QrCode = true
    }
    if v := os.Getenv("MINISERVE_ALLOWED_UPLOAD_DIR"); v != "" {
        cfg.UploadEnabled = true
        s := v
        cfg.AllowedUploadDir = &s
    }
    if v := os.Getenv("MINISERVE_README"); v != "" {
        cfg.Readme = true
    }
    if v := os.Getenv("MINISERVE_DISABLE_INDEXING"); v != "" {
        cfg.DisableIndex = true
