    if v := os.Getenv("MINISERVE_FILE_EXTERNAL_URL"); v != "" {
        cfg.ExternalURL = v
    }
    if v := os.Getenv("MINISERVE_TITLE"); v != "" {
        cfg.Title = v
    }
    if v := os.Getenv("MINISERVE_HEADER"); v != "" {
        cfg.Headers = append(cfg.Headers, v)
    }

    i:=1
    for i < len(argv) {
        tok := argv[i]
        if tok=="--" {
            if i+1 < len(argv) {
                if cfg.ServePath=="" {
                    cfg.ServePath = argv[i+1]
                } else {
                    fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n", argv[i+1], argv[i+1], argv[i+1])
                    os.Exit(2)
                }
            }
            break
        } else if tok=="-v" || tok=="--verbose" {
            cfg.Verbose=true
            i++
        } else if tok=="--temp-directory" {
            if i+1>=len(argv) {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--temp-directory <TEMP_UPLOAD_DIRECTORY>' but none was supplied\n\nFor more information, try '--help'.\n")
