            v:=argv[i+1]
            var pi int
            _, err := fmt.Sscan(v, &pi)
            if err != nil || pi<0 || pi>65535 {
                isDigit := true
                for _, ch := range v {
                    if (ch<'0' || ch>'9') && ch!='-' {
                        isDigit=false
                        break
                    }
                }
                // For port, check if dash present, treat as not in range? Original for 99999 says not in 0..=65535, not invalid digit. For notanumber, invalid digit.
                if !isDigit || strings.ContainsAny(v, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ") {
                    fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n", v)
                } else {
