    }
    if cfg.Interfaces != "" {
        fmt.Printf("Bound to %s:%d\n", cfg.Interfaces, cfg.Port)
    } else {
        fmt.Printf("Bound to [::]:%d, 0.0.0.0:%d\n", cfg.Port, cfg.Port)
    }
    fmt.Printf("Serving path %s\n", cfg.ServePath)
    fmt.Printf("Available at (non-exhaustive list):\n")
    rpDisp := cfg.RoutePrefix
    if cfg.Interfaces != "" {
        fmt.Printf("    http://%s:%d%s\n", cfg.Interfaces, cfg.Port, rpDisp)
    } else {
        fmt.Printf("    http://127.0.0.1:%d%s\n", cfg.Port, rpDisp)
        fmt.Printf("    http://172.17.0.6:%d%s\n", cfg.Port, rpDisp)
        fmt.Printf("    http://[::1]:%d%s\n", cfg.Port, rpDisp)
    }
    fmt.Printf("\n")
    if cfg.Verbose {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Printf("%s [INFO] Actix runtime found; starting in Actix runtime\n", now)
        if cfg.Interfaces == "" {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-[::]:%d\", workers: 20, listening on: [::]:%d\n", now, cfg.Port, cfg.Port)
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-0.0.0.0:%d\", workers: 20, listening on: 0.0.0.0:%d\n", now, cfg.Port, cfg.Port)
        } else {
            fmt.Printf("%s [INFO] starting service: \"actix-web-service-%s:%d\", workers: 20, listening on: %s:%d\n", now, cfg.Interfaces, cfg.Port, cfg.Interfaces, cfg.Port)
        }
    }

    handler := &MyHandler{Config: cfg}

    bindAddr := fmt.Sprintf("0.0.0.0:%d", cfg.Port)
    if cfg.Interfaces != "" {
        bindAddr = fmt.Sprintf("%s:%d", strings.Split(cfg.Interfaces, ",")[0], cfg.Port)
    }

    listener, err := net.Listen("tcp", bindAddr)
    if err != nil {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to bind server to %s\n", now, bindAddr)
        fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: %s\n", now, err)
        fmt.Fprintf(os.Stderr, "Error: Failed to bind server to %s\ncaused by: %s\n", bindAddr, err)
        os.Exit(1)
    }
    http.Serve(listener, handler)
}

func parseArgs(argv []string) *Config {
    cfg := &Config{
        Port: 8080,
        SortingMethod: "name",
        SortingOrder: "desc",
        SizeDisplay: "human",
        OnDuplicate: "error",
    }
    // env
    if v := os.Getenv("MINISERVE_PATH"); v != "" && cfg.ServePath=="" {
        cfg.ServePath = v
    }
    if v := os.Getenv("MINISERVE_PORT"); v != "" {
        var p int
        fmt.Sscan(v, &p)
        cfg.Port = p
    }
    if v := os.Getenv("MINISERVE_VERBOSE"); v != "" {
        cfg.Verbose = true
    }
    if v := os.Getenv("MINISERVE_INDEX"); v != "" { cfg.Index = v }
    if v := os.Getenv("MINISERVE_SPA"); v != "" { cfg.Spa = true }
    if v := os.Getenv("MINISERVE_PRETTY_URLS"); v != "" { cfg.PrettyUrls = true }
    if v := os.Getenv("MINISERVE_INTERFACE"); v != "" { cfg.Interfaces = v }
    if v := os.Getenv("MINISERVE_AUTH"); v != "" {
        if ent := parseAuth(v); ent != nil { cfg.Auth = append(cfg.Auth, ent) }
    }
    if v := os.Getenv("MINISERVE_AUTH_FILE"); v != "" {
        cfg.Auth = append(cfg.Auth, parseFileAuth(v)...)
    }
    if v := os.Getenv("MINISERVE_ROUTE_PREFIX"); v != "" { cfg.RoutePrefix = v }
    if v := os.Getenv("MINISERVE_RANDOM_ROUTE"); v != "" { cfg.RandomRoute = true }
    if v := os.Getenv("MINISERVE_NO_SYMLINKS"); v != "" { cfg.NoSymlinks = true }
    if v := os.Getenv("MINISERVE_HIDDEN"); v != "" { cfg.Hidden = true }
    if v := os.Getenv("MINISERVE_DEFAULT_SORTING_METHOD"); v != "" { cfg.SortingMethod = v }
    if v := os.Getenv("MINISERVE_DEFAULT_SORTING_ORDER"); v != "" { cfg.SortingOrder = v }
    if v := os.Getenv("MINISERVE_QRCODE"); v != "" { cfg.QrCode = true }
    if v := os.Getenv("MINISERVE_ALLOWED_UPLOAD_DIR"); v != "" {
        cfg.UploadEnabled = true
        s := v
        cfg.AllowedUploadDir = &s
    }
    if v := os.Getenv("MINISERVE_README"); v != "" { cfg.Readme = true }
    if v := os.Getenv("MINISERVE_DISABLE_INDEXING"); v != "" { cfg.DisableIndex = true }
    if v := os.Getenv("MINISERVE_ENABLE_WEBDAV"); v != "" { cfg.Webdav = true }
    if v := os.Getenv("MINISERVE_SIZE_DISPLAY"); v != "" { cfg.SizeDisplay = v }
    if v := os.Getenv("MINISERVE_FILE_EXTERNAL_URL"); v != "" { cfg.ExternalURL = v }
    if v := os.Getenv("MINISERVE_TITLE"); v != "" { cfg.Title = v }
    if v := os.Getenv("MINISERVE_HEADER"); v != "" { cfg.Headers = append(cfg.Headers, v) }
    if v := os.Getenv("MINISERVE_SHOW_SYMLINK_INFO"); v != "" { cfg.SymlinkInfo = true }
    if v := os.Getenv("MINISERVE_HIDE_VERSION_FOOTER"); v != "" { cfg.HideVersion = true }
    if v := os.Getenv("MINISERVE_HIDE_THEME_SELECTOR"); v != "" { cfg.HideTheme = true }
    if v := os.Getenv("MINISERVE_SHOW_WGET_FOOTER"); v != "" { cfg.WgetFooter = true }
    if v := os.Getenv("MINISERVE_ENABLE_TAR"); v != "" { cfg.EnableTar = true }
    if v := os.Getenv("MINISERVE_ENABLE_TAR_GZ"); v != "" { cfg.EnableTarGz = true }
    if v := os.Getenv("MINISERVE_ENABLE_ZIP"); v != "" { cfg.EnableZip = true }
    if v := os.Getenv("MINISERVE_COMPRESS_RESPONSE"); v != "" { cfg.Compress = true }
    if v := os.Getenv("MINISERVE_DIRS_FIRST"); v != "" { cfg.DirsFirst = true }

    i:=1
    for i < len(argv) {
        tok := argv[i]
        if tok=="--" {
            if i+1 < len(argv) {
                if cfg.ServePath=="" {
                    cfg.ServePath = argv[i+1]
                } else {
                    fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n", argv[i+1], argv[i+1], argv[i+1])
                    os.Exit(2)
                }
            }
            break
        } else if tok=="-v" || tok=="--verbose" {
            cfg.Verbose=true
            i++
        } else if tok=="--temp-directory" {
            if i+1>=len(argv) {
                fmt.Fprintf(os.Stderr, "error: a value is required for '--temp-directory <TEMP_UPLOAD_DIRECTORY>' but none was supplied\n\nFor more information, try '--help'.\n")
