                cfg.ServePath=tok
            } else {
                fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n", tok, tok, tok)
                os.Exit(2)
            }
            i++
        }
    }

    if cfg.ServePath=="" {
        fi, _ := os.Stdin.Stat()
        if (fi.Mode() & os.ModeCharDevice) == 0 {
            now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
            fmt.Fprintf(os.Stderr, "%s [ERROR] Refusing to start as no explicit serve path was set and no interactive terminal was attached\n", now)
            fmt.Fprintf(os.Stderr, "%s [ERROR] Please set an explicit serve path like: `miniserve /my/path`\n", now)
            fmt.Fprintf(os.Stderr, "Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached\nPlease set an explicit serve path like: `miniserve /my/path`\n")
            os.Exit(1)
        } else {
            wd, _ := os.Getwd()
            cfg.ServePath = wd
        }
    }

    absPath, err := filepath.Abs(cfg.ServePath)
    if err == nil {
        cfg.ServePath = absPath
    }
    if _, err := os.Stat(cfg.ServePath); err != nil {
        now := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
        fmt.Fprintf(os.Stderr, "%s [ERROR] Failed to resolve path to be served\n", now)
        fmt.Fprintf(os.Stderr, "%s [ERROR] caused by: No such file or directory (os error 2)\n", now)
        fmt.Fprintf(os.Stderr, "Error: Failed to resolve path to be served\ncaused by: No such file or directory (os error 2)\n")
        os.Exit(1)
    }
    if fi, err := os.Stat(cfg.ServePath); err==nil {
        cfg.ServeIsFile = !fi.IsDir()
    }

    if cfg.RoutePrefix != "" {
        rp := strings.TrimSpace(cfg.RoutePrefix)
        if !strings.HasPrefix(rp, "/") {
            rp = "/" + rp
        }
        rp = strings.TrimSuffix(rp, "/")
        if rp=="" {
            rp = "/"
        }
        cfg.RoutePrefix = rp
    }
    if cfg.RandomRoute {
        r := fmt.Sprintf("%06x", rand.Intn(0xFFFFFF))
        cfg.RoutePrefix = "/" + r
    }

    if cfg.Mkdir && !cfg.UploadEnabled {
        fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  --upload-files [<ALLOWED_UPLOAD_DIR>]\n\nUsage: miniserve --upload-files [<ALLOWED_UPLOAD_DIR>] --port <PORT> --mkdir <PATH>\n\nFor more information, try '--help'.\n")
        os.Exit(2)
    }

    return cfg
}

func parseFileAuth(path string) []*AuthEntry {
    var entries []*AuthEntry
    data, err := os.ReadFile(path)
    if err != nil { return entries }
    lines := strings.Split(string(data), "\n")
    for _, line := range lines {
        line = strings.TrimSpace(line)
        if line=="" { continue }
        if ent := parseAuth(line); ent != nil {
            entries = append(entries, ent)
        }
    }
    return entries
}

type MyHandler struct {
    Config *Config
}

func (h *MyHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    effectivePath := r.URL.Path
    if h.Config.RoutePrefix != "" {
        rp := h.Config.RoutePrefix
        if effectivePath == rp {
            effectivePath = "/"
        } else if strings.HasPrefix(effectivePath, rp+"/") {
            effectivePath = effectivePath[len(rp):]
        } else {
            h.send404(w, r, effectivePath)
            return
        }
    }

    if len(h.Config.Auth) > 0 {
        ah := r.Header.Get("Authorization")
        ok := false
        if strings.HasPrefix(strings.ToLower(ah), "basic ") {
            b64 := strings.TrimSpace(ah[6:])
            decBytes, err := base64.StdEncoding.DecodeString(b64)
            if err == nil {
                dec := string(decBytes)
                if idx := strings.Index(dec, ":"); idx != -1 {
                    u := dec[:idx]
                    p := dec[idx+1:]
                    for _, ent := range h.Config.Auth {
                        if ent.Username==u && checkAuth(ent, p) {
                            ok=true
                            break
                        }
                    }
                }
            }
        }
        if !ok {
            w.Header().Set("WWW-Authenticate","Basic")
            w.WriteHeader(401)
            return
        }
    }

    if strings.HasPrefix(effectivePath, "/__miniserve_internal/") {
        if effectivePath == "/__miniserve_internal/favicon.svg" {
            w.Header().Set("Content-Type","image/svg+xml")
            w.Write([]byte(faviconSVG))
            return
        } else if effectivePath == "/__miniserve_internal/style.css" {
            w.Header().Set("Content-Type","text/css; charset=utf-8")
            w.Write([]byte(styleCSS))
            return
        } else if effectivePath == "/__miniserve_internal/api" {
            if r.Method=="POST" {
                bodyBytes, _ := io.ReadAll(r.Body)
                var j map[string]interface{}
                if err := json.Unmarshal(bodyBytes, &j); err==nil {
                    if dirVal, ok := j["DirSize"].(string); ok {
                        if h.Config.DirSize {
                            sz := h.calcDirSize(dirVal)
                            w.Write([]byte(fmt.Sprintf("%d B", sz)))
                            return
                        }
                    }
                }
                w.WriteHeader(404)
                return
            }
            w.WriteHeader(404)
            return
        } else {
            h.send404(w, r, effectivePath)
            return
        }
    }

    // upload
    if strings.HasPrefix(effectivePath, "/upload") && r.Method=="POST" {
        upParam := r.URL.Query().Get("path")
        if upParam=="" { upParam="/" }
        if !h.Config.UploadEnabled {
            w.WriteHeader(403)
            return
        }
        if h.Config.AllowedUploadDir != nil {
            allowed := *h.Config.AllowedUploadDir
            defNorm := func(p string) string {
                if strings.HasSuffix(p, "/") { return p }
                return p+"/"
            }
            if upParam != allowed && !strings.HasPrefix(defNorm(upParam), defNorm(allowed)) && allowed!="/" {
                w.WriteHeader(403)
                w.Write([]byte("Upload not allowed to this directory"))
                return
            }
        }
        err := r.ParseMultipartForm(32 << 20)
        if err != nil {
            w.WriteHeader(400)
            return
        }
        if mkdirVals, ok := r.MultipartForm.Value["mkdir"]; ok && len(mkdirVals)>0 && h.Config.Mkdir {
            dname := mkdirVals[0]
            if dname=="" || strings.Contains(dname, "/") || strings.Contains(dname, "..") {
                w.WriteHeader(400)
                return
            }
            targetDir := h.resolveFs(upParam)
            newDir := filepath.Join(targetDir, dname)
            if err := os.Mkdir(newDir, 0755); err != nil {
                w.WriteHeader(500)
                return
            }
            rp := h.Config.RoutePrefix
            loc := upParam
            if !strings.HasPrefix(loc, "/") { loc = "/" + loc }
            loc = rp + loc
            http.Redirect(w, r, loc, 303)
            return
        }
        for _, fileHeaders := range r.MultipartForm.File {
            for _, fh := range fileHeaders {
                f, err := fh.Open()
                if err != nil { continue }
                data, _ := io.ReadAll(f)
                f.Close()
                base := filepath.Base(fh.Filename)
                targetDir := h.resolveFs(upParam)
                if _, err := os.Stat(targetDir); err != nil {
                    w.WriteHeader(400)
                    w.Write([]byte(fmt.Sprintf("Invalid path\ncaused by: cannot upload file to %s, since it's not a directory", targetDir)))
                    return
                }
                dest := filepath.Join(targetDir, base)
                if h.Config.OnDuplicate=="error" {
                    if _, err := os.Stat(dest); err==nil {
                        w.WriteHeader(400)
                        return
                    }
                } else if h.Config.OnDuplicate=="rename" {
                    if _, err := os.Stat(dest); err==nil {
                        dest = h.genRename(targetDir, base)
                    }
                }
                if h.Config.TempDir != "" {
                    tmpFile, err := os.CreateTemp(h.Config.TempDir, "miniserve_tmp_*")
                    if err == nil {
                        tmpFile.Write(data)
                        tmpFile.Close()
                        os.Rename(tmpFile.Name(), dest)
                    } else {
                        os.WriteFile(dest, data, 0644)
                    }
                } else {
                    os.WriteFile(dest, data, 0644)
                }
                if h.Config.Chmod != "" {
                    if m, err := parseOctal(h.Config.Chmod); err==nil {
                        os.Chmod(dest, os.FileMode(m))
                    }
                }
            }
        }
        rp := h.Config.RoutePrefix
        loc := upParam
        if !strings.HasPrefix(loc, "/") { loc = "/" + loc }
        loc = rp + loc
        http.Redirect(w, r, loc, 303)
        return
    }

    if strings.HasPrefix(effectivePath, "/rm") && r.Method=="POST" {
        if !h.Config.RmEnabled {
            w.WriteHeader(403)
            return
        }
        rmParam := r.URL.Query().Get("path")
        if rmParam=="" { rmParam="/" }
        if h.Config.AllowedRmDir != nil {
            allowed := *h.Config.AllowedRmDir
            defNorm := func(p string) string {
                if strings.HasSuffix(p, "/") { return p }
                return p+"/"
            }
            if rmParam != allowed && !strings.HasPrefix(defNorm(rmParam), defNorm(allowed)) && allowed!="/" {
                w.WriteHeader(403)
                return
            }
        }
        target := h.resolveFs(rmParam)
        if _, err := os.Stat(target); err != nil {
            h.send404(w, r, effectivePath)
            return
        }
        if fi, err := os.Stat(target); err==nil {
            if fi.IsDir() {
                os.RemoveAll(target)
            } else {
                os.Remove(target)
            }
        }
        http.Redirect(w, r, "/", 303)
        return
    }

    servePath := h.Config.ServePath
    var fsPath string
    if effectivePath=="/" {
        fsPath = servePath
    } else {
        cleaned := path.Clean(effectivePath)
        fsPath = filepath.Join(servePath, strings.TrimPrefix(cleaned, "/"))
    }

    if h.Config.NoSymlinks {
        if fi, err := os.Lstat(fsPath); err==nil {
            if fi.Mode() & os.ModeSymlink != 0 {
                h.send404(w, r, effectivePath)
                return
            }
        }
    }

    fi, err := os.Stat(fsPath)
    if err != nil {
        if h.Config.PrettyUrls {
            cand := fsPath + ".html"
            if f2, err2 := os.Stat(cand); err2==nil && !f2.IsDir() {
                h.serveFile(w, r, cand)
                return
            }
        }
        if h.Config.Spa && h.Config.Index != "" {
            idxPath := filepath.Join(servePath, h.Config.Index)
            if _, err := os.Stat(idxPath); err==nil {
                h.serveFile(w, r, idxPath)
                return
            }
        }
        h.send404(w, r, effectivePath)
        return
    }

    if !fi.IsDir() {
        h.serveFile(w, r, fsPath)
        return
    }

    if dl := r.URL.Query().Get("download"); dl != "" {
        if dl=="tar" && h.Config.EnableTar {
            h.serveTar(w, r, fsPath, false)
            return
        }
        if dl=="tar_gz" && h.Config.EnableTarGz {
            h.serveTar(w, r, fsPath, true)
            return
        }
        if dl=="zip" && h.Config.EnableZip {
            h.serveZip(w, r, fsPath)
            return
        }
    }

    if h.Config.Index != "" {
        idxPath := filepath.Join(fsPath, h.Config.Index)
        if f, err := os.Stat(idxPath); err==nil && !f.IsDir() {
            h.serveFile(w, r, idxPath)
            return
        }
    }

    if h.Config.DisableIndex {
        h.send404FileNotFound(w, r, effectivePath)
        return
    }

    if !strings.HasSuffix(effectivePath, "/") {
        newPath := effectivePath + "/"
        if r.URL.RawQuery != "" {
            newPath += "?" + r.URL.RawQuery
        }
        if h.Config.RoutePrefix != "" {
            newPath = h.Config.RoutePrefix + newPath
        }
        http.Redirect(w, r, newPath, 301)
        return
    }

    h.serveDirectory(w, r, fsPath, effectivePath)
}

func (h *MyHandler) resolveFs(urlPath string) string {
    trimmed := strings.TrimPrefix(urlPath, "/")
    cleaned := path.Clean("/" + trimmed)
    trimmed = strings.TrimPrefix(cleaned, "/")
    parts := strings.Split(trimmed, "/")
    p := h.Config.ServePath
    for _, part := range parts {
        if part=="." || part=="" { continue }
        if part==".." {
            p = filepath.Dir(p)
            continue
        }
        p = filepath.Join(p, part)
    }
    return p
}

func (h *MyHandler) calcDirSize(urlPath string) int64 {
    fsPath := h.resolveFs(urlPath)
    var total int64
    filepath.Walk(fsPath, func(p string, info os.FileInfo, err error) error {
        if err != nil { return nil }
        if !h.Config.Hidden && strings.HasPrefix(info.Name(), ".") {
            if info.IsDir() {
                return filepath.SkipDir
            }
            return nil
        }
        if h.Config.NoSymlinks {
            if info.Mode() & os.ModeSymlink != 0 {
                if info.IsDir() {
                    return filepath.SkipDir
                }
                return nil
            }
        }
        if !info.IsDir() {
            total += info.Size()
        }
        return nil
    })
    return total
}

func (h *MyHandler) genRename(dir, base string) string {
    ext := filepath.Ext(base)
    stem := strings.TrimSuffix(base, ext)
    c:=1
    for {
        newName := fmt.Sprintf("%s-%d%s", stem, c, ext)
        newPath := filepath.Join(dir, newName)
        if _, err := os.Stat(newPath); err != nil {
            return newPath
        }
        c++
    }
}

func (h *MyHandler) serveFile(w http.ResponseWriter, r *http.Request, fsPath string) {
    f, err := os.Open(fsPath)
    if err != nil {
        h.send404(w, r, fsPath)
        return
    }
    defer f.Close()
    fi, _ := f.Stat()
    modTime := fi.ModTime()
    w.Header().Set("Content-Type", getMimeType(fsPath))
    disp := "inline"
    if strings.HasPrefix(filepath.Base(fsPath), ".") {
        disp = "attachment"
    }
    w.Header().Set("Content-Disposition", fmt.Sprintf("%s; filename=\"%s\"", disp, filepath.Base(fsPath)))
    for _, hdr := range h.Config.Headers {
        if idx := strings.Index(hdr, ":"); idx != -1 {
            k := strings.TrimSpace(hdr[:idx])
            v := strings.TrimSpace(hdr[idx+1:])
            if w.Header().Get(k)=="" {
                w.Header().Set(k,v)
            }
        }
    }
    http.ServeContent(w, r, filepath.Base(fsPath), modTime, f)
}

func (h *MyHandler) serveDirectory(w http.ResponseWriter, r *http.Request, fsPath string, effectivePath string) {
    dirEntries, _ := os.ReadDir(fsPath)
    type Ent struct {
        Name string
        IsDir bool
        Size int64
        ModTime time.Time
    }
    var ents []Ent
    for _, de := range dirEntries {
        name := de.Name()
        if !h.Config.Hidden && strings.HasPrefix(name, ".") { continue }
        if h.Config.NoSymlinks {
            if fi, err := os.Lstat(filepath.Join(fsPath, name)); err==nil {
                if fi.Mode() & os.ModeSymlink != 0 { continue }
            }
        }
        fi, _ := de.Info()
        isDir := fi.IsDir()
        sz := fi.Size()
        if isDir { sz=0 }
        ents = append(ents, Ent{Name: name, IsDir: isDir, Size: sz, ModTime: fi.ModTime()})
    }
    sortMethod := r.URL.Query().Get("sort")
    if sortMethod=="" { sortMethod = h.Config.SortingMethod }
    sortOrder := r.URL.Query().Get("order")
    if sortOrder=="" { sortOrder = h.Config.SortingOrder }
    sort.Slice(ents, func(i,j int) bool {
        if h.Config.DirsFirst {
            if ents[i].IsDir != ents[j].IsDir {
                return ents[i].IsDir
            }
        }
        var less bool
        if sortMethod=="size" {
            less = ents[i].Size < ents[j].Size
        } else if sortMethod=="date" {
            less = ents[i].ModTime.Before(ents[j].ModTime)
        } else {
            less = strings.ToLower(ents[i].Name) < strings.ToLower(ents[j].Name)
        }
        if sortOrder=="desc" { return !less }
        return less
    })
    hostDisplay := h.Config.Title
    if hostDisplay=="" {
        hostDisplay = r.Host
        if hostDisplay=="" {
            hostDisplay = fmt.Sprintf("127.0.0.1:%d", h.Config.Port)
        }
    }
    rp := h.Config.RoutePrefix
    trimmed := strings.Trim(effectivePath, "/")
    var breadcrumb string
    if trimmed=="" {
        breadcrumb = fmt.Sprintf("<span><bdi>%s</bdi></span>/", html.EscapeString(hostDisplay))
    } else {
        parts := strings.Split(trimmed, "/")
        breadcrumb = fmt.Sprintf("<a href=\"%s/\"><bdi>%s</bdi></a>/", rp, html.EscapeString(hostDisplay))
        for i, part := range parts {
            isLast := i==len(parts)-1
            up := "/" + strings.Join(parts[:i+1], "/") + "/"
            href := rp + up
            if isLast {
                breadcrumb += fmt.Sprintf("<span><bdi>%s</bdi></span>/", html.EscapeString(part))
            } else {
                breadcrumb += fmt.Sprintf("<a href=\"%s\"><bdi>%s</bdi></a>/", href, html.EscapeString(part))
            }
        }
    }
    var rows strings.Builder
    if effectivePath != "/" {
        trimmed2 := strings.TrimSuffix(effectivePath, "/")
        parent := path.Dir(trimmed2)
        if parent=="." || parent=="" { parent="/" }
        if !strings.HasSuffix(parent, "/") { parent+="/" }
        parentHref := rp + parent
        rows.WriteString(fmt.Sprintf("<tr><td colspan=\"3\"><p><span class=\"root-chevron\">◂</span><a class=\"root\" href=\"%s\">Parent directory</a></p></td></tr>", parentHref))
    }
    for _, e := range ents {
        var href string
        if e.IsDir {
            if effectivePath=="/" {
                href = "/" + e.Name + "/"
            } else {
                href = effectivePath + e.Name + "/"
            }
        } else {
            if effectivePath=="/" {
                href = "/" + e.Name
            } else {
                href = effectivePath + e.Name
            }
            if h.Config.ExternalURL != "" {
                href = strings.TrimSuffix(h.Config.ExternalURL, "/") + href
            }
        }
        if rp != "" && !(h.Config.ExternalURL != "" && !e.IsDir) {
            href = rp + href
        }
        var sizeDisp string
        if !e.IsDir {
            sizeDisp = fmt.Sprintf("%d B", e.Size)
        }
        modStr := e.ModTime.Format("2006-01-02 15:04:05 -07:00")
        rel := relativeTime(e.ModTime)
        if e.IsDir {
            rows.WriteString(fmt.Sprintf("<tr class=\"entry-type-directory\"><td><p><a class=\"directory\" href=\"%s\">%s/</a></p></td><td class=\"size-cell\"></td><td class=\"date-cell\"><span>%s </span><span class=\"history\">%s</span></td></tr>", html.EscapeString(href), html.EscapeString(e.Name), modStr, rel))
        } else {
            rows.WriteString(fmt.Sprintf("<tr class=\"entry-type-file\"><td><p><a class=\"file\" href=\"%s\">%s</a><span class=\"mobile-info size\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=size&amp;order=asc\" title=\"Sort by size in ascending order\">%s</a></span></span></p></td><td class=\"size-cell\">%s</td><td class=\"date-cell\"><span>%s </span><span class=\"history\">%s</span></td></tr>", html.EscapeString(href), html.EscapeString(e.Name), sizeDisp, sizeDisp, modStr, rel))
        }
    }
    versionFooter := ""
    if !h.Config.HideVersion {
        versionFooter = fmt.Sprintf("<div class=\"version\"><a href=\"https://github.com/svenstaro/miniserve\">miniserve</a>/%s</div>", VERSION)
    }
    nav := "<nav><div><p>Change theme...</p><ul class=\"theme\"><li data-theme=\"default\"><a href=\"javascript:updateColorScheme(&quot;default&quot;)\" title=\"Switch to Default (light/dark) theme\">Default (light/dark)</a></li><li data-theme=\"squirrel\"><a href=\"javascript:updateColorScheme(&quot;squirrel&quot;)\" title=\"Switch to Squirrel (light) theme\">Squirrel (light)</a></li><li data-theme=\"archlinux\"><a href=\"javascript:updateColorScheme(&quot;archlinux&quot;)\" title=\"Switch to Arch Linux (dark) theme\">Arch Linux (dark)</a></li><li data-theme=\"zenburn\"><a href=\"javascript:updateColorScheme(&quot;zenburn&quot;)\" title=\"Switch to Zenburn (dark) theme\">Zenburn (dark)</a></li><li data-theme=\"monokai\"><a href=\"javascript:updateColorScheme(&quot;monokai&quot;)\" title=\"Switch to Monokai (dark) theme\">Monokai (dark)</a></li></ul></div></nav>"
    tableHeader := "<table><thead><th class=\"name\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=name&amp;order=asc\" title=\"Sort by name in ascending order\">Name</a></span></th><th class=\"size\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=size&amp;order=asc\" title=\"Sort by size in ascending order\">Size</a></span></th><th class=\"date\"><span class=\"\"><span class=\"chevron\">▾</span><a href=\"?sort=date&amp;order=asc\" title=\"Sort by date in ascending order\">Last modification</a></span></th></thead><tbody>"

    pageTitle := hostDisplay
    if effectivePath != "/" {
        pageTitle = hostDisplay + strings.TrimSuffix(effectivePath, "/")
    }

    htmlDoc := fmt.Sprintf("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"color-scheme\" content=\"dark light\"><link rel=\"icon\" type=\"image/svg+xml\" href=\"%s/__miniserve_internal/favicon.svg\"><link rel=\"stylesheet\" href=\"%s/__miniserve_internal/style.css\"><title>%s</title><script>function updateColorScheme(name){if(name&&name!=\"default\"){localStorage.setItem('theme',name);document.body.setAttribute('data-theme',name)}else{localStorage.removeItem('theme');document.body.removeAttribute('data-theme')}}function loadColorScheme(){var name=localStorage.getItem('theme');updateColorScheme(name);}addEventListener('load',loadColorScheme);addEventListener('storage',loadColorScheme);</script><script>const API_ROUTE = '%s/__miniserve_internal/api'; let dirSizeCache = {}; function fetchDirSize(dir){return fetch(API_ROUTE,{headers:{'Accept':'application/json','Content-Type':'application/json'},method:'POST',body:JSON.stringify({DirSize:dir})}).then(resp=>resp.ok?resp.text():\"~\")}function updateSizeCells(){const directoryCells=document.querySelectorAll('tr.entry-type-directory .size-cell');directoryCells.forEach(cell=>{const href=cell.parentNode.querySelector('a').href;const target=new URL(href).pathname;if(target in dirSizeCache){cell.dataset.size=dirSizeCache[target];}else{fetchDirSize(target).then(dir_size=>{cell.dataset.size=dir_size;dirSizeCache[target]=dir_size;}).catch(error=>console.error(\"Error fetching dir size:\",error));}})}setInterval(updateSizeCells,1000);</script></head><body id=\"drop-container\"><div class=\"toolbar_box_group\"></div>%s<div class=\"container\"><span id=\"top\"></span><h1 class=\"title\" dir=\"ltr\">%s</h1><div class=\"toolbar\"><div class=\"toolbar_box_group\"></div></div>%s%s</tbody></table><a class=\"back\" href=\"#top\">⇪</a><div class=\"footer\">%s</div></div></body></html>", rp, rp, html.EscapeString(pageTitle), rp, nav, breadcrumb, tableHeader, rows.String(), versionFooter)
    w.Header().Set("Content-Type","text/html; charset=utf-8")
    w.WriteHeader(200)
    w.Write([]byte(htmlDoc))
}

func (h *MyHandler) send404(w http.ResponseWriter, r *http.Request, effectivePath string) {
    rp := h.Config.RoutePrefix
    footer := ""
    if !h.Config.HideVersion {
        footer = fmt.Sprintf("<div class=\"version\"><a href=\"https://github.com/svenstaro/miniserve\">miniserve</a>/%s</div>", VERSION)
    }
    root := "/"
    if rp != "" { root = rp }
