        return mt
    }
    return "application/octet-stream"
}

func relativeTime(t time.Time) string {
    diff := time.Since(t)
    secs := int(diff.Seconds())
    if secs < 10 {
        return "now"
    } else if secs < 60 {
        return fmt.Sprintf("%d seconds ago", secs)
    } else if secs < 120 {
        return "a minute ago"
    } else if secs < 3600 {
        return fmt.Sprintf("%d minutes ago", secs/60)
    } else if secs < 7200 {
        return "an hour ago"
    } else if secs < 86400 {
        return fmt.Sprintf("%d hours ago", secs/3600)
    } else if secs < 172800 {
        return "a day ago"
    } else {
        return fmt.Sprintf("%d days ago", secs/86400)
    }
}

func parseOctal(s string) (int64, error) {
    // parse octal
    v := strings.TrimPrefix(s, "0o")
    var res int64
    for _, ch := range v {
        if ch<'0' || ch>'7' {
            return 0, fmt.Errorf("invalid")
        }
        res = res*8 + int64(ch-'0')
    }
    return res, nil
}

func generateQR(url string) string {
    // simple placeholder QR
    // 27x27 with finder
    modules := [27][27]bool{}
    for _, pos := range [][2]int{{0,0},{0,20},{20,0}} {
        fx,fy := pos[0], pos[1]
        for y:=0; y<7; y++ {
            for x:=0; x<7; x++ {
                if x==0 || x==6 || y==0 || y==6 || (x>=2 && x<=4 && y>=2 && y<=4) {
                    modules[fy+y][fx+x]=true
                }
            }
        }
    }
    h := sha256.Sum256([]byte(url))
    bits := []bool{}
    for _, b := range h {
        for i:=0; i<8; i++ {
            bits = append(bits, (b>>i)&1==1)
        }
    }
    idx:=0
    for y:=0; y<27; y++ {
        for x:=0; x<27; x++ {
            if (x<8 && y<8) || (x>=19 && y<8) || (x<8 && y>=19) { continue }
            if x==6 || y==6 { continue }
            if bits[idx % len(bits)] {
                modules[y][x]=true
            }
            idx++
        }
    }
    var sb strings.Builder
    for y:=0; y<27; y++ {
        for x:=0; x<27; x++ {
            if modules[y][x] {
                sb.WriteString(fmt.Sprintf("M%d,%dh1v1h-1", x, y))
            }
        }
    }
    return fmt.Sprintf("<svg viewBox=\"0 0 27 27\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"27px\" height=\"27px\" fill=\"#ffffff\"/><path d=\"%s\"/></svg>", sb.String())
}

func renderMarkdown(md string) string {
    var out strings.Builder
    inP := false
    lines := strings.Split(md, "\n")
    for _, line := range lines {
        t := strings.TrimSpace(line)
        if t=="" {
            if inP {
                out.WriteString("</p>")
                inP=false
            }
            continue
        }
        if strings.HasPrefix(t, "# ") {
            if inP { out.WriteString("</p>"); inP=false }
            out.WriteString("<h1>" + html.EscapeString(strings.TrimPrefix(t, "# ")) + "</h1>")
        } else if strings.HasPrefix(t, "## ") {
            if inP { out.WriteString("</p>"); inP=false }
            out.WriteString("<h2>" + html.EscapeString(strings.TrimPrefix(t, "## ")) + "</h2>")
        } else if strings.HasPrefix(t, "### ") {
            if inP { out.WriteString("</p>"); inP=false }
            out.WriteString("<h3>" + html.EscapeString(strings.TrimPrefix(t, "### ")) + "</h3>")
        } else {
            if !inP {
                out.WriteString("<p>")
                inP=true
            } else {
                out.WriteString(" ")
            }
            out.WriteString(html.EscapeString(t))
        }
    }
    if inP { out.WriteString("</p>") }
    if out.Len()==0 {
        out.WriteString("<p>" + html.EscapeString(md) + "</p>")
    }
    return out.String()
}

func addCustomHeaders(w http.ResponseWriter, cfg *Config) {
    for _, hdr := range cfg.Headers {
        if idx := strings.Index(hdr, ":"); idx != -1 {
            k := strings.TrimSpace(hdr[:idx])
            v := strings.TrimSpace(hdr[idx+1:])
            if w.Header().Get(k) == "" {
                w.Header().Set(k, v)
            }
        }
    }
}
