func (h *MyHandler) serveDirectory(w http.ResponseWriter, r *http.Request, fsPath string, effectivePath string) {
    dirEntries, _ := os.ReadDir(fsPath)
    type Ent struct {
        Name string
        IsDir bool
        IsSymlink bool
        SymlinkTarget string
        Size int64
        ModTime time.Time
    }
    var ents []Ent
    for _, de := range dirEntries {
        name := de.Name()
        if !h.Config.Hidden && strings.HasPrefix(name, ".") { continue }
        if h.Config.NoSymlinks {
            if fi, err := os.Lstat(filepath.Join(fsPath, name)); err==nil {
                if fi.Mode() & os.ModeSymlink != 0 { continue }
            }
        }
        fi, _ := de.Info()
        isDir := fi.IsDir()
        isSymlink := false
        symlinkTarget := ""
        if fi.Mode() & os.ModeSymlink != 0 {
            isSymlink = true
            if h.Config.SymlinkInfo {
                if target, err := os.Readlink(filepath.Join(fsPath, name)); err==nil {
                    symlinkTarget = target
                }
            }
            // For size, follow symlink if possible
            if fi2, err := os.Stat(filepath.Join(fsPath, name)); err==nil {
                if !fi2.IsDir() {
                    // Use target size
                    fi = fi2
                }
            }
            // Check if symlink points to dir
            if fi.IsDir() {
                isDir = true
            }
        } else {
            // Also check if file is symlink via Lstat
            if lfi, err := os.Lstat(filepath.Join(fsPath, name)); err==nil {
